insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('saguaro-arizona', '12A', 'Saguaro National Park', 'United States', 'Two saguaro forests on either side of Tucson - the paved Cactus Forest Loop in the Rincon Mountain District, the gravel Bajada Loop and Signal Hill petroglyphs in the Tucson Mountain District - ringed by the Desert Museum, Mission San Xavier del Bac, Sabino Canyon, Mount Lemmon and the first UNESCO City of Gastronomy in the United States', 'future', 'verified', 'mountainValley', 'The Southwest Desert', '{"hiking","culinary","culture","family","adventure","parks"}', '{"dramatic","rugged","serene","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Cactus Forest Loop Drive (Rincon Mountain District, east)","source":"https://www.nps.gov/sagu/planyourvisit/gettingaround.htm","accessed":"2026-10-02","si":["senior","family","sports","romance"],"booking_route":"none needed - park entrance fee only","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an 8-mile paved scenic loop with \"several trailheads, scenic vistas and pullouts\"; open to bicycles but \"narrow with multiple tight turns and steep hills\"; highlighted by the NPS for sunset; no vehicles over 102 inches wide or 40 feet combined length"},{"name":"Bajada Loop Drive (Tucson Mountain District, west)","source":"https://www.nps.gov/sagu/planyourvisit/gettingaround.htm","accessed":"2026-10-02","si":["senior","family","adventure"],"booking_route":"none needed - park entrance fee only","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 6-mile unpaved, graded dirt loop with scenic pullouts, picnic areas and trailheads; bikes on the road only - \"Riding on trails around this loop is not permitted\""},{"name":"Signal Hill petroglyphs","source":"https://www.nps.gov/places/signal-hill.htm","accessed":"2026-10-02","si":["culture","family","hiking"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"on the Bajada Loop Drive, \"the best place to see petroglyphs within the park\", with a spiral petroglyph atop the Signal Hill Trail and a picnic area with shelters and grills; \"The trails from this area (including the short walk up to the petroglyphs) are not ADA accessible\""},{"name":"Valley View Overlook Nature Trail","source":"https://www.nps.gov/places/valley-view-overlook-nature-trail.htm","accessed":"2026-10-02","si":["hiking","family","senior","romance"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an easy 0.8 mile (1.3 km) round trip off the Bajada Loop, built by the Civilian Conservation Corps in the 1930s, ending on a ridge with benches looking over Avra Valley, Signal Hill and \"the jagged ridge of Picacho Peak to the north\""},{"name":"Desert Discovery Trail (west)","source":"https://www.nps.gov/sagu/planyourvisit/accessibility.htm","accessed":"2026-10-02","si":["senior","family"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 1/2-mile \"paved trail with exhibit signs\" with \"Pavement texturing and shade ramadas with resting benches\"; trail guides available in braille"},{"name":"Desert Ecology Trail and Mica View Trail (east)","source":"https://www.nps.gov/sagu/planyourvisit/accessibility.htm","accessed":"2026-10-02","si":["senior","family"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"two short accessible walks in the Rincon Mountain District: the 1/4-mile Desert Ecology Trail, \"paved trail has exhibits along the way\" with benches, and the 0.7-mile Mica View Trail on a \"hard-packed surface conducive to wheelchairs, walkers\" to the Broadway Trailhead"},{"name":"Rincon Mountain and Red Hills visitor centers and cactus gardens","source":"https://www.nps.gov/sagu/what-to-know-before-you-visit.htm","accessed":"2026-10-02","si":["family","senior","culture"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"one visitor center in each district, each with \"restrooms, water fountains, maps, hiking trails, a driving loop, programs, and staff\"; \"Water fountains are found at both visitor centers and only there\"; both have \"paved cactus garden paths\"; summer 8 am-4 pm, winter 9 am-5 pm"},{"name":"Freeman Homestead Trail (east)","source":"https://www.nps.gov/sagu/planyourvisit/saguaro_hiking.htm","accessed":"2026-10-02","si":["hiking","family","culture","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an easy 1-mile walk past a historic homestead site, a saguaro grove and a desert wash"},{"name":"Loma Verde Loop (east)","source":"https://www.nps.gov/sagu/planyourvisit/saguaro_hiking.htm","accessed":"2026-10-02","si":["hiking","family","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an easy 3.8-mile loop with 60 ft of elevation change, mesquite trees and overlook views"},{"name":"Hope Camp and Ridgeview Trail (east)","source":"https://www.nps.gov/sagu/planyourvisit/saguaro_hiking.htm","accessed":"2026-10-02","si":["hiking","sports","adventure"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a moderate 2-mile walk with 400 ft of gain, panoramic views and seasonal wildflowers; the Hope Camp Trail also runs 2.8 miles from the Loma Alta trailhead, open to bikes, and \"connects the Arizona Trail\""},{"name":"Garwood Dam and Wildhorse Tank (east)","source":"https://www.nps.gov/sagu/planyourvisit/saguaro_hiking.htm","accessed":"2026-10-02","si":["hiking","wildlife"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a moderate 6.4-mile hike to a perennial water source with Santa Catalina views"},{"name":"Tanque Verde Ridge Trail (east)","source":"https://www.nps.gov/sagu/planyourvisit/saguaro_hiking.htm","accessed":"2026-10-02","si":["hiking","adventure","expedition"],"booking_route":"none needed for day use; camping by permit on Recreation.gov","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the east district''s strenuous ridge climb - up to 8.7 miles and 4,000 ft of elevation, past a crested saguaro; the NPS names it for sunset, and it leads to Juniper Basin campground (6,000 ft, 6.9 mi)"},{"name":"Wild Dog Trail and Signal Hill add-on (west)","source":"https://www.nps.gov/sagu/planyourvisit/saguaro_hiking.htm","accessed":"2026-10-02","si":["hiking","family","culture"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an easy 1.8-mile trail with an optional 0.5-mile Signal Hill add-on"},{"name":"King Canyon and Gould Mine Loop (west)","source":"https://www.nps.gov/sagu/planyourvisit/saguaro_hiking.htm","accessed":"2026-10-02","si":["hiking","family","culture"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an easy-to-moderate 2.4-mile loop with 380 ft of gain through a sandy wash and rocky sections; the NPS notes \"bees may be present due to moisture\""},{"name":"Sendero Esperanza to the Ridge and Wasson Peak (west)","source":"https://www.nps.gov/sagu/planyourvisit/saguaro_hiking.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"moderate to strenuous, 3.4 to 8 miles and 220 to 1,600 ft of gain, to the Tucson Mountain District''s highest point at 4,687 ft"},{"name":"Saguaro Wilderness backcountry campgrounds (Manning Camp and five others)","source":"https://www.nps.gov/sagu/planyourvisit/camping.htm","accessed":"2026-10-02","si":["expedition","hiking","adventure"],"booking_route":"Recreation.gov permit (up to 2 months in advance, per the NPS outdoor activities page)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the park''s only camping: 6 hike-in designated campgrounds - Manning Camp (6 sites, 7,920 ft, 7.5 mi from Turkey Creek), Spud Rock Spring, Happy Valley Saddle, Juniper Basin, Grass Shack (10 mi) and Douglas Spring; $8 per campsite per night, max 6 per site; \"There are no accommodations for any vehicle camping (including RV)\""},{"name":"Ranger-led programmes (year-round, busiest January-April)","source":"https://www.nps.gov/sagu/planyourvisit/guided-programs.htm","accessed":"2026-10-02","si":["family","senior","culture","wildlife"],"booking_route":"none observed - see the park calendar","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"guided programmes in both districts, \"from ranger talks around our gardens to night hikes\"; the widest choice January through April; summer limited by \"extreme temperatures during the daytime\"; schedules on the park calendar"},{"name":"Golden Gate multi-use trail and park cycling","source":"https://www.nps.gov/sagu/planyourvisit/bicycling-at-saguaro-national-park.htm","accessed":"2026-10-02","si":["sports","adventure"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a \"wide gravel path\" reached from the Bajada Loop or Picture Rocks Road on the former Golden Gate Road, now \"permanently closed to vehicle traffic\"; e-bikes allowed \"only where traditional bicycles are allowed\"; \"Drinking water is NOT available on the Cactus Forest Drive, Bajada Loop Drive or at any picnic area\""},{"name":"Arizona-Sonora Desert Museum","source":"https://en.wikipedia.org/wiki/Arizona-Sonora_Desert_Museum","accessed":"2026-10-02","si":["family","wildlife","senior","culture"],"booking_route":"not observed (desertmuseum.org returned 403 on three URLs)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"founded in 1952 just west of Tucson: a zoo, aquarium, botanical garden, natural history museum, art gallery and publisher on 98 acres, with \"two miles (3.2 km) of walking paths traversing 21 acres\", over 230 animal species and 1,200 plant varieties, nearly 400,000 visitors a year; Visit Tucson calls it \"a zoo, garden and museum\""},{"name":"Old Tucson","source":"https://oldtucson.com/","accessed":"2026-10-02","si":["family","culture","group"],"booking_route":"own online ticketing on oldtucson.com; 520.883.0100","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"built in 1939 for the movie Arizona (1940) beside the Tucson Mountains near the park''s western section; now \"The Adventure Park\" with studio tours and stunt shows, Nightfall and Ghost Tours in October 2026 and Yuletide November 24 - December 24; online tickets \"Save $5 per Ticket Compared to Walk-Up Pricing\"; lease ends April 2027 and Pima County is seeking an operator"},{"name":"Mission San Xavier del Bac","source":"https://en.wikipedia.org/wiki/Mission_San_Xavier_del_Bac","accessed":"2026-10-02","si":["culture","senior","romance"],"booking_route":"none needed; 1950 W San Xavier Rd, (520) 294-2624 (sanxaviermission.org)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"founded in 1692 by Father Eusebio Francisco Kino on the Tohono O''odham Nation''s San Xavier reservation; the church was built 1783-1797 and is \"the oldest European structure in Arizona\", a National Historic Landmark since 1960 and still an active parish serving the village of Wa:k"},{"name":"Mission Garden","source":"https://missiongarden.org/","accessed":"2026-10-02","si":["culinary","culture","senior"],"booking_route":"walk-in; admission not shown","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"a living agricultural museum of Sonoran Desert-adapted heritage fruit trees, traditional local heirloom crops and edible native plants\" at the foot of Sentinel Peak, representing about 4,100 years of continuous cultivation; open Wednesday-Sunday, 8am-2pm October-March"},{"name":"Tohono Chul Sonoran Botanic Garden","source":"https://tohonochul.org/","accessed":"2026-10-02","si":["senior","wellness","culinary","family"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"49 acres of serene beauty\", an accredited botanical garden and Level II arboretum at 7366 North Paseo del Norte, with the Garden Bistro (daily 9am-4pm); grounds 8am-5pm daily; $20 general, $15 seniors 62+"},{"name":"Sabino Canyon Crawler","source":"https://www.sabinocanyoncrawler.com/","accessed":"2026-10-02","si":["family","senior","hiking"],"booking_route":"own online reservation system on sabinocanyoncrawler.com","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the electric shuttle in the Sabino Canyon Recreation Area: a Sabino Canyon route with hourly departures 9 AM-4 PM ($15 adults, $8 children) and a Bear Canyon route, plus seasonal Saturday Night Tours of \"approximately 90 minutes\"; a separate $8 amenity fee per vehicle"},{"name":"Sky Island Scenic Byway (Catalina Highway) to Mount Lemmon","source":"https://www.recreation.gov/gateways/13848","accessed":"2026-10-02","si":["adventure","senior","hiking","romance"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 27-mile byway climbing \"to shady conifer forests at nearly 9,000 feet\", with \"biological diversity equivalent to a drive from Mexico to Canada\", starting among saguaros in the Sonoran Desert"},{"name":"Mount Lemmon Ski Valley and the Sky Ride","source":"https://www.skithelemmon.com/","accessed":"2026-10-02","si":["sports","family","adventure"],"booking_route":"not observed; (520) 576-1321","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"in the Coronado National Forest at 10300 Ski Run Rd: winter skiing, the Sky Ride scenic chairlift year-round, a restaurant, gift shop and fudge store; Thursday-Monday, \"closed Tuesday and Wednesday\""},{"name":"Pima Air & Space Museum","source":"https://www.pimaair.org/","accessed":"2026-10-02","si":["family","senior","group"],"booking_route":"not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"one of the largest non-government funded aviation & space museums in the world\" with \"about 400 historic aircraft\" on \"80 acres\" and six indoor hangars; adults $22.50 for one day; summer hours 9 AM-3 PM"},{"name":"Tanque Verde Ranch","source":"https://www.tanqueverderanch.com/","accessed":"2026-10-02","si":["family","adventure","group","romance"],"booking_route":"own engine on tanqueverderanch.com; 800-234-3833","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"one of America''s old-time cattle and guest ranches\", established in 1868, an all-inclusive dude ranch on 640 acres \"nestled among Rincon mountains and adjacent to Saguaro National Park and Coronado National Forest\"; packages include lodging, three meals, horseback riding and most activities"},{"name":"White Stallion Ranch","source":"https://www.whitestallion.com/","accessed":"2026-10-02","si":["family","adventure","group","wellness"],"booking_route":"innRoad (whitestallionranch.client.innroad.com); (520) 297-0252","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"a historic, traditional, yet upscale family-owned and operated dude ranch\" run by the True family since 1965 on 3,000 acres, with 43 rooms and 170 horses; riding, archery, rock climbing, jeep tours and a spa"},{"name":"Hacienda Del Sol Guest Ranch Resort","source":"https://www.haciendadelsol.com/","accessed":"2026-10-02","si":["romance","wellness","culinary"],"booking_route":"not observed; (520) 299-1501","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Catalina Foothills resort operating \"since 1929\", with The Grill, the Terraza Garden Patio & Lounge, a spa, complimentary Sunday yoga, and billed as \"Tucson''s Premier Place for Weekly Live Music\"; the base for Backroads'' family trip"},{"name":"Loews Ventana Canyon Resort","source":"https://www.loewshotels.com/ventana-canyon","accessed":"2026-10-02","si":["wellness","sports","romance","senior"],"booking_route":"own engine on loewshotels.com; 1-877-879-9979","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"A Sonoran Escape for all the Senses\" in the Catalina foothills: 398 rooms including 27 suites, two Tom Fazio-designed golf courses, the Lakeside Spa, two heated pools, and the Flying V restaurant; AAA Four Diamond"},{"name":"Camp Saguaro (Hipcamp), Tucson","source":"https://www.hipcamp.com/en-US/d/united-states/arizona/saguaro-national-park/glamping","accessed":"2026-10-02","si":["glamping","family","adventure"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Hipcamp property listed for tents, RVs and lodging, rated 100% across 889 reviews on Hipcamp''s Saguaro National Park glamping page"},{"name":"Diamond J RV Park, Tucson Mountain Park edge","source":"https://maps.campendium.com/us/tucson-az/camping-rv/diamond-j-rv-park","accessed":"2026-10-02","si":["adventure","senior"],"booking_route":"phone only, (520) 883-6706 (per Campendium)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an adults-only (18+) RV park at 3451 S. San Joaquin Rd with 128 \"40'' ultra-wide sites\", full hookups, and reviewer-reported \"trails that go straight to Tucson Mountain Park and Saguaro National Park\""},{"name":"Tucson E-Bike Adventures - Saguaro National Park East E-Bike Tour","source":"https://ww1.aaa.com/tripcanvas/thing-to-do/saguaro-national-park-east-e-bike-tour-144494P1","accessed":"2026-10-02","si":["adventure","sports","group"],"booking_route":"AAA Travel / Viator platform (also listed on Expedia and Pelago)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 2 hour 30 minute guided e-bike tour of the east district, including \"E-Bike, Battery, Helmet, Guide\"; minimum age 16, riders \"110-260 lbs.\" and 5''1\" to 6''5\"; from $168.70 per person on AAA''s listing"},{"name":"Backroads - Arizona''s Saguaro & Tucson Family Multi-Adventure Tour","source":"https://www.backroads.com/trips/MAZQF/arizonas-saguaro-tucson-multi-adventure-tour-4-day-getaway-families-teens-kids","accessed":"2026-10-02","si":["family","adventure","hiking","group"],"booking_route":"Backroads own booking","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 4-day, 3-night family trip for ages 7-17 (minimum 4) that will \"hike and bike through diverse Saguaro National Park\", visit the Desert Museum, hike Sabino Canyon and ride in the Tucson Mountains foothills, staying at Hacienda Del Sol; from $3,199 per person; 2027 departures in February, March and November"},{"name":"Saguaro Corners Restaurant & Bar","source":"http://www.saguaro-corners.com/","accessed":"2026-10-02","si":["culinary","family","wildlife"],"booking_route":"walk-in; (520) 886-2020","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"just outside Saguaro National Park East since 1956, on the corner of Escalante and Old Spanish Trail\": a scratch kitchen with 18 craft taps and a \"shaded and misted patio with Rincon Mountain views\" and \"wildlife and desert beauty right out our windows\"; closed Mondays"},{"name":"El Güero Canelo - the Sonoran hot dog","source":"https://www.afar.com/magazine/tucson-is-the-best-food-city-in-arizona","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in (elguerocanelo.com returned 403)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a \"James Beard Award-winning\" Tucson institution serving Sonoran hot dogs inspired by Hermosillo recipes (AFAR)"},{"name":"Ruiz Hot Dogs","source":"https://www.afar.com/magazine/tucson-is-the-best-food-city-in-arizona","accessed":"2026-10-02","si":["culinary","culture"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a small cart on 22nd Street serving Sonoran hot dogs (AFAR)"},{"name":"Tacos Apson","source":"https://www.afar.com/magazine/tucson-is-the-best-food-city-in-arizona","accessed":"2026-10-02","si":["culinary"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"mesquite-grilled costillas de res (beef ribs) (AFAR)"},{"name":"Caruso''s, Fourth Avenue","source":"https://www.afar.com/magazine/tucson-is-the-best-food-city-in-arizona","accessed":"2026-10-02","si":["culinary","family","romance"],"booking_route":"not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"has been going strong since 1938\" on Fourth Avenue and \"still uses the same copper pot\" for its signature red sauce (AFAR)"},{"name":"Cup Café at Hotel Congress","source":"https://www.afar.com/magazine/tucson-is-the-best-food-city-in-arizona","accessed":"2026-10-02","si":["culinary","culture"],"booking_route":"not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"in Hotel Congress, known for \"legendary baked eggs\" (AFAR)"},{"name":"Downtown Kitchen + Cocktails","source":"https://www.afar.com/magazine/tucson-is-the-best-food-city-in-arizona","accessed":"2026-10-02","si":["culinary","romance","culture"],"booking_route":"not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"highlighting indigenous ingredients for years\", including \"Dr. Pepper pork belly biscuits\" made with local mesquite bean flour (AFAR)"},{"name":"Heirloom Farmers'' Market at Rillito Park","source":"https://www.afar.com/magazine/tucson-is-the-best-food-city-in-arizona","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Sunday market with \"space for more than 80 small businesses\", including Country Harvest Pantry''s \"heirloom beans that have been a staple of Arizona cuisine for thousands of years\" (AFAR)"},{"name":"Pueblo Vida Brewing and Crooked Tooth Brewing","source":"https://www.afar.com/magazine/tucson-is-the-best-food-city-in-arizona","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"Pueblo Vida, with \"some of the best\" hazy IPAs in the state, and Crooked Tooth, with \"Sonoran sours in flavors like Key lime pie and hibiscus\" (AFAR)"},{"name":"Tucson City of Gastronomy","source":"https://tucson.cityofgastronomy.org/about","accessed":"2026-10-02","si":["culinary","culture"],"booking_route":"none - a designation and certification body, not a bookable product","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"On 15 December 2015, Tucson, Arizona, became the first UNESCO City of Gastronomy designated in the United States\"; the organisation \"Certifies and endorses restaurants, food artisans, culinary events, and experiences\""}],"faq":[{"q":"Is there a campground at Saguaro National Park?","a":"Not a drive-in one. The NPS states there are no accommodations for any vehicle camping, including RV. Camping is at six designated hike-in campgrounds in the Saguaro Wilderness, $8 per campsite per night, with permits on Recreation.gov.","source":"https://www.nps.gov/sagu/planyourvisit/camping.htm","accessed":"2026-10-02"},{"q":"How much does it cost to enter Saguaro National Park?","a":"$25 per private vehicle, $20 per motorcycle and $15 per person on foot or bicycle; a Saguaro annual pass is $45. The NPS states that only debit and credit cards are accepted, no cash.","source":"https://www.nps.gov/sagu/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Which district of Saguaro should I visit, east or west?","a":"Both have a visitor center, a loop drive and short trails. The Rincon Mountain District (east) has the 8-mile paved Cactus Forest Loop Drive and the backcountry campgrounds; the Tucson Mountain District (west) has the 6-mile graded dirt Bajada Loop Drive and the Signal Hill petroglyphs.","source":"https://www.nps.gov/sagu/planyourvisit/gettingaround.htm","accessed":"2026-10-02"},{"q":"How much water should I carry hiking in Saguaro?","a":"The NPS says that on hot summer days you should be drinking 1 quart of water per hour of hiking, and to avoid 10 am - 4 pm in the summer months; in winter, take at least 2 quarts per day. Water fountains are found only at the two visitor centers.","source":"https://www.nps.gov/sagu/planyourvisit/hiking-safety-information.htm","accessed":"2026-10-02"},{"q":"Where can I see petroglyphs in Saguaro National Park?","a":"At Signal Hill on the Bajada Loop Drive in the west district, which the NPS calls the best place to see petroglyphs within the park. The short walk up to the petroglyphs is not ADA accessible.","source":"https://www.nps.gov/places/signal-hill.htm","accessed":"2026-10-02"},{"q":"When is the best time to visit Saguaro National Park?","a":"The NPS describes winter as mildly warm, with days averaging 65 degrees and nights averaging 40, and ranger programmes are busiest January through April. Summer daytime temperatures regularly reach well over 100 degrees, and the monsoon runs June 15 to September 30.","source":"https://home.nps.gov/sagu/planyourvisit/weather.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Saguaro National Park: Loop Drives, Trails, Petroglyphs & Where to Stay | TravelWell","meta_description":"Both districts of Saguaro, the loop drives, Signal Hill petroglyphs, hike-in camping, guest ranches, the Desert Museum and Tucson''s Sonoran hot dogs.","slug":"saguaro-national-park-arizona","primary_keyword":"Saguaro National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Saguaro National Park, Arizona"}}'::jsonb, 70),
  ('white-sands-new-mexico', '12A', 'White Sands National Park', 'United States', 'World''s largest gypsum dunefield', 'future', 'verified', 'mountainValley', 'The Southwest Desert', '{"adventure","family","hiking","culture","spectator","parks"}', '{"dramatic","serene","wild","family-friendly"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Dunes Drive","source":"https://www.nps.gov/whsa/planyourvisit/driving-dunes-drive.htm","accessed":"2026-10-03","si":["motoring","family","senior","adventure"],"booking_route":"pay at the White Sands Entrance Station - $25 per private vehicle, cash or credit/debit","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities","move"],"draw_rank":1,"blurb":"\"an eight-mile (13 km) scenic drive\"; \"the first five miles of Dunes Drive are paved and the last three miles are a hard-packed gypsum sand road\"; \"The 16-mile (26km) round-trip drive takes approximately 45 minutes\", with \"outdoor exhibits, hiking trails, picnic areas, vault toilets, and parking areas\" along it. The park itself: \"Great wave-like dunes of gypsum sand have engulfed 275 square miles of desert, creating the world''s largest gypsum dunefield.\""},{"name":"Sledding the gypsum dunes","source":"https://www.nps.gov/whsa/planyourvisit/sledding.htm","accessed":"2026-10-03","si":["family","adventure","sports"],"booking_route":"none needed - bring a sled or rent/buy one at the White Sands Trading Post","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Waxed plastic snow saucers work best and can be rented or purchased at the park''s gift shop\"; sledding is \"Allowed in the loop portion of Dunes Drive\". \"Choose a dune with a gently sloping face and a level run-off at the end\";\"Sit or lay on the sled, with your feet pointing downhill\"; \"Do not stand up while sledding.\""},{"name":"Sunset Stroll","source":"https://www.nps.gov/whsa/planyourvisit/sunset-stroll.htm","accessed":"2026-10-03","si":["hiking","romance","family","senior"],"booking_route":"none needed - free, no reservations","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"A leisurely, ranger-guided stroll through the gypsum sand dunes\" timed to conclude at sunset; \"Sunset strolls are offered three days a week on Friday, Saturday, and Sunday\"; \"45 minutes to one hour\". \"Program is free. Park entrance fees apply.\" \"Reservations are not required or permitted.\" Meets at the \"Sunset Stroll Meets Here\" parking area, 8 miles from the fee station."},{"name":"Moonlight Hike","source":"https://www.nps.gov/whsa/planyourvisit/moonlight-hike.htm","accessed":"2026-10-03","si":["hiking","adventure","romance"],"booking_route":"Recreation.gov or 1-877-444-6777, from one month ahead at 8:00 am MT","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":4,"blurb":"\"Hike the dunes under the magical glow of the moon\"; \"March through November, on nights surrounding the full moon\"; \"1.5 - 2 hours\". \"$8 per person ages 16 and older and $4 per child ages 15 and younger\" plus entrance fees. \"Tickets are available one month before the day of the tour at 8:00 am Mountain Time\" and \"often sell out in a matter of minutes.\" \"Flashlights, headlamps, and flash photography are not allowed.\""},{"name":"Full Moon Night","source":"https://www.nps.gov/whsa/planyourvisit/full-moon-night.htm","accessed":"2026-10-03","si":["spectator","romance","family","culture"],"booking_route":"none needed - free, no tickets","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"Enjoy the radiance of the dunes beneath a full moon with live music, ranger programs, and special guest presenters and artists\"; May through October; \"The park hours are generally extended two hours from the park''s normal closing time on all Full Moon Nights.\" 2026: May 1, May 31, June 29, July 29, August 27, September 26, October 25. \"Program is free. Park entrance fees apply.\" \"Reservations or tickets are not required.\""},{"name":"Lake Lucero Tour","source":"https://www.nps.gov/whsa/planyourvisit/lake-lucero-tour.htm","accessed":"2026-10-03","si":["adventure","hiking","culture"],"booking_route":"Recreation.gov or 1-877-444-6777, from one month before the tour","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":6,"blurb":"\"Take a tour to Lake Lucero with a ranger and learn about the formation of the sands\", with \"thousands of exposed selenite crystals\"; \"November through March\"; \"Three hours\"; \"$8 per person ages 16 and older and $4 per child ages 15 and younger\". Meets at the \"Small Missile Range Gate, located on Hwy 70 West between mile markers 174 and 175\"; the drive is \"17.5 miles (27.36 km) one-way\"."},{"name":"Alkali Flat Trail","source":"https://www.nps.gov/whsa/planyourvisit/alkali-flat-trail.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"5 miles (8 km), out-and-back\", \"Strenuous\", about \"3 hours\": \"This trail takes you through the heart of the sands, up and over steep dunes, to the edges of the Alkali Flat\", the bed of an ice-age lake - \"this trail is not flat\". \"Take a minimum of two 32-ounce (1 L) bottles of water per person\"; \"If you cannot see the next trail marker because of blowing sand or because the trail marker is knocked down, do not proceed—return to your car.\""},{"name":"White Sands Visitor Center","source":"https://www.nps.gov/whsa/planyourvisit/visitor-center.htm","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"none needed - 19955 Highway 70 West, Alamogordo, NM 88310","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"Built 1936-1940 as a WPA project; \"In 1990, the visitor center and adjacent seven buildings...were officially designated as the White Sands National Park Historic District\", with \"decoratively carved corbels\" and \"individually crafted tin lighting fixtures.\" Museum exhibits and a 17-minute film every 30 minutes (Spanish and audio-description versions). \"The visitor center and gift shop are open 363 days a year, closing on Thanksgiving and Christmas Day.\" 575-479-6124."},{"name":"White Sands Trading Post (park gift shop)","source":"https://www.nps.gov/whsa/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"walk-in at the visitor center","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["gear","shop","eat"],"draw_rank":9,"blurb":"Operated by Western National Parks Association, the gift shop \"sells sleds for sledding, pre-packaged food, bottled water, and souvenirs\" - \"convenient, ready-to-eat food options including packaged sandwiches, bottled drinks, salty snacks, and sweet treats\" - the only food in the park. It stays open during missile-test closures."},{"name":"Fossilized footprints exhibit","source":"https://www.nps.gov/whsa/learn/nature/fossilized-footprints.htm","accessed":"2026-10-03","si":["culture","family"],"booking_route":"none needed - in the visitor center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"the largest collection of fossilized human footprints\", showing humans in the Tularosa Basin \"at least 23,000 years ago\" - \"probably the most important resources in the Americas to understand the interaction of humans and extinct animals from the ice age.\" \"Currently the footprints at White Sands are inaccessible\", but an exhibit of \"casted human footprints\" opened at the visitor center in January 2024."},{"name":"Yucca, Roadrunner and Primrose picnic areas","source":"https://www.nps.gov/whsa/planyourvisit/picknicking.htm","accessed":"2026-10-03","si":["family","senior","group"],"booking_route":"first-come, first-served; Group Use Area by reservation with the park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"There are a total of 62 shaded tables in the three designated public picnic areas\", with elevated grills, \"located off Dunes Drive about six to seven miles (9.65 –11.26 km) from the fee station\"; Roadrunner has two pavilions for up to 20 people; the Group Use Area pavilion needs a reservation (\"Reservations are required to use this area\")."},{"name":"Backcountry camping (closed)","source":"https://www.nps.gov/whsa/planyourvisit/backpackingpr.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"none - closed, no reopening date published","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"Normally \"ten primitive backcountry camping sites available on a first-come, first-served basis\" (things-to-do page). Today: \"Backcountry camping is currently closed while park staff assess environmental conditions and other key factors\"; no reopening date; \"Currently, overnight stays are not permitted within White Sands National Park.\""},{"name":"Kit for sun and heat in the dunes","source":"https://www.nps.gov/whsa/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - water and snacks also sold at the park gift shop","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":13,"blurb":"The park''s list: \"One gallon (4 liters) of water per person per day is recommended\", with salty snacks; \"A hat, sunscreen, and long sleeves are all recommended to protect yourself from sunburn in the dunes\" - even in winter; \"Adequate clothing (rain jacket and warm layers)\"; \"Closed toed shoes are suggested. Venomous creatures can be found throughout the dunefield.\" Also a first aid kit and flashlight."},{"name":"Kit for dune hiking and navigation","source":"https://www.nps.gov/whsa/planyourvisit/hiking-safety-tips.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":14,"blurb":"\"Wear a wide-brimmed hat, sunscreen with an SPF of 15 or higher, sunglasses\" and lightweight long sleeves and long pants; carry \"the park map, compass, flashlight with extra batteries, whistle, signal mirror, and first-aid kit\" - GPS can be unreliable here, and the safety page warns \"Do not rely on your phone⁠— cell service is spotty in the park.\" \"Have at least one gallon (4L) of water per person, per day.\""},{"name":"Kit for sledding the dunes","source":"https://www.nps.gov/whsa/planyourvisit/sledding.htm","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"park gift shop (rent or buy), or affiliate retail referral (Amazon Associates; REI.com via AvantLink) for a saucer brought from home","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":15,"blurb":"\"Waxed plastic snow saucers work best and can be rented or purchased at the park''s gift shop\"; \"You may also bring your own sleds.\" The NPS warns to watch for \"the hard ground at the dune''s base where injuries commonly occur\" and to never sled \"into a parking area or roadway.\""},{"name":"Kit for the night hike and Lake Lucero","source":"https://www.nps.gov/whsa/planyourvisit/moonlight-hike.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":16,"blurb":"Moonlight Hike: bring \"Hat, jacket, and gloves,\" \"closed-toe shoes,\" and \"two liters of water per person\" - \"Flashlights, headlamps, and flash photography are not allowed.\" (moonlight-hike page) Lake Lucero: closed-toe hiking shoes, sunscreen, hats, sunglasses, snacks and \"a minimum of one gallon of water per person\"; long sleeves and pants recommended (https://www.nps.gov/whsa/planyourvisit/lake-lucero-tour.htm, read 2026-10-03)."},{"name":"Oliver Lee Memorial State Park","source":"https://www.emnrd.nm.gov/spd/find-a-park/oliver-lee-memorial-state-park/","accessed":"2026-10-03","si":["hiking","family","motoring","culture"],"booking_route":"ReserveAmerica (newmexicostateparks.reserveamerica.com), up to six months ahead","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":17,"blurb":"\"Set against the dramatic Sacramento Mountains, this park features a historic ranch house, quiet camping in the Chihuahuan Desert, and pools of water under the cottonwood trees of Dog Canyon.\" 15 water/electric sites (30 amp), 1 ADA site (50 amp), 24 developed dry sites with 8 tent pads; \"Guided Tours of the Historic Oliver Lee Ranch House -Contact Park for current schedule\". 8 miles south of Alamogordo via US 54, then 4 miles east on Dog Canyon Road; (575) 437-8284. The NPS lists it 24 miles from White Sands."},{"name":"Aguirre Spring Campground","source":"https://www.blm.gov/visit/aguirre-spring-campground","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"first-come, first-served; group shelters by phone 575-525-4300, 48 hours ahead","commission_status":"none","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":18,"blurb":"BLM: \"The high wall, needle-like spires of the Organ Mountains curve dramatically around a semicircle of Chihuahuan Desert habitat\"; \"a total of 55 individual campsites that are available on a first-come first-served basis\"; $7 per vehicle per campsite overnight, $5 day use; \"The recommended max length for RVs is 23 feet\". Baylor Pass Trail (six miles one way) and Pine Tree Trail (four-mile loop). The NPS lists it 39 miles from White Sands."},{"name":"Hacienda RV Resort","source":"https://www.haciendarv.com/","accessed":"2026-10-03","si":["motoring","senior"],"booking_route":"own website booking or phone (575) 528-5800","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"740 Stern Drive, Las Cruces: \"113 meticulously maintained RV sites\" with \"30/50 amp electrical hookups,\" \"full water and sewer hookups,\" and \"free high-speed WiFi\"; hot tub, fitness center, dog park and clubhouse; Pull Thru XL sites 69''-110''; 1.5 miles from Old Mesilla. (575) 528-5800. Las Cruces sits at the ring''s edge: the NPS puts the park entrance 52 miles east of Las Cruces."},{"name":"KOA of Las Cruces","source":"https://www.visitlascruces.com/places-to-stay/campgrounds-rv-parks/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"koa.com (brand booking; not fetched - HTTP 403)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"Listed by Visit Las Cruces: \"conveniently located one mile from Interstate 10, overlooking Las Cruces and the scenic Mesilla Valley\". koa.com refused the fetch (HTTP 403), so site types and rates are not stated here."},{"name":"TownePlace Suites, Las Cruces","source":"https://www.visitlascruces.com/places-to-stay/pet-friendly/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":21,"blurb":"Marriott''s extended-stay brand, listed by Visit Las Cruces under \"Nationally Known Brands\" at 2143 Telshor Ct., Las Cruces, as pet friendly. marriott.com refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Hilton Garden Inn, Las Cruces","source":"https://www.visitlascruces.com/places-to-stay/pet-friendly/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":22,"blurb":"Listed by Visit Las Cruces under \"Nationally Known Brands\" at 2550 Don Roser Dr., Las Cruces, as pet friendly. hilton.com refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Home2 Suites by Hilton, Las Cruces","source":"https://www.visitlascruces.com/places-to-stay/pet-friendly/","accessed":"2026-10-03","si":["family"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":23,"blurb":"Listed by Visit Las Cruces under \"Nationally Known Brands\" at 1120 N. Telshor Blvd., Las Cruces, as pet friendly. hilton.com refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Staybridge Suites, Las Cruces","source":"https://www.visitlascruces.com/places-to-stay/pet-friendly/","accessed":"2026-10-03","si":["family"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":24,"blurb":"IHG''s extended-stay brand, listed by Visit Las Cruces under \"Nationally Known Brands\" at 2651 E. Northrise Dr., Las Cruces, as pet friendly. ihg.com refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"The Lodge at Cloudcroft","source":"https://www.223collectionhotels.com/the-lodge","accessed":"2026-10-03","si":["romance","golf","culture"],"booking_route":"own website \"Book Now\" (ResNexus)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","eat"],"draw_rank":25,"blurb":"Established 1899 in the Sacramento Mountains at \"9,000 feet above sea level\"; its golf course is \"one of the highest courses in New Mexico\"; dining at \"1899\", and \"Rebecca\" is \"our resident ghost.\" Part of the independent 223 Collection."},{"name":"Hotel Encanto de Las Cruces","source":"https://www.visitlascruces.com/places-to-stay/unique-lodging/","accessed":"2026-10-03","si":["culture","romance"],"booking_route":"own website (not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"Visit Las Cruces: \"A unique New Mexico hotel with an ambiance reflective of Spanish and Mexican Colonial history and tradition\"; 705 S. Telshor Blvd.; offers a \"pet-friendly package\" with room, doggie toy and blankets."},{"name":"New Mexico Museum of Space History","source":"https://visitalamogordo.com/museums-new/","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"admission at the museum (prices page not read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":27,"blurb":"\"Did you know that New Mexico''s Tularosa Basin was the cradle of America''s space program?\" Moon rocks, satellite replicas and the International Space Hall of Fame (est. 1976); the New Horizons Dome Theater & Planetarium. 1301 North White Sands Blvd., Alamogordo; (575) 437-2840; open Monday and Wednesday-Saturday 10-5, Sunday 12-5, closed Tuesday. The museum notes its Fifth Floor is temporarily closed for renovation (nmspacemuseum.org, read 2026-10-03)."},{"name":"Heart of the Desert Pistachios & Wine","source":"https://www.heartofthedesert.com/","accessed":"2026-10-03","si":["wine","culinary","family"],"booking_route":"walk-in; free farm tours","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop","eat","activities"],"draw_rank":28,"blurb":"\"New Mexico''s first and largest producing pistachio grove\", founded 1974 with over 13,000 pistachio trees; wine tasting room, gift shop and free farm tours of the groves, roasting facility and vineyard. On Highway 54/70, Alamogordo; 800.432.0999; Mon-Sat 8AM-6PM, Sun 9AM-6PM."},{"name":"Organ Mountains-Desert Peaks National Monument","source":"https://www.blm.gov/programs/national-conservation-lands/new-mexico/organ-mountains-desert-peaks-national-monument","accessed":"2026-10-03","si":["hiking","adventure","wildlife"],"booking_route":"none needed - public lands","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":29,"blurb":"BLM: \"The Organ Mountains are a steep, angular mountain range with rocky spires that jut majestically above the Chihuahuan Desert floor to an elevation of 9,000 feet.\" 496,330 acres, established May 21, 2014; hiking, horseback riding, mountain biking, camping and wildlife viewing, including Aguirre Spring and the Sierra Vista Trail."},{"name":"Ski Cloudcroft","source":"https://skicloudcroft.net/","accessed":"2026-10-03","si":["ski","family"],"booking_route":"own website / at the lodge","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":30,"blurb":"\"The Southern Most Ski Area in New Mexico, where families come to ski, snowboard, tube and, most importantly, have fun!\" Top elevation 9,100 feet, base 8,400; winter and summer tubing. The 2025-26 season closed March 7, 2026 \"due to warm weather and insufficient snow\". 1920 1/2 U.S Highway 82, Cloudcroft; (575) 682-2333."},{"name":"Alameda Park Zoo","source":"https://visitalamogordo.com/outdoor-activities-new/","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"admission at the gate","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":31,"blurb":"Alamogordo: \"Home to nearly 300 animals representing 90 species, the 12-acre Alameda Park Zoo\"; daily 9am-5pm except Christmas and New Year''s; (575) 439-4290."},{"name":"Alamogordo","source":"https://www.nps.gov/whsa/planyourvisit/directions.htm","accessed":"2026-10-03","si":["culture","family"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":32,"blurb":"The gateway town: the visitor center is \"about 15 miles (24 km) west of Alamogordo\", about 15 minutes'' drive, and \"The nearest gas station is located in Alamogordo\". Visit Alamogordo''s visitor center: 1301 North White Sands Blvd., 575-439-4100."},{"name":"Cloudcroft","source":"https://visitalamogordo.com/day-trips/","accessed":"2026-10-03","si":["hiking","ski","romance"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":33,"blurb":"\"Perched nearly 9,000 feet above sea level in the Sacramento Mountains, Cloudcroft was once accessible only by train\", with \"boutique shopping and cozy cafés to hiking, mountain biking, and winter skiing\" (Visit Alamogordo day trips). The NPS names the Lincoln National Forest campgrounds around it (Pines, Silver, Skyline) at about 35-69 miles from the park."},{"name":"Las Cruces and Old Mesilla","source":"https://www.visitlascruces.com/places-to-stay/hotels/","accessed":"2026-10-03","si":["culture","culinary"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":34,"blurb":"The western gateway: the park entrance is \"about 52 miles (84 km) east of Las Cruces\", about an hour on US-70 (NPS). Visit Las Cruces counts \"nearly 60 different hotels\" and names Mesilla''s \"classic New Mexican restaurants\" with \"inviting patios\". Visitors bureau: 336 S. Main St., (575) 541-2444."},{"name":"La Posta de Mesilla","source":"https://www.lapostademesilla.com/","accessed":"2026-10-03","si":["culinary","culture"],"booking_route":"walk-in / phone (575) 524-3524","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"\"The year was 1939\": a \"historic adobe hacienda\" on the old Butterfield Stagecoach route serving \"Mexican Food & Steaks\", known for fajitas, chile rellenos and margaritas. 2410 Calle De San Albino, Mesilla; (575) 524-3524."},{"name":"Double Eagle (Mesilla)","source":"https://www.visitlascruces.com/food-drink/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"own website (not fetched)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"Named by Visit Las Cruces with La Posta among Mesilla''s \"classic New Mexican restaurants\" with \"inviting patios\". Its own site was not fetched, so nothing else is stated here."},{"name":"Oppenheimer Gasthaus","source":"https://visitalamogordo.com/alamogordo-restaurants-new/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in / phone 575-348-2853","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"Listed by Visit Alamogordo: 902 N New York Ave, Alamogordo, NM 88310; 575-348-2853."},{"name":"575 Brewing Company","source":"https://visitalamogordo.com/alamogordo-restaurants-new/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"Listed by Visit Alamogordo: 234 West 8th St., Alamogordo."},{"name":"D.H. Lescombes (Alamogordo)","source":"https://visitalamogordo.com/alamogordo-restaurants-new/","accessed":"2026-10-03","si":["wine","culinary"],"booking_route":"walk-in / phone 575-616-5595","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":39,"blurb":"Listed by Visit Alamogordo: 261 Panorama Blvd., Alamogordo; 575-616-5595."},{"name":"Pizza Patio","source":"https://visitalamogordo.com/alamogordo-restaurants-new/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / phone 575-434-9633","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":40,"blurb":"Listed by Visit Alamogordo: 2203 E. 1st. St., Alamogordo; 575-434-9633."},{"name":"Rustic Café","source":"https://visitalamogordo.com/alamogordo-restaurants-new/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in / phone 575-437-2770","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":41,"blurb":"Listed by Visit Alamogordo: 3500 N. White Sands Blvd., Alamogordo; 575-437-2770."},{"name":"Hi-D-Ho Drive-In","source":"https://visitalamogordo.com/alamogordo-restaurants-new/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":42,"blurb":"Listed by Visit Alamogordo: 414 S. White Sands Blvd., Alamogordo; 575-437-6400."}],"faq":[{"q":"Is White Sands National Park free?","a":"No. The NPS entrance fee is $25.00 per private vehicle, $20.00 per motorcycle and $15.00 per person on foot or bicycle (16 and older); a White Sands annual pass is $45.00. \"Children ages 15 and younger enter for free\" (basicinfo page). Payment is \"Cash or Credit/Debit\" at the entrance station.","source":"https://www.nps.gov/whsa/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you camp at White Sands National Park?","a":"Not at present: \"Backcountry camping is currently closed while park staff assess environmental conditions and other key factors\", and \"Currently, overnight stays are not permitted within White Sands National Park.\" No reopening date has been set. The NPS points campers to Oliver Lee Memorial State Park (24 miles) and Aguirre Springs (39 miles).","source":"https://www.nps.gov/whsa/planyourvisit/backpackingpr.htm","accessed":"2026-10-03"},{"q":"Can you rent sleds at White Sands National Park?","a":"Yes: \"Waxed plastic snow saucers work best and can be rented or purchased at the park''s gift shop.\" You may also bring your own. Sledding is allowed in the loop portion of Dunes Drive; \"Sit or lay on the sled, with your feet pointing downhill\" and \"Do not stand up while sledding.\"","source":"https://www.nps.gov/whsa/planyourvisit/sledding.htm","accessed":"2026-10-03"},{"q":"Can you take dogs to White Sands National Park?","a":"Yes, on a leash: \"The leash can be no longer than six feet (2 m).\" \"Do not bring pets inside the visitor center\", pick up after your pet, and never leave a pet in a vehicle - \"Within just ten minutes, the inside vehicle temperature will become 25 degrees warmer than the outside temperature.\"","source":"https://www.nps.gov/whsa/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"When is White Sands National Park closed?","a":"The park closes on Thanksgiving and Christmas Day. Separately, \"White Sands Missile Range regularly conducts military tests. For visitor safety, the only road into the dunefield, Dunes Drive, may be closed for periods of up to three hours during military tests\"; one is listed for October 15, 2026, 7:00 to 9:00 am. \"The park visitor center and gift shop remain open during military test closures.\"","source":"https://www.nps.gov/whsa/planyourvisit/park-closures.htm","accessed":"2026-10-03"},{"q":"How far is White Sands National Park from Las Cruces?","a":"\"Drive time: About 1 hour\" east on US-70; the entrance is \"about 52 miles (84 km) east of Las Cruces on the north side (left-hand side) of the road.\" From Alamogordo it is about 15 miles and 15 minutes; from El Paso, about 1.5 hours.","source":"https://www.nps.gov/whsa/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"What is the closest airport to White Sands National Park?","a":"The NPS names \"El Paso, TX, about 85 miles (136.79 km) from the park\". \"No public transportation serves the park\", and rideshare services typically won''t provide return pickups.","source":"https://www.nps.gov/whsa/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"What should you wear at White Sands National Park?","a":"\"A hat, sunscreen, and long sleeves are all recommended to protect yourself from sunburn in the dunes\" - even in winter; \"Adequate clothing (rain jacket and warm layers)\" because weather shifts fast; and \"Closed toed shoes are suggested. Venomous creatures can be found throughout the dunefield.\" Carry \"One gallon (4 liters) of water per person per day\".","source":"https://www.nps.gov/whsa/planyourvisit/safety.htm","accessed":"2026-10-03"},{"q":"Do you need reservations for White Sands National Park?","a":"Not to enter - the fee is paid at the entrance station. The ticketed ranger program is the Moonlight Hike: book on Recreation.gov or at 1-877-444-6777; \"Tickets are available one month before the day of the tour at 8:00 am Mountain Time\" and \"often sell out in a matter of minutes.\" The Lake Lucero tour (November-March) books the same way.","source":"https://www.nps.gov/whsa/planyourvisit/moonlight-hike.htm","accessed":"2026-10-03"},{"q":"What are the White Sands fossil footprints?","a":"Ice-age trackways of people and megafauna on Lake Otero - \"the largest collection of fossilized human footprints\", showing humans here \"at least 23,000 years ago\". \"Currently the footprints at White Sands are inaccessible\", but an exhibit of \"casted human footprints\" opened at the visitor center in January 2024.","source":"https://www.nps.gov/whsa/learn/nature/fossilized-footprints.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"White Sands National Park: Dunes, Sledding & Moonlight Hikes | TravelWell","meta_description":"The world''s largest gypsum dunefield: Dunes Drive, sled rental, ranger Moonlight Hikes and Lake Lucero tours, plus stays around Alamogordo and Las Cruces.","slug":"white-sands-national-park-new-mexico","primary_keyword":"White Sands National Park","jsonld_type":"TouristDestination"},"hero":{"query":"White Sands National Park gypsum dunes"}}'::jsonb, 71),
  ('carlsbad-caverns-new-mexico', '12A', 'Carlsbad Caverns National Park', 'United States', 'The Big Room and the evening bat flight', 'future', 'verified', 'mountainValley', 'The Southwest Desert', '{"adventure","hiking","wildlife","family","parks"}', '{"dramatic","wild","remote","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Big Room Trail","source":"https://www.nps.gov/cave/planyourvisit/selfguided_tours.htm","accessed":"2026-10-03","si":["family","adventure","senior","hiking"],"booking_route":"Recreation.gov timed entry (recreation.gov/ticket/facility/234637) or 877-444-6777; $15 entrance paid at the visitor center","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":1,"blurb":"\"the largest single cave chamber by volume in North America\"; a \"relatively flat\" 1.25-mile (2 km) trail of \"about 1.5 hours\", or a 0.6-mile, 45-minute shortcut; \"cave formations of all shapes and sizes, and a rope ladder used by explorers in 1924\"; reached by elevator."},{"name":"Bat Flight Program","source":"https://www.nps.gov/cave/planyourvisit/bat_flight_program.htm","accessed":"2026-10-03","si":["wildlife","family","adventure"],"booking_route":"none needed - free, first come first served","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Enjoy a ranger program and watch thousands of bats emerge from Carlsbad Cavern\": Brazilian free-tailed bats, every evening April through October, at the amphitheater \"about a five minute walk from the visitor center\"; \"The program is free and you do not need reservations\"; no electronic devices of any kind."},{"name":"Natural Entrance Trail","source":"https://www.nps.gov/cave/planyourvisit/selfguided_tours.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"Recreation.gov timed entry (recreation.gov/ticket/facility/234637) or 877-444-6777","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":3,"blurb":"1.25 miles (2 km), about one hour, \"extremely steep\" - about \"750 feet (229 m)—equivalent to walking up or down a 75-story building\"; past \"Devil''s Spring, the Whale''s Mouth, and Iceberg Rock\"; \"not recommended for visitors with heart or respiratory conditions\"; last hike-in 2:30 pm."},{"name":"Dawn bat return","source":"https://www.nps.gov/cave/planyourvisit/bat_flight_program.htm","accessed":"2026-10-03","si":["wildlife","adventure"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"Early risers (around 4-6 a.m.) watch bats \"re-enter the cavern with spectacular dives from heights of hundreds of feet. Individual bats may reach speeds of 25 mph (40 km/h) or more.\""},{"name":"King''s Palace ranger-guided tour","source":"https://www.recreation.gov/ticket/facility/234637","accessed":"2026-10-03","si":["adventure","family","culture"],"booking_route":"Recreation.gov (recreation.gov/ticket/facility/234637) when tours resume","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":5,"blurb":"Listed on Recreation.gov at \"$10:00\" adult and \"$5:00\" for ages 6-15, \"available through the park website\"; ⚠️ the NPS fees page reads \"All tours are temporarily suspended until further notice.\""},{"name":"Ranger star viewing and night hikes","source":"https://www.nps.gov/cave/planyourvisit/nightsky.htm","accessed":"2026-10-03","si":["adventure","family","hiking"],"booking_route":"none needed - register at the visitor center desk on the day for night hikes","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"Come explore the night sky through the eye of a powerful telescope. Park rangers will point out space objects near and far\"; free. Night hikes: 1.5 miles round trip after the Bat Flight, age 8+, maximum 12, long pants and red-light headlamps required; \"More dates to be announced\"."},{"name":"Surface desert trails","source":"https://www.nps.gov/cave/surface-hiking-trails.htm","accessed":"2026-10-03","si":["hiking","adventure","wildlife"],"booking_route":"none needed - free park trails","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"Eleven named routes from the Walnut Canyon Overlook and Chihuahuan Desert Nature Trail to Old Guano Trail, Slaughter Canyon, Yucca Canyon and the Guadalupe Ridge Trail; ⚠️ Guadalupe Ridge (visitor center to Slaughter Canyon Trail), Rattlesnake Canyon and Juniper Ridge are closed by flood damage."},{"name":"Rattlesnake Springs","source":"https://www.nps.gov/thingstodo/rattlesnake-springs-picnic-area.htm","accessed":"2026-10-03","si":["wildlife","family","senior"],"booking_route":"none needed - free picnic area","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"Enjoy an oasis of plants and wildlife in a serene setting. You can hear an see a variety of birds that make Rattlesnake Springs their home\"; picnic tables under large cottonwoods, accessible restrooms; open from half an hour before sunrise to half an hour after sunset; about 15 miles (24 km) from the visitor center."},{"name":"Walnut Canyon Desert Drive","source":"https://www.nps.gov/thingstodo/walnut-canyon-desert-drive.htm","accessed":"2026-10-03","si":["motoring","wildlife"],"booking_route":"none needed - free park road (currently closed)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Explore the stories of ancient life, people of the past, and desert survival on a one hour scenic drive\": 9.5 miles one-way, unpaved, closed to RVs, buses and trailers; ⚠️ closed - \"Recent flooding has caused major damage to the road. It is unknown when repairs will begin\"."},{"name":"Backcountry camping by free permit","source":"https://www.nps.gov/cave/planyourvisit/permitsandreservations.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"free permit at the visitor center on the day; not reservable","commission_status":"none","tier_absent_reason":"not-sold","wells":["stay"],"draw_rank":10,"blurb":"\"Only backcountry camping is permitted in the park. Overnight RV parking or car camping is not allowed\"; a \"free backcountry use permit at the visitor center on the day of arrival (no advanced reservations issued)\"; groups up to 10, maximum seven consecutive nights; \"no reliable water source in the park''s backcountry\"."},{"name":"Carlsbad Caverns Trading Company restaurant","source":"https://www.nps.gov/cave/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["family","culinary"],"booking_route":"walk-in counter","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":11,"blurb":"In the visitor center past the gift shop: \"limited food options and bottled, fountain, and hot drinks\", \"open until 3 pm\"; the same concessioner runs the $15-a-day kennel (575-785-2281). No food in the cave: \"Any consumption of food and drink, except plain, unflavored water, is prohibited in any cave.\""},{"name":"Cavern kit: lug-sole shoes and a light jacket","source":"https://www.nps.gov/cave/planyourvisit/things2know.htm","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"affiliate referral to a gear retailer (REI.com via AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":12,"blurb":"The NPS list: \"Closed-toe shoes with good traction (e.g. lug soles) are recommended\"; \"bring a light jacket or sweater as the year-round temperature in the cavern is about 56ºF (13ºC)\"; plain water only - \"No flavored water or drinks\"; strollers not permitted, \"baby backpacks are suggested\"."},{"name":"Desert hike kit: water and sun protection","source":"https://www.nps.gov/cave/surface-hiking-trails.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral (Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":4,"commission_basis":"published","wells":["gear"],"draw_rank":13,"blurb":"For the surface trails the NPS says bring \"Water (2 quarts (1.9 L) per two hiking hours)\" and \"Sun protection (for eyes and skin)\"; \"there is no reliable water source in the park''s backcountry. Pack plenty of water—at least one gallon (3.8 L) per person per day.\""},{"name":"Night-hike kit: red-light headlamp and long pants","source":"https://www.nps.gov/cave/planyourvisit/nightsky.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"affiliate referral to a gear retailer (REI.com via AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":14,"blurb":"For ranger night hikes on \"unimproved, dimly-lit trails\" with thorny vegetation: \"Long pants mandatory; no open-toed shoes; bring water and red light headlamps\"; star viewers are asked to \"use red lens flashlights to preserve night vision.\""},{"name":"Whites City","source":"https://www.nps.gov/cave/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"The park turn-off: \"Turn north from US Hwy 62/180 at White''s City\"; the NPS notes \"A campground and amenities are available seven miles (11 km) from the visitor center in White''s City, New Mexico.\""},{"name":"Whites City RV Park","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone (575) 361-3665","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"Listed by the Carlsbad Chamber of Commerce at \"19 Carlsbad Caverns Hwy\", (575) 361-3665 - the campground the NPS places in Whites City, seven miles from the visitor center. Its own site was not reached (whitescity.com is a parked domain), so nothing else is stated here."},{"name":"Whites City Cavern Inn","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone (855) 516-1090","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"Listed by the Carlsbad Chamber of Commerce under Whites City at \"17 Carlsbad Cavern Hwy\", (855) 516-1090 - the closest listed rooms to the park gate."},{"name":"Cactus Cafe","source":"https://www.carlsbadchamber.com/dining","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":18,"blurb":"Listed by the Carlsbad Chamber of Commerce among locally owned restaurants at \"26 Carlsbad Caverns Hwy, Whites City NM\" - the eat stop at the park turn-off."},{"name":"Carlsbad","source":"https://www.nps.gov/cave/planyourvisit/directions.htm","accessed":"2026-10-03","si":["family","motoring","culture"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":19,"blurb":"The gateway city \"about 20 miles (32 km) south\" of which the park turn-off lies; the NPS sends visitors to \"the Carlsbad Chamber of Commerce at 575-887-6516\" for lodging and dining; local airport with rental cars and taxi service; Greyhound and TNM&O bus lines."},{"name":"Trinity Hotel","source":"https://www.thetrinityhotel.com/","accessed":"2026-10-03","si":["romance","culture","wine"],"booking_route":"own website reservations (thetrinityhotel.com/reservations) or 575-234-9891","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"\"built in 1892 as the First National Bank\", later \"the historic headquarters of the Carlsbad Irrigation District\"; \"nine luxurious hotel suites\"; afternoon wine tasting \"featuring our own Spirit of Seven Rivers varieties made right here along the Pecos Valley\"; 201 South Canal St, 575-234-9891."},{"name":"The Trinity restaurant","source":"https://www.thetrinityhotel.com/","accessed":"2026-10-03","si":["culinary","wine","romance"],"booking_route":"walk-in; phone 575-234-9891","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":21,"blurb":"In the 1892 bank building: \"breakfast, lunch and dinner Tuesday-Sunday\", \"classic dishes and our amazing green chile cheeseburger\" and \"traditional American Italian dishes like lasagna, chicken parmigiana\"; daily wine tasting."},{"name":"Fairfield Inn & Suites by Marriott Carlsbad","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":22,"blurb":"Listed by the Carlsbad Chamber of Commerce at \"2525 S. Canal St\", (575) 887-8000. Marriott''s own page was not fetched (brand pages return 403), so nothing else about the property is stated here."},{"name":"TownePlace Suites Carlsbad","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":23,"blurb":"Listed by the Carlsbad Chamber of Commerce at \"311 Pompa St\", (575) 689-8850. Marriott''s own page was not fetched (brand pages return 403), so nothing else about the property is stated here."},{"name":"Hampton Inn & Suites by Hilton Carlsbad","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":24,"blurb":"Listed by the Carlsbad Chamber of Commerce at \"120 Esperanza Circle\", (575) 725-5700. Hilton''s own page was not fetched (brand pages return 403), so nothing else about the property is stated here."},{"name":"Holiday Inn Express Carlsbad","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":25,"blurb":"Listed by the Carlsbad Chamber of Commerce at \"2210 W Pierce St\", (575) 234-1252. IHG''s own page was not fetched (brand pages return 403), so nothing else about the property is stated here."},{"name":"Candlewood Suites Carlsbad","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":26,"blurb":"Listed by the Carlsbad Chamber of Commerce at \"3711 San Jose Blvd\", (575) 941-3711. IHG''s own page was not fetched (brand pages return 403), so nothing else about the property is stated here."},{"name":"Brantley Lake State Park","source":"https://www.emnrd.nm.gov/spd/find-a-park/brantley-lake-state-park/","accessed":"2026-10-03","si":["family","motoring","wildlife","adventure"],"booking_route":"ReserveAmerica (newmexicostateparks.reserveamerica.com); pay stations on site","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":27,"blurb":"\"Located fifteen miles North of Carlsbad\", \"the southernmost lake in New Mexico\": 51 developed campsites - 38 water and electric (30 amp), 10 water and electric (50 amp), 3 full hookup (50 amp) - plus shoreline and boat-in primitive camping; boating, kayaking, fishing and \"exceptional bird watching\"."},{"name":"Bud''s Place RV Park","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone (888) 204-4470","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"Listed by the Carlsbad Chamber of Commerce under RV Parks/Campgrounds at \"900 Standpipe Rd\", (888) 204-4470. Its own site was not fetched, so nothing else is stated here."},{"name":"Ellipse Global Lodge & RV Park","source":"https://www.carlsbadchamber.com/lodging","accessed":"2026-10-03","si":["motoring"],"booking_route":"phone (575) 649-3883","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"Listed by the Carlsbad Chamber of Commerce under RV Parks/Campgrounds at \"26 Quahada Rd.\", (575) 649-3883. Its own site refused the connection, so nothing else is stated here."},{"name":"Living Desert Zoo and Gardens State Park","source":"https://www.emnrd.nm.gov/spd/find-a-park/living-desert-zoo-and-gardens-state-park/","accessed":"2026-10-03","si":["wildlife","family","senior"],"booking_route":"pay at the gate","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":30,"blurb":"\"This native wildlife zoo exhibits more than 40 species of animals and hundreds of species of plants native to the Chihuahuan Desert\" - bald eagles, mountain lions, wolves and black bears; 1504 Skyline Dr., Carlsbad; 9 am-5 pm, last entry 3:30 pm; adults $10, children 7-12 $5, 6 and under free."},{"name":"Guadalupe Mountains National Park","source":"https://www.nps.gov/gumo/index.htm","accessed":"2026-10-03","si":["hiking","adventure","group"],"booking_route":"none needed to visit; campgrounds per the NPS","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":31,"blurb":"\"the world''s most extensive Permian fossil reef, the four highest peaks in Texas\"; Carlsbad''s visitor site places it \"55 miles away across the Texas border\" with \"two campgrounds\" offering individual and group sites."},{"name":"Guadalupe Mountain Brewing Co.","source":"https://www.carlsbadchamber.com/dining","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"Listed by the Carlsbad Chamber of Commerce among member restaurants at \"3324 National Parks Hwy\" - on the highway toward the park. Its own site timed out (HTTP 522), so nothing else is stated here."},{"name":"Blue House Bakery & Cafe","source":"https://www.carlsbadchamber.com/dining","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"Listed by the Carlsbad Chamber of Commerce among member restaurants at \"609 N Canyon St.\", Carlsbad."},{"name":"Red Chimney BBQ","source":"https://www.carlsbadchamber.com/dining","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"Listed by the Carlsbad Chamber of Commerce among member restaurants at \"817 N. Canal St.\", Carlsbad."},{"name":"Lucky Bull Grill","source":"https://www.carlsbadchamber.com/dining","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"Listed by the Carlsbad Chamber of Commerce among member restaurants at \"220 W. Fox St.\", Carlsbad."},{"name":"Flume at Stevens Inn","source":"https://www.carlsbadchamber.com/dining","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"Listed by the Carlsbad Chamber of Commerce among member restaurants at \"1829 S. Canal St.\", the address of the Stevens Inn on the same Chamber''s lodging list."},{"name":"Lucy''s Mexicali","source":"https://www.carlsbadchamber.com/dining","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"Listed by the Carlsbad Chamber of Commerce among member restaurants at \"710 S. Canal St.\", Carlsbad."}],"faq":[{"q":"Do you need reservations for Carlsbad Caverns National Park?","a":"Yes, for the cavern: \"A timed entry reservation must be purchased to access Carlsbad Cavern\" ($1.00, required year-round). Recreation.gov releases tickets \"30 days in advance at 8 AM MT\" and \"The park does not offer stand-by or wait list tickets.\"","source":"https://www.recreation.gov/ticket/facility/234637","accessed":"2026-10-03"},{"q":"How much does it cost to go to Carlsbad Caverns National Park?","a":"\"Adults 16 years and older are $15, children 15 and younger are free. There are additional fees for guided tours.\" The timed-entry reservation adds $1.00.","source":"https://www.nps.gov/cave/faqs.htm","accessed":"2026-10-03"},{"q":"Can you camp at Carlsbad Caverns National Park?","a":"Only in the backcountry: \"Carlsbad Caverns National Park offers no overnight lodging or campgrounds.\" \"Primitive camping is allowed in the backcountry only, and requires a free permit which is issued at the park''s visitor center when you arrive (not reservable in advance).\" A campground is available in White''s City, seven miles from the visitor center.","source":"https://www.nps.gov/cave/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03"},{"q":"How long does it take to tour Carlsbad Caverns?","a":"The Big Room Trail is 1.25 miles and takes \"about 1.5 hours (on average)\", or 45 minutes on the 0.6-mile shortcut; the Natural Entrance Trail is 1.25 miles and \"about one hour\". With limited time, the NPS suggests: \"Enter and exit the cavern by elevator and walk the Big Room Trail.\"","source":"https://www.nps.gov/cave/planyourvisit/selfguided_tours.htm","accessed":"2026-10-03"},{"q":"What should I wear to Carlsbad Caverns?","a":"\"Closed-toe shoes with good traction (e.g. lug soles) are recommended\", and \"You may want to bring a light jacket or sweater as the year-round temperature in the cavern is about 56ºF (13ºC).\"","source":"https://www.nps.gov/cave/planyourvisit/things2know.htm","accessed":"2026-10-03"},{"q":"Is Carlsbad Caverns National Park dog friendly?","a":"Only in a limited way: \"Pets are not allowed in the cavern, on unpaved park trails on the surface, off road, during the Bat Flight Program, or in the visitor center.\" A concession kennel charges \"$15/day\", 9:00 am-3:30 pm.","source":"https://www.nps.gov/cave/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"What is the closest airport to Carlsbad Caverns National Park?","a":"Carlsbad has a local airport with rental cars and taxi service. The NPS lists Roswell at 103 miles, El Paso at 151 miles, Midland at 194 miles and Albuquerque at 304 miles.","source":"https://www.nps.gov/cave/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you take pictures in Carlsbad Caverns?","a":"\"Yes, and you may use a flash. Tripods, bipods, and monopods are prohibited.\" At the Bat Flight Program, though, \"Electronic devices are not allowed\", including \"cameras of any kind\".","source":"https://www.nps.gov/cave/faqs.htm","accessed":"2026-10-03"},{"q":"Is Carlsbad Caverns National Park open on Thanksgiving?","a":"No: \"The park is open every day, except Thanksgiving, Christmas, and New Year''s days, weather and road conditions permitting.\"","source":"https://www.nps.gov/cave/faqs.htm","accessed":"2026-10-03"},{"q":"What are Carlsbad Caverns National Park''s hours?","a":"Visitor center \"9 am–5 pm\". The last cavern entrance ticket is sold at 2:15 pm and the last cavern entrance is 2:30 pm; the elevator runs in 9:30 am-2:30 pm, and the \"Last Elevator OUT of the Cavern\" is 4:45 pm.","source":"https://www.nps.gov/cave/planyourvisit/hours.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Carlsbad Caverns National Park: Big Room, Bat Flight & Where to Stay | TravelWell","meta_description":"Timed entry opens 30 days ahead: the Big Room, the steep Natural Entrance, the April-October bat flight, and RV parks and hotels in Whites City and Carlsbad.","slug":"carlsbad-caverns-national-park-new-mexico","primary_keyword":"Carlsbad Caverns National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Carlsbad Caverns Big Room"}}'::jsonb, 72)
