  ('petrified-forest-arizona', '12A', 'Petrified Forest National Park', 'United States', 'Painted Desert, petrified logs and Route 66', 'future', 'verified', 'mountainValley', 'The Southwest Desert', '{"motoring","culture","hiking","family","parks"}', '{"dramatic","remote","historic","rugged"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Painted Desert overlooks","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["motoring","family","senior"],"booking_route":"none needed - roadside overlooks inside the park (park entrance fee applies)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"Enjoy spectacular views of the Painted Desert from several overlooks in this area\"; Kachina Point at the Painted Desert Inn overlooks the red Painted Desert. Westbound I-40 drivers \"take Exit 311, drive the 28 miles through the park and connect with Highway 180 at the south end\"."},{"name":"Blue Mesa","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["hiking","motoring","family"],"booking_route":"none needed - park trail and loop road","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Walk the 1 mi (1.6 km) trail and/or drive the 3.5 mi (5.6 km) loop road to explore colorful geology.\""},{"name":"Crystal Forest","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - paved park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"Many petrified logs glimmer with quartz crystals along a paved 0.75 mi (1.2 km) loop trail.\" Taking wood is prohibited: \"Although it seems as if there is an endless supply of petrified wood here, it is limited.\""},{"name":"Historic Route 66 alignment","source":"https://www.nps.gov/pefo/learn/historyculture/historic-route-66.htm","accessed":"2026-10-03","si":["motoring","culture","family"],"booking_route":"none needed - roadside pull-out on the park road","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"A 1932 Studebaker sits where famed Route 66 once cut through the park.\" \"Petrified Forest National Park is the only park in the National Park System containing a section of Historic Route 66\"; \"A line of telephone poles still marks the road bed of Historic Route 66 within the park.\""},{"name":"Painted Desert Inn National Historic Landmark","source":"https://www.nps.gov/pefo/learn/historyculture/pdi.htm","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"none needed - museum inside the park (park entrance fee applies)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"This trading post turned inn turned museum offers exhibits on the park''s recent human history.\" Built of petrified wood and native stone by Herbert David Lore (registered 1924), rebuilt by the Civilian Conservation Corps in the 1930s, reopened \"in the late 1940s under the renowned Fred Harvey Company\" with interiors by Mary Colter and dining-room murals by \"renowned Hopi artist\" Fred Kabotie; a National Historic Landmark since 1987. Open 9am to 4pm."},{"name":"Newspaper Rock","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["culture","family","pilgrimage"],"booking_route":"none needed - overlook on the park road","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"Look down from an overlook to see over 650 petroglyphs, some as old as 2000 years.\""},{"name":"Puerco Pueblo","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["culture","hiking","family"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"View ancestral Puebloan homes and petroglyphs along a 0.3 mi (0.5 km) loop trail.\" Accessible restroom on site."},{"name":"Agate Bridge","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"none needed - roadside stop","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"See a 110 ft (34 m) petrified log spanning a gully.\""},{"name":"Rainbow Forest Museum and Giant Logs Trail","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["family","culture","senior"],"booking_route":"none needed - museum and trail at the south entrance","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Study paleontological exhibits in the museum and walk a 0.4 mi (0.6 km) loop trail.\" The demonstration lab, where paleontologists prepare fossils, is \"Open Thursday, Friday, and Saturday 9 am-12 pm and 1 pm-4 pm\"; touch tables and open-captioned films."},{"name":"Long Logs and Agate House","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["hiking","culture"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"A 2.6 mi (4.2 km) trail showcases some of the longest, most colorful petrified logs in the park and a partially reconstructed pueblo originally built of petrified wood.\""},{"name":"Jasper Forest","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"none needed - overlook on the park road","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"Enjoy a panoramic view of an area with a high concentration of petrified wood.\""},{"name":"Wilderness backpacking by free permit","source":"https://www.nps.gov/pefo/planyourvisit/backpacking.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"free same-day permit in person at a visitor center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"The backpacking wilderness permit is free. You may obtain it in person from either visitor centers, Painted Desert Inn or Rainbow Forest Museum, on the day that you want to backpack.\" \"The permits are available until 4:30 pm.\" \"Group camping is limited to 8\"; camp \"at least a half mile from your vehicle\"; \"No wood or charcoal fires are allowed. Please use fuel stoves.\""},{"name":"Painted Desert Visitor Center","source":"https://www.nps.gov/pefo/planyourvisit/placestogo.htm","accessed":"2026-10-03","si":["family","senior","motoring"],"booking_route":"none needed - north entrance off I-40 Exit 311","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"\"Stop for historic architecture, information, bookstore, gift shop, food, and gas.\" Open 8am to 5pm; open-captioned park film; BARK Ranger certificates for dogs."},{"name":"Painted Desert Diner","source":"https://www.nps.gov/pefo/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["culinary","motoring","family"],"booking_route":"walk-in at the Painted Desert Visitor Center","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":14,"blurb":"\"The Painted Desert Diner and a convenience store for snacks are located next to the Painted Desert Visitor Center.\" \"Limited snacks are also available for purchase at the curio shop in Rainbow Forest.\" Accessible restroom at the diner."},{"name":"Kit for the desert drive and trails","source":"https://www.nps.gov/pefo/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","motoring","family"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":15,"blurb":"The park''s own list: \"Take all the water you will need when traveling through the park and when hiking... One gallon per person per day is recommended during summer months when hiking.\" \"Wear sunscreen to protect yourself from the Arizona sun. The sun''s rays are stronger due to the high elevations.\" \"Be prepared! There is no water and little shade in the backcountry.\""},{"name":"Kit for a wilderness overnight","source":"https://www.nps.gov/pefo/planyourvisit/backpacking.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":16,"blurb":"The backpacking rules set the kit: water at \"One gallon per person per day is recommended during summer months\"; \"No wood or charcoal fires are allowed. Please use fuel stoves\"; camp \"at least a half mile from your vehicle\". \"Temperatures vary greatly from extreme heat to bitter cold. Be prepared for rapidly changing conditions.\""},{"name":"Wigwam Motel","source":"https://www.sleepinawigwam.com/","accessed":"2026-10-03","si":["motoring","culture","family"],"booking_route":"own website booking (Book Now) or reservations@sleepinawigwam.com; \"24 hour cancellation policy\"","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"811 W Hopi Dr, Holbrook: \"Fifteen white concrete teepees built in 1950\", \"one of only a handful of wigwam villages left on Route 66\"; \"Built By Chester Evert Lewis\" and \"Currently Operated By His Family\" as Wigwam Village #6. Queen Bed Wigwam $105 a night plus tax, Double Full Wigwam $115. Discover Holbrook: \"Reserve as early as you can.\" (928) 524-3048."},{"name":"La Posada Hotel","source":"https://www.laposada.org/","accessed":"2026-10-03","si":["culture","romance","rail","senior","group"],"booking_route":"own website online reservations or 1-928-289-4366","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":18,"blurb":"303 East 2nd Street, Route 66, Winslow: \"In 1930, La Posada (The Resting Place) opened to great acclaim as the crown jewel of the Fred Harvey series of luxury railroad hotels\"; architect Mary E.J. Colter \"considered it to be her finest work.\" 1-928-289-4366."},{"name":"The Turquoise Room","source":"https://www.laposada.org/","accessed":"2026-10-03","si":["culinary","romance","culture"],"booking_route":"through La Posada, 1-928-289-4366","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":19,"blurb":"La Posada''s restaurant \"serves regional contemporary Southwestern cuisine and is considered by many to be the finest restaurant in the Four Corners region.\""},{"name":"Holbrook - Petrified Forest KOA Journey","source":"https://maps.campendium.com/us/holbrook-az/camping-rv/holbrook-petrified-forest-koa-journey","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"koa.com online reservations (not fetched - HTTP 403) or (928) 524-6689","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"102 Hermosa Dr., Holbrook: 119 sites; \"30 Amp,\" \"50 Amp,\" and \"Full Hookups\"; pull-throughs to \"100 feet\", maximum vehicle 85 feet; pool, dog park, playground, laundry, showers, store. \"Easy access to I-40 gets you to the Painted Desert and Petrified Forest National Park (20 minutes).\" (928) 524-6689. koa.com refused the fetch (HTTP 403), so this is sourced to Campendium."},{"name":"OK RV Park","source":"https://maps.campendium.com/us/holbrook-az/camping-rv/ok-rv-park","accessed":"2026-10-03","si":["motoring"],"booking_route":"phone (928) 524-3226","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"1576 Roadrunner Rd., Holbrook: \"30 Amp, 50 Amp, Full Hookups, Water, Sewer\"; \"Picnic tables, Pull thru, Big rigs\", recreation hall, laundry, showers, dog walk and free wifi; 80 campsites, rigs to 45 feet; accepts \"AAA, Good Sam, FMCA, AARP, Military Discounts\". Local First Arizona: \"well-equipped haven for RV enthusiasts passing through Holbrook. Pets welcome!\" (928) 524-3226."},{"name":"Gateway to the Petrified Forest RV Resort","source":"https://maps.campendium.com/us/holbrook-az/camping-rv/gateway-to-the-petrified-forest-rv-resort","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone (928) 524-2002","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":22,"blurb":"7551 Ramada Rd., Holbrook: 31 full-hookup pull-through RV sites and 7 tent sites, 30 and 50 amp, rigs to 45 feet, general store and community fire pit; \"22 miles from Petrified Forest National Park\"; open year-round. (928) 524-2002."},{"name":"Homolovi State Park","source":"https://azstateparks.com/homolovi/","accessed":"2026-10-03","si":["culture","hiking","family"],"booking_route":"Arizona State Parks reservations (azstateparks.com/reserve) or same day by phone 928-289-4106","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":23,"blurb":"I-40 Exit 257, 1.5 mi. N on Hwy 87: \"''Homolovi'' is Hopi for ''Place of the Little Hills'' - the traditional name for Winslow, Arizona\"; a research center for late Hopi migration (1200s to late 1300s) with a campground. \"Homolovi State Park no longer accepts self-pay registrations for camping. Same-day reservations can be made by coming to the visitor center in person or by calling the park office at 928-289-4106 by 4:45 p.m.\" Entry $10 per vehicle (1 person), $20 (2-4 people)."},{"name":"Holbrook","source":"https://discoverholbrook.com/","accessed":"2026-10-03","si":["motoring","culture"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":24,"blurb":"\"Holbrook is a small Route 66 town in northeastern Arizona and the county seat of Navajo County, sitting right off Interstate 40.\" \"The Painted Desert entrance is about 26 miles from town off I-40 and the Rainbow Forest entrance is about 20 miles south on Highway 180.\" The NPS route from eastbound I-40: \"take Exit 285 into Holbrook then travel 19 miles on Highway 180 South to the park''s south entrance\"."},{"name":"Navajo County Historic Courthouse Museum","source":"https://discoverholbrook.com/things-to-do/","accessed":"2026-10-03","si":["culture","senior"],"booking_route":"visit in Holbrook (admission not read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":25,"blurb":"Holbrook: \"Built in 1898 of rough native stone\"."},{"name":"Jim Gray''s Petrified Wood Co.","source":"https://discoverholbrook.com/things-to-do/","accessed":"2026-10-03","si":["culture","family"],"booking_route":"walk-in shop","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop"],"draw_rank":26,"blurb":"Holbrook, \"on Highway 180 just south of downtown\" - the legal way to take petrified wood home: the NPS says \"Souvenirs are available at local gift shops\", since collecting in the park is prohibited."},{"name":"Big Fella''s BBQ","source":"https://discoverholbrook.com/things-to-do/","accessed":"2026-10-03","si":["culinary","motoring"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":27,"blurb":"Holbrook: \"real-deal, slow-smoked Texas brisket right on Route 66\"."},{"name":"Colonel Mustard Hot Dogs","source":"https://discoverholbrook.com/things-to-do/","accessed":"2026-10-03","si":["culinary","motoring","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":28,"blurb":"Holbrook: \"proper Chicago-style dogs out of a beautifully restored 1958 Richfield station\"."},{"name":"Mesa Italiana","source":"https://discoverholbrook.com/things-to-do/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"Holbrook: \"hand-tossed pizza and hearty Italian classics\"."},{"name":"Wayside Soda Shop","source":"https://discoverholbrook.com/things-to-do/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (Wednesdays only)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":30,"blurb":"Holbrook: an \"old-fashioned soda fountain open only on Wednesdays\"."},{"name":"Studio 66 Cafe","source":"https://discoverholbrook.com/things-to-do/","accessed":"2026-10-03","si":["culinary","motoring"],"booking_route":"walk-in or drive-through","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"Holbrook: a \"family-run coffee bar with a drive-through and a bakery case\"."},{"name":"Route Sixty Sips","source":"https://discoverholbrook.com/things-to-do/","accessed":"2026-10-03","si":["culinary","motoring"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"Holbrook: a coffee shop pouring Route 66-themed drinks."},{"name":"Arizona Sake","source":"https://discoverholbrook.com/things-to-do/","accessed":"2026-10-03","si":["culinary","wine"],"booking_route":"private tastings (booking method not read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"Holbrook: a \"tiny one-man brewery\" offering private tastings."}],"faq":[{"q":"How much is it to get into Petrified Forest National Park?","a":"A private vehicle is \"$25.00\" and admits \"one private, non-commercial vehicle (15-passenger capacity or less) and all occupants. Valid for 7 days.\" A motorcycle is $20 and a person on foot or bicycle $15, with \"Youth 15 and under\" free. \"This park does not accept cash.\"","source":"https://www.nps.gov/pefo/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you drive through Petrified Forest National Park?","a":"Yes: \"The drive through the park is 28 miles. Driving the road at the posted speed limit without stopping takes about an hour.\" The main road takes larger vehicles and trailers, though some pull-outs are small.","source":"https://www.nps.gov/pefo/faqs.htm","accessed":"2026-10-03"},{"q":"How long does it take to visit Petrified Forest National Park?","a":"\"Most visitors spend 2 to 3 hours enjoying the park, while others sometime return over multiple days.\"","source":"https://www.nps.gov/pefo/faqs.htm","accessed":"2026-10-03"},{"q":"Can you camp in Petrified Forest National Park?","a":"Only by backpacking. \"There is no RV, car, or front country camping in the park. There is no boondocking, dispersed or ''primitive'' camping.\" Backpackers hike into the Petrified Forest National Wilderness Area on a permit that \"is free\" and is issued until 4:30 pm.","source":"https://www.nps.gov/pefo/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03"},{"q":"What time can you enter Petrified Forest National Park?","a":"\"Park hours are 8am to 5pm.\" \"The park is open year round except Thanksgiving and Christmas.\"","source":"https://www.nps.gov/pefo/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"What time zone is Petrified Forest National Park in?","a":"\"Times are Mountain Standard year round. Most of Arizona does not observe Daylight Saving.\"","source":"https://www.nps.gov/pefo/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"Is Petrified Forest National Park dog friendly?","a":"Yes: \"Pets are allowed everywhere in the park except inside buildings. Pets must be on a leash, no longer than six feet, and the owner must clean up after their pet.\" Visitor centers offer BARK Ranger certificates.","source":"https://www.nps.gov/pefo/faqs.htm","accessed":"2026-10-03"},{"q":"How far is Petrified Forest National Park from Phoenix?","a":"The NPS gives \"259 miles\" from Phoenix by Interstates 17 North and 40 East through Flagstaff, or \"215 miles\" from the east side of Phoenix by Highways 87, 260, 377 and 180.","source":"https://www.nps.gov/pefo/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"What is the closest major airport to Petrified Forest National Park?","a":"The NPS lists major airports in Phoenix, Arizona and Albuquerque, New Mexico; smaller airports in Flagstaff and Show Low, Arizona and Gallup, New Mexico; and a small airport in Holbrook. \"There is no public transportation to or within the park.\"","source":"https://www.nps.gov/pefo/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"Can you hike in Petrified Forest National Park?","a":"Yes - short loops such as Blue Mesa (1 mile), Crystal Forest (0.75 mile, paved) and Giant Logs (0.4 mile), the 2.6-mile Long Logs and Agate House trail, and for a full day \"Choose an Off the Beaten Path hike\" or go \"backpacking in the park Wilderness Area.\"","source":"https://www.nps.gov/pefo/planyourvisit/itineraries.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Petrified Forest National Park: Painted Desert, Route 66 & Stays | TravelWell","meta_description":"A 28-mile drive past petrified logs, Blue Mesa, Newspaper Rock and the only Route 66 in a national park, with RV parks and the Wigwam Motel in Holbrook.","slug":"petrified-forest-national-park-arizona","primary_keyword":"Petrified Forest National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Petrified Forest National Park Painted Desert petrified logs"}}'::jsonb, 73),
  ('zion-utah', '12A', 'Zion National Park', 'United States', 'A canyon you enter by shuttle, a river you hike in, and a ridge you need a lottery permit to climb', 'future', 'verified', 'mountainValley', 'Utah Canyon Country', '{"hiking","adventure","glamping","family","parks"}', '{"dramatic","rugged","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Angels Landing (permit required past Scout Lookout)","source":"https://www.nps.gov/zion/planyourvisit/angels-landing-hiking-permits.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"the chained ridge hike from the Grotto (Shuttle Stop 6); permits by seasonal or day-before lottery, $6 application covering up to 6 people plus $3 per person if selected; the NPS notes \"Since 1930, the majority of deadly accidents have taken place on this section of trail\""},{"name":"The Narrows, bottom-up from the Temple of Sinawava","source":"https://www.nps.gov/zion/planyourvisit/thenarrows.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"no permit needed: hike in the river for an hour, or the \"strenuous, ten-mile round trip\" to Big Spring; closed to all travel over 150 CFS and for at least two hours after a flash flood warning is lifted"},{"name":"The Narrows, top-down from Chamberlain''s Ranch","source":"https://www.nps.gov/zion/planyourvisit/thenarrows.htm","accessed":"2026-10-02","si":["expedition"],"tier_absent_reason":"not-sold","blurb":"a 16-mile through-hike that needs a wilderness permit and separately arranged transport to the trailhead"},{"name":"Zion Canyon Shuttle","source":"https://www.nps.gov/zion/planyourvisit/zion-canyon-shuttle-system.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"the only way up the Zion Canyon Scenic Drive in shuttle season - nine stops from the Visitor Center to the Temple of Sinawava, first-come, first-served, no reservation"},{"name":"Riverside Walk","source":"https://home.nps.gov/zion/planyourvisit/accessibility.htm","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"two miles round trip from the Temple of Sinawava along the river toward the Narrows, mostly paved and wheelchair accessible with assistance"},{"name":"Pa''rus Trail","source":"https://www.nps.gov/thingstodo/hike-pa-rus-trail.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"1.6 miles one way, paved, minimal elevation - the park''s most accessible trail, open to wheelchairs, leashed pets and bicycles"},{"name":"Emerald Pools (Lower, Middle, Upper)","source":"https://www.nps.gov/thingstodo/hike-upper-emerald-pools.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"three linked trails near Zion Lodge - Lower is a rough paved path to ephemeral waterfalls; Middle and Upper climb sandstone ledges to the base of the canyon walls"},{"name":"Canyon Overlook Trail","source":"https://www.nps.gov/thingstodo/hike-canyon-overlook.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"a moderate 1-mile trail on the East Side ending at a fenced cliff edge facing main Zion Canyon and the Towers of the Virgin"},{"name":"Kolob Canyons","source":"https://www.nps.gov/zion/planyourvisit/kolob-canyons.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"Exit 40 on I-15, 40 miles north of Zion Canyon - a five-mile scenic drive past 2,000-foot cliff walls and 20+ miles of trail, with its own visitor center"},{"name":"The Subway (Left Fork of North Creek)","source":"https://www.nps.gov/zion/planyourvisit/thesubway.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"a day-use-only canyon route that requires a wilderness permit, issued by seasonal lottery or daily lottery and collected in person at the Zion Canyon Visitor Center"},{"name":"Zion Lodge","source":"https://www.nps.gov/zion/planyourvisit/lodging.htm","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"the only lodging inside the park - 76 hotel rooms, 6 suites and 40 historic cabins, with the Red Rock Grill and Castle Dome Cafe; operated by POWDR"},{"name":"Under Canvas Zion","source":"https://www.undercanvas.com/camps/zion/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"safari-style tents with ensuite bathrooms and wood stoves in Virgin, about 8 miles north of the main entrance; Stargazer tents with a viewing window; 2026 season March 12 to November 8"},{"name":"Springdale and the Springdale Line","source":"https://www.nps.gov/zion/planyourvisit/zion-canyon-shuttle-system.htm","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"the gateway town at the south entrance, linked to the park''s pedestrian entrance by a free shuttle every 10-15 minutes during shuttle season"},{"name":"Zion Adventures, Springdale","source":"https://www.zionadventures.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"outfitter since 1996 at 36 Lion Blvd - Narrows dry-suit rentals, guided canyoneering, climbing, via ferrata, guided Angels Landing and Narrows hikes, e-bikes"},{"name":"Zion Art Invitational, November 2-7, 2026","source":"https://www.zionpark.org/pages/artinvitational","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"the Zion Forever Project''s week of sixteen landscape artists painting in the park, with demonstrations, a gala and art sale, and a Wet Paint and Silent Auction"},{"name":"AutoCamp Zion","source":"https://autocamp.com/location/zion/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"Airstreams, modern cabins and BaseCamps (an Airstream suite plus canvas tent for up to six) at 1322 East State Route 9, Virgin; pool, clubhouse, seasonal bike rentals"},{"name":"Zion Wildflower Resort","source":"https://zionwildflower.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"Grand Mesa canvas tents with private bathrooms and decks, covered wagons and bungalows at 100 Kolob Terrace Rd, Virgin - about 15 minutes to the park entrance by its own account"},{"name":"Zion White Bison Glamping & RV Resort","source":"https://zionwhitebisonresort.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"luxury teepees with private hot tubs, covered wagons and Anasazi-inspired cliff dwellings at 400 UT-9, Virgin, beside a white bison sanctuary; also the Zion Corridor Park & Ride with shuttle service to Springdale"},{"name":"Zion Ponderosa Ranch Resort (glamping and Conestoga wagons)","source":"https://www.zionponderosa.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"canvas glamping tents for up to six, Conestoga wagons, tiny homes and cabins at 6,500 feet near Orderville on Zion''s east side - billed as the closest full-service resort to the East Entrance"},{"name":"Zen Zion Domes, Glendale","source":"https://www.zionstays.com/properties/zen-zion-domes","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"two geodesic domes sleeping four each, with kitchenette, loft, shared hot tub and a cold plunge in the Virgin River; listed as 20 minutes from Zion National Park"},{"name":"Zion Glamping Adventures, Hildale","source":"https://www.hipcamp.com/en-US/land/utah-zion-glamping-adventures-3j29hl5y","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"26 acres with 20 canvas glamping tents, two rock-cave cabins with jacuzzis and RV sites; listed as about an hour''s drive from Zion Canyon"},{"name":"Watchman Campground (NPS)","source":"https://www.nps.gov/zion/planyourvisit/campgrounds-in-zion.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"the in-park campground beside the Zion Canyon Visitor Center, open year-round, reservations up to six months ahead on recreation.gov"},{"name":"South Campground (NPS)","source":"https://www.nps.gov/zion/planyourvisit/campgrounds-in-zion.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"in-park campground in Zion Canyon that closes seasonally; reservations up to two weeks ahead on recreation.gov"},{"name":"Lava Point Campground (NPS)","source":"https://www.nps.gov/zion/planyourvisit/campgrounds-in-zion.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"high on the Kolob Terrace Road about an hour from Zion Canyon; closes seasonally, reservations up to two weeks ahead on recreation.gov"},{"name":"Zion Canyon Campground & RV Resort, Springdale","source":"https://www.zioncamp.com/zion-national-park-camping/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"131 powered RV spots, 15 tent sites, cabins and lodges at 479 Zion Park Blvd, run by the Ferber family since 1974"},{"name":"Zion River Resort, Virgin","source":"https://www.zionriverresort.com/accommodations/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"40 full-hookup concrete RV pads and climate-controlled cabins with private bathrooms at 551 E State Route 9, with pool and hot tub"},{"name":"Gateway Luxury RV Resort & Casitas, La Verkin","source":"https://gatewayrvresort.com/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"81 full-hookup RV sites and luxury casitas where SR17 meets SR9, about 20 minutes from the south entrance; pool, hot tub, pickleball"},{"name":"St. George/Hurricane KOA Journey","source":"https://koa.com/campgrounds/st-george/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"the closest KOA to Zion, just over 20 minutes away and open all year, with deluxe cabins, full-hookup RV sites and tent sites"},{"name":"Jellystone Park Camp-Resort Zion Utah, Hurricane","source":"https://zionutahjellystonepark.com/cabins/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Yogi Bear cabins including a two-bedroom glamping cabin and ADA cabins at 505 South Sand Hollow Rd, with a Water Zone and floating obstacle course"},{"name":"Zion West RV Park, Leeds","source":"https://greaterzion.com/accommodations/zion-west-rv-park/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"full-hookup pull-through and back-in RV sites plus tent sites in Leeds, roughly 30 to 45 minutes from Zion"},{"name":"Canyon Trail Rides (park concessioner)","source":"https://www.nps.gov/zion/planyourvisit/horseback-riding.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"1-hour or 3-hour guided horse and mule rides along the Virgin River and Sand Bench Trail, mid-March through October 31, weather dependent"},{"name":"Zion Outfitter, Springdale","source":"https://zionoutfitter.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"Narrows gear rentals plus bike and e-bike rentals at 7 Zion Park Blvd, just outside the main entrance, open daily 7am to 8pm"},{"name":"Zion Guru, Springdale","source":"https://www.zionguru.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"guided canyoneering, Narrows hikes, rock climbing, e-bike tours, photography and yoga hikes, plus Narrows and e-bike rentals, at 1013 Zion Park Blvd"},{"name":"Zion Rock & Mountain Guides, Springdale","source":"https://www.zionrockguides.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"guided climbing, canyoneering, hiking, jeep and bike trips, and trailhead shuttles to Chamberlain''s Ranch, the West Rim and Kolob''s Lee Pass, from 1458 Zion Park Blvd"},{"name":"Zion Cycles, Springdale","source":"https://www.zioncycles.com/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"road, e-bike, gravel, mountain, kids and tandem e-bike rentals, guided bike tours and repair at 868 Zion Park Blvd"},{"name":"East Zion Adventures","source":"https://eastzionadventures.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"jeep tours to the East Rim, horseback rides, Elkheart Canyon canyoneering, guided hikes and UTV tours from Zion''s east side; states many tours can accommodate wheelchairs"},{"name":"Zion Canyon Brew Pub, Springdale","source":"https://zionbrewery.com/zionbrewpub/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"Zion Brewery''s brewpub at 95 Zion Park Blvd - house ales, scratch pub food and live music by the park entrance, open daily 11:30 am to 10 pm"},{"name":"Zion Canyon Farmers Market, Springdale","source":"https://www.foraged.com/farmers-markets/utah/springdale/zion-canyon-farmers''-market","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"a Saturday-morning seasonal market of local produce on the lawn at 1212 Zion Park Blvd; current-season dates not confirmed"},{"name":"Grafton ghost town and the Smithsonian Butte Back Country Byway","source":"https://www.blm.gov/visit/smithsonian-butte-national-back-country-byway","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"a 9.25-mile BLM byway from Rockville, with a 1.8-mile side trip to Grafton, first settled in 1861, with restored buildings; BLM: \"This route often becomes impassable during heavy rain and periods of inclement winter weather\""},{"name":"King''s Landing Bistro, Springdale","source":"https://www.kingslandingbistro.com/","accessed":"2026-10-02","si":["culinary","romance","wine"],"booking_route":"phone (435-772-7422); own online form for groups of 6+; smaller parties walk-in; credit card held, $50 per guest late-cancellation fee","tier_absent_reason":"not-sold","blurb":"Seasonal, chef-driven cuisine by Chef King and Chef Nguyen with craft cocktails and curated wines at 1515 Zion Park Blvd; dinner Tuesday to Saturday 5-9 pm."},{"name":"Bit and Spur Restaurant and Saloon, Springdale","source":"https://www.bitandspur.com/","accessed":"2026-10-02","si":["culinary","group","culture"],"booking_route":"own site ''Make a Reservation'' link (platform not identified); phone (435) 772-3498","tier_absent_reason":"not-sold","blurb":"Restaurant and saloon at 1212 Zion Park Blvd serving Southwest food and a Prickly Pear Margarita, open 7 days 5-9:30 pm with a late-night menu and a taco truck."},{"name":"Water Canyon Winery (Springdale tasting room and Hildale vineyard cafe)","source":"https://www.watercanyonwinery.com/","accessed":"2026-10-02","si":["wine","culinary","romance"],"booking_route":"tastings walk-in, no reservation; winery cafe reservations by phone 435-862-1825","tier_absent_reason":"not-sold","blurb":"Family-owned all-natural winery making wine without added sulfites, preservatives or enzymes; a Springdale tasting room open daily 3-8 pm plus the Hildale vineyard with a seasonal winery cafe."},{"name":"Silver Reef Brewing Co. Craft and Kitchen, St. George","source":"https://greaterzion.com/brews-with-a-view-the-greater-zion-craft-beer-crawl/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"walk-in (operator site https://sgbev.com/ shows hours and address only)","tier_absent_reason":"not-sold","blurb":"Described by the visitor bureau as Greater Zion''s largest craft brewery, with a 2026 World Beer Cup gold for its Ay Dios Mio! habanero chile beer; taproom kitchen at 4391 S Enterprise Drive, daily 11:30 am-9 pm."},{"name":"Zion Brewery Station II, downtown St. George","source":"https://greaterzion.com/brews-with-a-view-the-greater-zion-craft-beer-crawl/","accessed":"2026-10-02","si":["culinary","group","culture"],"booking_route":"not observed (operator site https://zionbrewery.com/ lists hours only)","tier_absent_reason":"not-sold","blurb":"Zion Brewery''s second bar at 142 N Main St, in a restored 1918 firehouse per the visitor bureau, with taproom, lounge, patio and billiards."},{"name":"Xetava Gardens Cafe & Bar, Ivins","source":"https://www.xetava.com/","accessed":"2026-10-02","si":["culinary","culture","romance"],"booking_route":"own ''Events & Reservations'' page; phone (435) 656-0165","tier_absent_reason":"not-sold","blurb":"Art-village garden cafe at 815 Coyote Gulch Ct, Ivins, serving house-made sangria and a prickly pear spritzer per the visitor bureau, with weekend brunch 10 am-3 pm."},{"name":"Swig, the birthplace of the dirty soda, St. George","source":"https://greaterzion.com/the-birthplace-of-the-dirty-soda/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"Per the Greater Zion visitor bureau, Nicole Tanner founded Swig in 2010 in a 700-square-foot shack in St. George, where the Dirty Dr Pepper (with coconut syrup and cream) started a national trend."},{"name":"Dutchman''s Market pink sugar cookie","source":"https://greaterzion.com/the-birthplace-of-the-dirty-soda/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Per the Greater Zion visitor bureau, Dutchman''s Market originated the pink frosted sugar cookie that became the dirty soda''s companion treat."},{"name":"Sego Restaurant, Kanab","source":"https://www.segokanab.com/","accessed":"2026-10-02","si":["culinary","romance","wine"],"booking_route":"online booking via own site; phone (435) 644-5680; reservations required for 7+","tier_absent_reason":"not-sold","blurb":"Chef Shon Foster''s regional New American social-plates restaurant in the Canyons Boutique Hotel, sourcing from Southwest farms and producers; OpenTable Diners'' Choice winner 2017-2025 per its site."},{"name":"Rocking V Cafe, Kanab","source":"https://www.rockingvcafe.com/","accessed":"2026-10-02","si":["culinary","culture","family"],"booking_route":"no reservations; online waitlist on own site","tier_absent_reason":"not-sold","blurb":"Eclectic American cafe with an art gallery at 97 West Center Street, known for a Smoked Gouda Bison Burger and vegan, vegetarian and gluten-free dishes."},{"name":"Thunderbird Restaurant ''Ho-Made Pies'', Mt. Carmel Junction","source":"https://www.thunderbirdutah.com/","accessed":"2026-10-02","si":["culinary","family","culture","senior"],"booking_route":"phone (435) 648-2262","tier_absent_reason":"not-sold","blurb":"Family-owned and operated since 1931 at the junction of State Route 9 and Highway 89, famous for its ''Ho-Made Pies'' and fresh-baked bread; daily 7 am-10 pm."}],"faq":[{"q":"Do I need a reservation to enter Zion National Park?","a":"No. The NPS states you do not need a permit or reservation to enter the park or ride the shuttles. Permits are required for specific activities such as Angels Landing past Scout Lookout and wilderness trips.","source":"https://www.nps.gov/zion/planyourvisit/zion-canyon-shuttle-system.htm","accessed":"2026-10-02"},{"q":"How do I get an Angels Landing permit?","a":"Through a seasonal lottery (four windows a year; for December 1 to February 28 it opens October 1 and closes October 20) or a day-before lottery open 12:01 am to 3 pm MT daily. The application is $6 for up to 6 people, plus $3 per person if selected.","source":"https://www.nps.gov/zion/planyourvisit/angels-landing-hiking-permits.htm","accessed":"2026-10-02"},{"q":"Can I drive my own car through Zion Canyon?","a":"Not while the shuttles run. Personal vehicles are prohibited on the Zion Canyon Scenic Drive during shuttle season; only Zion Lodge guests with reservations get access codes to drive to the lodge.","source":"https://www.nps.gov/zion/planyourvisit/zion-canyon-shuttle-system.htm","accessed":"2026-10-02"},{"q":"Do I need a permit to hike the Narrows?","a":"Not for the bottom-up hike from the Temple of Sinawava. The 16-mile top-down hike from Chamberlain''s Ranch needs a wilderness permit. The Narrows closes to all travel above 150 CFS and during flash flood warnings.","source":"https://www.nps.gov/zion/planyourvisit/thenarrows.htm","accessed":"2026-10-02"},{"q":"How much does it cost to enter Zion?","a":"$35 per private vehicle for 1-7 days, $20 per person on foot or bike (15 and under free), or $70 for a Zion Annual Pass. Non-US residents 16 and older pay an additional $100 from January 1, 2026.","source":"https://www.nps.gov/zion/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"When is the best time to visit Zion?","a":"The NPS describes fall as offering the same scenery at a slightly calmer pace, with visitation dropping more dramatically in November. Summer is the busiest season with temperatures regularly over 100°F.","source":"https://www.nps.gov/zion/planyourvisit/seasons.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Zion National Park: Angels Landing, the Narrows & Springdale | TravelWell","meta_description":"How the Zion shuttle works, when the Angels Landing lotteries open, what the Narrows needs, and where to stay from Zion Lodge to Under Canvas.","slug":"zion-national-park-utah","primary_keyword":"Zion National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Zion National Park, Utah"}}'::jsonb, 74),
  ('bryce-canyon-utah', '12A', 'Bryce Canyon National Park', 'United States', 'A hoodoo amphitheater at 8,000 feet, a Gold Tier dark sky, and the start of Scenic Byway 12', 'future', 'verified', 'mountainValley', 'Utah Canyon Country', '{"hiking","glamping","family","adventure","parks"}', '{"dramatic","rugged","alpine","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"The Bryce Amphitheater and its four main viewpoints","source":"https://www.nps.gov/brca/planyourvisit/index.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Bryce Point, Inspiration Point, Sunset Point and Sunrise Point, all within the first few miles of the park road"},{"name":"Queen''s Garden and Navajo Combination Loop","source":"https://www.nps.gov/brca/planyourvisit/qgnavajocombo.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"the park''s most popular hike: 2.9 miles, 2 to 3 hours, 625 feet of elevation, down from Sunrise Point and up to Sunset Point"},{"name":"Navajo Loop: Wall Street and Thor''s Hammer","source":"https://www.nps.gov/thingstodo/navajo-loop-trail.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"switchbacks between narrow limestone walls past the park''s most famous hoodoo; the Wall Street side closes in winter, Two Bridges stays open year-round"},{"name":"Southern Scenic Drive to Rainbow Point","source":"https://www.nps.gov/brca/planyourvisit/southern-scenic-drive-viewpoints.htm","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"18 miles from the entrance to Rainbow and Yovimpa Points at 9,115 feet, the park''s highest viewpoints, with nine overlooks on the way"},{"name":"Mossy Cave Trail","source":"https://www.nps.gov/thingstodo/mossy-cave-trail.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"on Highway 12 outside the fee booths: 0.8 miles roundtrip to a summer waterfall and winter icicles"},{"name":"Gold Tier International Dark Sky Park","source":"https://www.nps.gov/brca/learn/news/bryce-canyon-national-park-certified-as-an-international-dark-sky-park.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"certified 13 August 2019, as the park marked 50 years of astronomy programming"},{"name":"Ranger astronomy programmes","source":"https://www.nps.gov/brca/planyourvisit/astronomyprograms.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"about 100 programmes a year from astronomy rangers and volunteers; best during the week of the new moon or the week before"},{"name":"Bryce Canyon Astronomy Festival, 11 to 13 June 2026","source":"https://www.nps.gov/brca/planyourvisit/astrofest.htm","accessed":"2026-10-02","si":["group"],"tier_absent_reason":"not-sold","blurb":"free with park admission; an astrophotography workshop limited to 15 people a night opens on 10 June"},{"name":"Full moon hikes","source":"https://www.nps.gov/brca/planyourvisit/astronomyprograms.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"ranger-led on full moon nights, 1 to 2 miles over 2 to 3 hours, no flashlights allowed, limited tickets obtained in advance"},{"name":"Bryce Canyon Shuttle, 3 April to 18 October 2026","source":"https://www.nps.gov/brca/planyourvisit/shuttle.htm","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"free with park admission, about 15 stops through the amphitheater area, buses typically every 15 minutes"},{"name":"Canyon Trail Rides guided horse and mule rides","source":"https://www.nps.gov/brca/planyourvisit/horse.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"the park concessioner''s 2-hour and 3-hour rides into the amphitheater, typically April to 31 October, weather permitting"},{"name":"The Lodge at Bryce Canyon","source":"https://www.nps.gov/brca/planyourvisit/lodging.htm","accessed":"2026-10-02","si":["romance"],"tier_absent_reason":"not-sold","blurb":"the in-park historic lodge, 114 suites, motel rooms and cabins a short walk from the amphitheater; booked through visitbrycecanyon.com"},{"name":"Under Canvas Bryce Canyon","source":"https://www.undercanvas.com/camps/bryce-canyon/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"safari-style tents near Widtsoe about 15 minutes from the park, Stargazer tents with a sky window, ensuite baths and wood stoves; 2027 season 6 May to 27 September"},{"name":"Ruby''s Inn and the Bryce Canyon Winter Festival","source":"https://www.rubysinn.com/event/bryce-canyon-winter-festival/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"the Bryce Canyon City gateway just outside the park, host of the winter festival with ski and snowshoe tours, 14 to 16 February 2026"},{"name":"Scenic Byway 12 and Kodachrome Basin State Park","source":"https://www.visitutah.com/articles/the-all-american-road-scenic-byway-12","accessed":"2026-10-02","si":["expedition"],"tier_absent_reason":"not-sold","blurb":"Utah''s All-American Road, about 123 miles from US 89 near Panguitch to SR 24 near Torrey via Red Canyon and the Hogsback; Kodachrome Basin State Park is among the sites on the route"},{"name":"Clear Sky Resorts Bryce Canyon (Cannonville)","source":"https://brycecanyon.clearskyresorts.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"geodesic Sky Domes with floor-to-ceiling panoramic glass on a private 80-acre canyon at 855 UT-12, about 15 minutes from the park; units sleep 2 to 8, with the Sky Nova restaurant on site"},{"name":"Bryce Glamp and Camp (Cannonville)","source":"https://www.visitutah.com/things-to-do/camping/glamping-in-utah","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"glamping domes with private bathrooms, kitchenettes and year-round climate control, plus a disc golf course and stargazing pad"},{"name":"Wander Camp at Bryce Canyon","source":"https://thewandercamp.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"off-grid canvas bell tents over 200 sq ft with king or twin XL beds, shared bathrooms and communal fire pits, less than 15 minutes from the park; current season dates not established"},{"name":"Canyon Base Camp (Hatch)","source":"https://www.brycecanyoncountry.com/glamping/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"tipis, yurts and private cabins near Hatch, listed by the Garfield County tourism bureau"},{"name":"UYurt Adventure Rentals (Panguitch)","source":"https://www.uyurt.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"yurt glamping at 1680 S Rainbow Dr, Panguitch, some units riverside, operating since 2017"},{"name":"Escalante Yurts (Escalante)","source":"https://www.escalanteyurts.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"luxury yurts at 1605 N. Pine Creek Road with private bathrooms, climate control and breakfast; the operator puts Bryce Canyon about 1 hour away"},{"name":"Stone Canyon Inn tree houses (Tropic)","source":"https://www.stonecanyoninn.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"secluded cabins, bungalows and tree houses at 1380 West Stone Canyon Lane, Tropic, with views of the park"},{"name":"Ruby''s Inn Campground cabins and tipis (Bryce Canyon City)","source":"https://www.brycecanyoncampgrounds.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"log cabins and tipis at 300 South Main St, alongside more than 250 RV sites among the pines"},{"name":"Nettie''s Vintage Trailer Resort (Panguitch)","source":"https://www.nettiesresort.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"six restored vintage trailers from 1953 to 1974 at 340 E Center St, Panguitch"},{"name":"Bear Valley RV & Campground wagon cabins and tipis (Panguitch)","source":"https://www.bearvalleyrv.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"wagon cabins and teepee tents alongside RV sites at 900 E SR20, just outside Panguitch"},{"name":"Boulder Mountain Guest Ranch (Boulder)","source":"https://www.brycecanyoncountry.com/glamping/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"listed by the county for seasonal luxury yurt glamping on a secluded ranch on Byway 12; the ranch''s own homepage did not detail the yurts"},{"name":"BaseCamp 37 (Kanab)","source":"https://basecamp37.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"five safari-style tents 8 miles east of Kanab in the Chocolate Cliffs, self-catering, open all year; drive time to Bryce not stated by the operator"},{"name":"North and Sunset Campgrounds (in the park)","source":"https://www.nps.gov/brca/planyourvisit/campgrounds.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"$30 a site a night; North is open year-round and booked up to 6 months ahead, Sunset closes in winter and books up to 14 days ahead, both on Recreation.gov"},{"name":"Ruby''s Inn RV Park & Campground (Bryce Canyon City)","source":"https://www.brycecanyoncountry.com/rv-parks-campgrounds/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"more than 250 sites among the pines, the county calls it the closest RV park to the park"},{"name":"Bryce Canyon Pines (Highway 12)","source":"https://www.bcpines.com/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"10 minutes from the main entrance: lodge rooms, cottages, 30 RV hookup sites and 18 campsites, and a restaurant known for homemade pies"},{"name":"Bryce Canyon RV Resort by Rjourney (Cannonville)","source":"https://rjourney.com/explore/best-rv-parks-near-bryce-canyon-ut/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"215 Red Rock Drive, about 12 miles east of the park entrance on Byway 12: full-hookup and pull-through RV sites, tent sites and cabins; rates from $36.50"},{"name":"Tropic RV parks: Bryce Village RV Park and Bryce Pioneer Village","source":"https://www.brycecanyoncountry.com/rv-parks-campgrounds/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Bryce Village has a heated pool; Pioneer Village offers cabins and campsites; both in Tropic"},{"name":"Bryce Valley Ranch RV & Horse Park (Cannonville)","source":"https://www.brycecanyoncountry.com/rv-parks-campgrounds/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"camping, cabins and a base camp for travellers with horses"},{"name":"National forest campgrounds: Kings Creek and Red Canyon","source":"https://www.brycecanyoncountry.com/rv-parks-campgrounds/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"Kings Creek sits at 8,000 feet near Bryce Canyon City and is booked on Recreation.gov; Red Canyon Campground is in ponderosa pine on the Panguitch side"},{"name":"Kodachrome Basin State Park Campground","source":"https://www.brycecanyoncountry.com/rv-parks-campgrounds/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"state park campground with cottages and bunkhouses for rent, booked through Utah State Parks"},{"name":"Panguitch and Red Canyon RV parks","source":"https://www.brycecanyoncountry.com/rv-parks-campgrounds/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Henrie''s Hitch-N-Post (70 sites, big-rig friendly), Dixie Forest RV Resort by Rjourney, Paradise RV Park, Bryce Canyon Shadows and Red Canyon Village RV Park"},{"name":"Ruby''s Inn guided ATV tours","source":"https://www.rubysinn.com/activities-in-bryce-canyon/guided-atv-tours/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"one-hour guided rides through ponderosa forest to the park rim, 1 April to 18 October, from $100 (ATV) to $195 (Ranger Crew); 435-834-5231"},{"name":"Ruby''s Inn horseback, bike rental and Ebenezer''s Barn & Grill","source":"https://www.rubysinn.com/activities-in-bryce-canyon/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"guided horseback tours from age 10, mountain bike rentals, and Western dining with a live country music show"},{"name":"Bryce Canyon Stargazing (Bryce Canyon City)","source":"https://brycecanyonstargazing.com/stargazing-tours/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"90-minute telescope tours from 175 S Highway 63, year-round; Classic tour $55 adults, plus late-night tours, full moonwalks and astrophotography"},{"name":"Dark Ranger Telescope Tours","source":"https://www.darkrangertelescopetours.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"a 2.5-hour summer public telescope tour with hands-on operation of large telescopes and a laser constellation tour; reservations required"},{"name":"Hell''s Backbone Grill & Farm (Boulder, Byway 12)","source":"https://hellsbackbonegrill.com/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"farm-to-table restaurant and lodge; 2026 dinner service Thursday to Monday 4 to 9 pm, and a Saturday community market May to October"},{"name":"Stone Hearth Grille, Tropic","source":"https://www.stonehearthgrille.com/","accessed":"2026-10-02","si":["culinary","romance","wine"],"booking_route":"own online reservation request form; phone 435-679-8923; walk-ins possible off-peak","tier_absent_reason":"not-sold","blurb":"Upscale steakhouse in a post-and-beam room with a stone fireplace and sunset views over pink cliffs, serving hormone-free beef with an extensive wine list; 2026 season 23 March to 29 October."},{"name":"Cowboy''s Buffet & Steak Room at Ruby''s Inn, Bryce Canyon City","source":"https://www.rubysinn.com/restaurant-in-bryce-canyon/cowboys-buffet-steak-room/","accessed":"2026-10-02","si":["culinary","family","group","senior"],"booking_route":"walk-in, no reservations needed","tier_absent_reason":"not-sold","blurb":"Western-style restaurant ''serving the area since 1916'' inside Best Western Ruby''s Inn, with an a la carte menu and a seasonal buffet of steak, ribs, seafood and chicken; open year-round."},{"name":"Showdowns Restaurant, Tropic","source":"https://www.showdownsrestaurant.com/","accessed":"2026-10-02","si":["culinary","family","group"],"booking_route":"walk-in only (''We do not accept reservations!'')","tier_absent_reason":"not-sold","blurb":"Home-style cooking at 80 South Main Street with beer, wine, mixed drinks and s''mores on the menu; open daily 5-9:30 pm, March to October."},{"name":"Bryce Canyon Coffee Co., Tropic","source":"https://www.brycecanyoncoffeeco.com/","accessed":"2026-10-02","si":["culinary","hiking","family"],"booking_route":"walk-in","tier_absent_reason":"not-sold","blurb":"Locally roasted coffee since 2013 at 21 N Main Street, with Mr. B''s homemade banana bread made exclusively for the shop."},{"name":"Henrie''s Drive-In, Panguitch","source":"https://www.henriesdrivein.com/","accessed":"2026-10-02","si":["culinary","family","culture"],"booking_route":"walk-in / drive-thru","tier_absent_reason":"not-sold","blurb":"Family-owned drive-in since 1957 at 166 N. Main, using ''Grandma''s recipes'' for burgers, hand-dipped onion rings and shakes; famous for the ''Chubby Cheese''."},{"name":"Cowboy Smokehouse, Panguitch","source":"https://www.brycecanyoncountry.com/dining/cowboy-smokehouse-in-panguitch/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Smokehouse in Panguitch, per the Bryce Canyon Country (Garfield County) visitor bureau listing; no operator details were confirmed."},{"name":"Kiva Koffeehouse, Escalante","source":"https://www.kivakoffeehouse.com/","accessed":"2026-10-02","si":["culinary","romance","hiking"],"booking_route":"walk-in; phone (435) 826-4550","tier_absent_reason":"not-sold","blurb":"Seasonal Escalante coffeehouse operating since 1998, serving coffee and food Wednesday to Sunday 8 am-4 pm (kitchen closes 3 pm), with the Kiva Kottage rental alongside."},{"name":"Escalante Outfitters pizza and beer, Escalante","source":"https://www.escalanteoutfitters.com/","accessed":"2026-10-02","si":["culinary","hiking","adventure","group"],"booking_route":"walk-in; phone (435) 215-7953","tier_absent_reason":"not-sold","blurb":"Family-run outfitter at 310 West Main Street serving pizza and beer daily 11 am-9 pm for the 2026 season, beside its cabins and gear shop, pitched as the meal after exploring Grand Staircase-Escalante."},{"name":"Burr Trail Grill & Tumbleweed Coffee, Boulder","source":"https://www.burrtrailgrill.com/","accessed":"2026-10-02","si":["culinary","adventure","hiking"],"booking_route":"phone (435) 335-7511; own contact page","tier_absent_reason":"not-sold","blurb":"Grill and coffee shop at 10 N Hwy 12 in Boulder on Scenic Byway 12."}],"faq":[{"q":"Do you need a reservation to enter Bryce Canyon National Park?","a":"No. The NPS says you don''t need a reservation to enter the park. Campsites are different: there are no first-come, first-served sites, and reservations must be made on recreation.gov.","source":"https://www.nps.gov/brca/planyourvisit/faqs.htm","accessed":"2026-10-02"},{"q":"How much does it cost to visit Bryce Canyon?","a":"$35 per private vehicle, $30 per motorcycle, or $20 per person on foot or bicycle. Non-US residents aged 16 and over pay an additional $100 nonresident fee unless admitted with an annual or America the Beautiful pass. The park does not accept cash.","source":"https://www.nps.gov/brca/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"When does the Bryce Canyon shuttle run?","a":"In 2026, from 3 April to 18 October. It is free with park admission, serves about 15 stops through the amphitheater area, and buses typically arrive every 15 minutes.","source":"https://www.nps.gov/brca/planyourvisit/shuttle.htm","accessed":"2026-10-02"},{"q":"What is the best hike at Bryce Canyon for a first visit?","a":"The NPS names the Queen''s Garden and Navajo Combination Loop as the most popular hike and recommends it for first-time visitors: 2.9 miles, 2 to 3 hours, 625 feet of elevation gain, rated moderate.","source":"https://www.nps.gov/brca/planyourvisit/qgnavajocombo.htm","accessed":"2026-10-02"},{"q":"When is the Bryce Canyon Astronomy Festival?","a":"11 to 13 June 2026, with an astrophotography workshop starting the evening of 10 June. Attending is free with park admission; some events require advance sign-up.","source":"https://www.nps.gov/brca/planyourvisit/astrofest.htm","accessed":"2026-10-02"},{"q":"Is Bryce Canyon open in winter?","a":"Yes. The park is open 24 hours a day all year. North Campground stays open, Sunset Campground closes from November into April, and the Lodge closes in winter though lodging often remains available at the Sunset Lodge Unit.","source":"https://www.nps.gov/brca/planyourvisit/faqs.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Bryce Canyon National Park: Hoodoos, Dark Skies & Byway 12 | TravelWell","meta_description":"The amphitheater hikes, the 2026 shuttle and astronomy festival dates, entrance fees, and the stays and byway around Bryce Canyon.","slug":"bryce-canyon-national-park-utah","primary_keyword":"Bryce Canyon National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Bryce Canyon National Park, Utah"}}'::jsonb, 75),
  ('arches-utah', '12A', 'Arches National Park', 'United States', 'A red-rock park five miles north of Moab, with Delicate Arch, the longest natural span in the world and a certified dark sky, and no timed-entry reservation in 2026', 'future', 'verified', 'mountainValley', 'Utah Canyon Country', '{"hiking","adventure","glamping","family","parks"}', '{"dramatic","rugged","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Delicate Arch Trail","source":"https://www.nps.gov/arch/planyourvisit/delicate-arch.htm","accessed":"2026-10-02","si":["hiking","romance","adventure"],"booking_route":"none needed - no timed-entry reservation in 2026","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"3 miles (4.8 km) roundtrip and climbs 480 feet (146m)\", \"steadily uphill\" past the Wolfe Ranch cabin and Ute petroglyphs; NPS: \"Rangers frequently rescue people who underestimated the trail''s difficulty\"; sunset can draw hundreds"},{"name":"The Windows and Turret Arch","source":"https://www.nps.gov/arch/planyourvisit/the-windows.htm","accessed":"2026-10-02","si":["hiking","family","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the first 100 yards of the Windows trail are flat, hard packed and \"barrier free\", then stone steps and elevation gain; the Windows Section is also an NPS-named stargazing spot"},{"name":"Double Arch","source":"https://www.nps.gov/arch/planyourvisit/the-windows.htm","accessed":"2026-10-02","si":["family","senior","hiking"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a \"barrier free\" hard-packed trail with some slopes and sand at the end; the Moab Office of Tourism notes it was used in filming Indiana Jones and the Last Crusade"},{"name":"Landscape Arch, Devils Garden","source":"https://www.nps.gov/arch/planyourvisit/devils-garden.htm","accessed":"2026-10-02","si":["hiking","family","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"1.9 miles (3.1 km roundtrip)\", \"relatively flat with hard packed surfaces\"; the Moab Office of Tourism calls it \"The longest natural rock span in the world\" at \"306 feet wide\""},{"name":"Double O Arch and the Primitive Trail","source":"https://www.nps.gov/arch/planyourvisit/devils-garden.htm","accessed":"2026-10-02","si":["adventure","hiking"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"Double O is \"4.1 miles (6.6 km roundtrip)\" and \"steeply climbs up and on the sandstone fins\"; the 2.1-mile one-way Primitive Trail is \"the most difficult segment of the Devils Garden trail system\" and \"not recommended when rock is wet or icy, or for those uncomfortable with heights\""},{"name":"Fiery Furnace, ranger-led hike","source":"https://www.nps.gov/arch/planyourvisit/programs.htm","accessed":"2026-10-02","si":["adventure","hiking","family"],"booking_route":"Recreation.gov","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Physically demanding hikes, for ages 5 and up only. You must purchase tickets in advance\"; season \"April 12 through early Fall\"; $16 per person"},{"name":"Fiery Furnace, self-guided permit","source":"https://www.nps.gov/arch/planyourvisit/fees.htm","accessed":"2026-10-02","si":["adventure","hiking","expedition"],"booking_route":"reservation required per NPS; engine for the self-guided permit not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"enter the Fiery Furnace on your own with a permit. We offer limited numbers of permits each day\"; $10 per person; children under 5 not permitted; reservations required in 2026"},{"name":"Entering Arches in 2026","source":"https://www.nps.gov/arch/planyourvisit/index.htm","accessed":"2026-10-02","si":["family","senior"],"booking_route":"entrance pass at the gate or online (fees page); no reservation","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"no timed-entry reservation in 2026; private vehicle $30, motorcycle $25, per person $15; vehicles \"may be diverted from park entrances when areas become too congested\""},{"name":"Night skies, International Dark Sky Park","source":"https://www.nps.gov/arch/planyourvisit/stargazing.htm","accessed":"2026-10-02","si":["romance","wellness","family"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"certified in 2019; the NPS names Balanced Rock Picnic Area, the Windows Section, Garden of Eden Viewpoint and Panorama Point, and says \"common binoculars may even reveal the rings of Saturn\""},{"name":"Evening programmes and patio talks","source":"https://www.nps.gov/arch/planyourvisit/programs.htm","accessed":"2026-10-02","si":["family","culture","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"free 30-45 minute evening programmes at the Devils Garden Campground amphitheatre \"nightly starting May 31\", and free ten-minute patio talks at the visitor centre with no reservation"},{"name":"Arches Visitor Center","source":"https://www.nps.gov/arch/planyourvisit/visitorcenters.htm","accessed":"2026-10-02","si":["family","senior"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"located just inside the park entrance, five miles north of Moab, Utah\"; tactile models, audio recordings and braille publications; 435-719-2299"},{"name":"Balanced Rock","source":"https://www.discovermoab.com/places-to-go/national-parks/arches-national-park/","accessed":"2026-10-02","si":["family","senior","romance"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"per the Moab Office of Tourism, \"total height is 128 feet, with the huge balanced rock rising 55 feet\"; its picnic area is an NPS-named stargazing spot"},{"name":"Devils Garden Campground","source":"https://www.nps.gov/arch/planyourvisit/camping.htm","accessed":"2026-10-02","si":["family","hiking","adventure"],"booking_route":"Recreation.gov","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the park''s only campground; reservable for nights March 1 to October 31, first-come, first-served in November and February; $25 a night for 1-10 campers; \"typically fills nightly during summer months\""},{"name":"Under Canvas Moab","source":"https://www.undercanvas.com/camps/moab/","accessed":"2026-10-02","si":["glamping","romance","family","group"],"booking_route":"own site online booking (engine not named) and Adventure Concierge","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"safari-style tents \"just seven miles north of Moab\" - Deluxe, Stargazer with viewing window, Suite, Safari and kids''-tent configurations; 2026 season March 5 to November 1; one of the world''s first DarkSky-certified resorts; pet-friendly, EV charging, no on-site cafe"},{"name":"HTR Moab Lodge & Cottages","source":"http://www.htrresorts.com/destinations/moab/","accessed":"2026-10-02","si":["glamping","family","group"],"booking_route":"own booking engine (book.htrresorts.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"luxury deluxe vacation rental cottages, safari tents, rustic lodge rooms, lodge residences, and primitive tent sites\" at 1536 S Mill Creek Drive, Moab (the former ACT Campground domain redirects here)"},{"name":"Moab RV and Glamping Resort","source":"https://www.hipcamp.com/en-US/land/utah-moab-rv-and-glamping-resort-06yh86ro","accessed":"2026-10-02","si":["glamping","family"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"10 acres with 43 full-hookup RV sites up to 65 feet, basic and deluxe cabins, glamping tents and tipis; listed as big-rig and family friendly"},{"name":"Dead Horse Point State Park yurts and campgrounds","source":"https://stateparks.utah.gov/parks/dead-horse/","accessed":"2026-10-02","si":["glamping","romance","hiking","family"],"booking_route":"ReserveAmerica (utahstateparks.reserveamerica.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"Wingate Yurts (no pets) and Moenkopi Yurts (pet-friendly) plus RV and tent sites in \"a designated International Dark Sky Park\"; campers keep night-sky access after day-use closes at 10 p.m."},{"name":"High Sage Hogans, La Sal","source":"https://www.hipcamp.com/en-US/land/utah-high-sage-hogans-mxvhrlvd","accessed":"2026-10-02","si":["glamping","romance"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"two tipis (a 16-foot for 4-5 and a 14-foot for couples) and two tent/RV sites at 7,000 feet with views of the La Sal Mountains; outdoor potty, free firewood, farm animals"},{"name":"Glamping Canyonlands, Monticello","source":"https://www.hipcamp.com/en-US/land/utah-glamping-canyonlands-lz9hn5oj","accessed":"2026-10-02","si":["glamping","romance","wellness"],"booking_route":"Hipcamp","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an off-grid, solar-powered 22-acre site with bell and safari tents, a stargazing lotus tent, cedar pod, moon barrel and casita, communal kitchen, pizza oven and sauna; named a best dark-sky Hipcamp in the US (2025); at the outer edge of the one-hour ring"},{"name":"Red Cliffs Lodge","source":"https://redcliffslodge.com/moab/","accessed":"2026-10-02","si":["romance","family","group"],"booking_route":"Marriott reservation system","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Marriott Tribute Portfolio lodge \"On the banks of the Colorado River\" at Mile Post 14 UT-128, with cabins and suites, Ember Restaurant & Lounge and on-site horseback riding"},{"name":"Sorrel River Ranch Resort & Spa","source":"https://www.sorrelriver.com/","accessed":"2026-10-02","si":["romance","wellness","ultra","culinary"],"booking_route":"not observed (stay@sorrelriver.com, 435.259.4642)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a 240-acre luxury ranch resort on the Colorado River at Mile 17, UT-128, with custom cabins, a spa, yoga programmes, horseback riding, an on-site farm and garden, and the River Grill"},{"name":"Moab Springs Ranch","source":"https://www.moabspringsranch.com/","accessed":"2026-10-02","si":["family","group","romance"],"booking_route":"own booking engine (secure.irm1.net)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"studio bungalows with kitchenette and patio, and townhouses with full kitchen and washer/dryer, at 1266 US Highway 191"},{"name":"Moab Adventure Center","source":"https://www.moabadventurecenter.com/","accessed":"2026-10-02","si":["adventure","family","group"],"booking_route":"own site cart and check-availability (engine not named)","commission_status":"commissioned","tier_absent_reason":"not-sold","blurb":"Colorado River day trips through Castle Valley with riverside BBQ, Hummer safaris, guided Arches tours, canyoneering, hot air balloons, horseback, bikes and jeep rentals at 225 S Main St; \"Best of State since 2004\""},{"name":"Navtec Expeditions","source":"https://www.navtec.com/","accessed":"2026-10-02","si":["adventure","expedition","family"],"booking_route":"own site (navtec.com/expeditions)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"an authorized concessioner of Canyonlands and Arches National Park\": Colorado River rafting including Cataract and Westwater canyons, 4x4, canyoneering and hiking; 1-800-833-1278"},{"name":"Adrift Adventures","source":"https://www.adrift.net/","accessed":"2026-10-02","si":["adventure","expedition","family","group"],"booking_route":"own site (adrift.net); 435-259-8594","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Since 1978\", an NPS authorized concessioner at 378 North Main Street: Cataract, Westwater and Fisher Towers rafting, kayak and SUP, and 4x4 jeep tours through Arches and Canyonlands; river trips March-October, land tours year-round"},{"name":"Sheri Griffith Expeditions","source":"https://www.griffithexp.com/","accessed":"2026-10-02","si":["expedition","adventure","family","ultra"],"booking_route":"Flybook (go.theflybook.com); 435-259-8229","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Adventure with a Touch of Class\" river trips on the Colorado (Westwater) and Green (Cataract, Desolation), Yampa and Gates of Lodore, with luxury, family and women-only formats; 2231 S Hwy 191"},{"name":"Canyonlands by Night & Day","source":"https://www.canyonlandsbynight.com/","accessed":"2026-10-02","si":["family","romance","senior","group"],"booking_route":"FareHarbor","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a family company since 1963 running the Sound & Light Show Jet Boat, a Sunset Jet Boat with Dinner and the unWine''d & Dine cruise on the Colorado"},{"name":"Desert Highlights","source":"https://www.deserthighlights.com/","accessed":"2026-10-02","si":["adventure","expedition","group"],"booking_route":"own site; 435-259-4433","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"private guided canyoneering since 1997 - Granary Canyon, Irish Canyons, Medieval Chamber, Zig Zag Canyon - plus climbing, packrafting and hiking, with WFR and AMGA-credentialed guides"},{"name":"High Point Hummer","source":"https://www.highpointhummer.com/","accessed":"2026-10-02","si":["adventure","family","group"],"booking_route":"FareHarbor","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"Hummer tours from $89, U-Drive UTV from $99 and Can-Am X3 tours $159-$249 on Hell''s Revenge and Fins N'' Things; \"Established 1999\" at 301 S. Main"},{"name":"Moab Tour Company","source":"https://www.moabtourcompany.com/","accessed":"2026-10-02","si":["adventure","group"],"booking_route":"own site; 435-259-4080","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"UTV, jeep and dirt bike tours on Hell''s Revenge, Fins & Things and Poison Spider Mesa from $55-$299 per person, locally owned for 23 years at 427 N Main St"},{"name":"Moab Cyclery","source":"https://www.moabcyclery.com/","accessed":"2026-10-02","si":["sports","adventure"],"booking_route":"own site online reservations (engine not named); 435-259-7423","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"mountain and e-bike rentals and shuttles to the Whole Enchilada, Porcupine Rim, Mag 7 and Slickrock at 391 S. Main St; notes a BLM change opening 211 miles of Moab singletrack to Class 1 e-bikes from March 1, 2026"},{"name":"Poison Spider Bicycles and Whole Enchilada Shuttles","source":"https://www.poisonspiderbicycles.com/","accessed":"2026-10-02","si":["sports","adventure"],"booking_route":"Peek (shuttles, also wholeenchiladashuttles.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"the largest selection of rental bikes in Moab\" at 497 N. Main St, with shuttles to the Whole Enchilada, UPS, LPS, Bar M and Mag 7"},{"name":"Rim Tours","source":"https://www.rimtours.com/","accessed":"2026-10-02","si":["expedition","sports","adventure"],"booking_route":"own site enquiry; 435-259-5223","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Guiding Moab since 1985\": half-day rides to the 4-day White Rim and 5-day Kokopelli Trail, small groups of \"max 8-12 riders\" with camping, meals and permits handled"},{"name":"Skydive Moab","source":"https://www.skydivemoab.com/","accessed":"2026-10-02","si":["adventure","sports"],"booking_route":"Dizio (moab.reservations.dizio.app); walk-ins when jumping","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"tandem skydives from 13,000 feet, sunset tandems and AFF training at Canyonlands Field Airport, 114 W Aviation Way"},{"name":"Canyonlands Field Institute","source":"https://www.cfimoab.org/","accessed":"2026-10-02","si":["culture","family","wellness"],"booking_route":"own site; 435-259-7750","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Moab nonprofit since 1984 running school programmes, summer camps and adult adventures at 1320 South Hwy 191"},{"name":"Moab Brewery","source":"https://www.themoabbrewery.com/","accessed":"2026-10-02","si":["culinary","group","family"],"booking_route":"Toast (online ordering); phone (435) 259-6333","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"brewery, distillery and restaurant since 1996 at 686 S. Main St, scratch cooking with the flavours of its own beer and spirits; open daily at 11 am"},{"name":"Desert Bistro","source":"https://www.desertbistro.com/","accessed":"2026-10-02","si":["culinary","romance","wine"],"booking_route":"Tock (exploretock.com/desert-bistro)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Internationally inspired fine cuisine with a southwestern flair\" in a historic downtown building at 36 S 100 W; nightly from 5 pm"},{"name":"98 Center","source":"https://www.98center.com/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"TBDine (online ordering)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"Vietnamese-inspired and contemporary American dishes from \"fresh, organic, locally sourced ingredients\" at 98 East Center Street, with live local music and cocktails; Wednesday-Sunday"},{"name":"Sabaku Sushi","source":"https://www.sabakusushi.com/visit","accessed":"2026-10-02","si":["culinary","romance"],"booking_route":"TBDine reservations; walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a desert sushi bar at 90 E. Center Street, Tuesday-Saturday 5-9 pm; half the tables by reservation, half held for walk-ins"},{"name":"River Grill at Sorrel River Ranch","source":"https://www.sorrelriver.com/","accessed":"2026-10-02","si":["culinary","romance","wine"],"booking_route":"not observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"meals \"set along the banks\" of the Colorado with red-rock views, drawing on the ranch''s on-site farm and garden"},{"name":"Moab Music Festival","source":"https://www.moabmusicfest.org/","accessed":"2026-10-02","si":["culture","romance","senior"],"booking_route":"own site ticketing (engine not named); (435) 259-7003","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"chamber music, jazz and Latin concerts in wilderness venues including grottos reached by jet boat; Holiday Concert December 12, 2026, Winterlude February 20-27, 2027, 35th festival September 1-17, 2027"},{"name":"Moab Museum","source":"https://www.moabmuseum.org/","accessed":"2026-10-02","si":["culture","family","senior"],"booking_route":"not observed; 435-259-7985","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"cultural and natural history of the region - First People, ranching, uranium and migration - at 118 East Center Street, Tuesday-Saturday 9-5"},{"name":"Moab Giants","source":"https://www.moabgiants.com/","accessed":"2026-10-02","si":["family"],"booking_route":"own site tickets (moabgiants.com/tickets)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"over 100 life-sized dinosaurs, a 3D theatre, VR and a prehistoric aquarium at Hwy 191 and SR 313; closed Wednesdays"},{"name":"Corona Arch Trail (BLM)","source":"https://www.blm.gov/visit/corona-arch-trail","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a National Recreation Trail since 2018, \"a moderately strenuous 3 mile round trip hike to the spectacular Corona Arch\" off UT-279"},{"name":"Island in the Sky, Canyonlands National Park (cross-link)","source":"https://www.nps.gov/cany/planyourvisit/islandinthesky.htm","accessed":"2026-10-02","si":["hiking","adventure","expedition"],"booking_route":"not researched in this file","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"The Island in the Sky mesa rests on sheer sandstone cliffs over 1,000 feet (304 m) above the surrounding terrain\" - the nearest district of Canyonlands; full treatment in the Canyonlands dossier"}],"faq":[{"q":"Do I need a timed-entry reservation for Arches in 2026?","a":"No. The NPS states that in 2026 advanced timed-entry reservations will not be required and visitors may enter at any time during operating hours. Vehicles may be diverted when areas become too congested, and reservations are still required for Devils Garden Campground and for self-guided and ranger-led Fiery Furnace hikes.","source":"https://www.nps.gov/arch/planyourvisit/index.htm","accessed":"2026-10-02"},{"q":"How do I get into the Fiery Furnace?","a":"Two ways, both reserved in advance: a ranger-led hike ($16 per person, April 12 through early fall, tickets on Recreation.gov) or a self-guided permit ($10 per person, limited numbers each day). Children under 5 are not permitted.","source":"https://www.nps.gov/arch/planyourvisit/programs.htm","accessed":"2026-10-02"},{"q":"Can I camp inside Arches?","a":"Yes, at Devils Garden Campground. Sites are reservable for nights between March 1 and October 31 and are first-come, first-served in November and February; $25 a night for 1-10 campers. The NPS says that without a reservation you will probably have to look outside the park.","source":"https://www.nps.gov/arch/planyourvisit/camping.htm","accessed":"2026-10-02"},{"q":"How long is the Delicate Arch hike?","a":"The NPS gives 3 miles (4.8 km) round trip with a 480-foot (146 m) climb, steadily uphill, and advises considering summer heat or winter ice and your own fitness before starting.","source":"https://www.nps.gov/arch/planyourvisit/delicate-arch.htm","accessed":"2026-10-02"},{"q":"When is Arches least crowded?","a":"The NPS says peak congestion runs spring through fall from 8 am to 3 pm, that late afternoon and evening offer sunsets and reduced crowding, and that in summer many trailhead lots fill by 7:30 am.","source":"https://www.nps.gov/arch/planyourvisit/traffic.htm","accessed":"2026-10-02"},{"q":"Is Arches a dark sky park?","a":"Yes. The NPS states Arches was certified as an International Dark Sky Park in 2019, and names Balanced Rock Picnic Area, the Windows Section, Garden of Eden Viewpoint and Panorama Point for stargazing.","source":"https://www.nps.gov/arch/planyourvisit/stargazing.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Arches National Park: Delicate Arch, Fiery Furnace & Moab Glamping | TravelWell","meta_description":"No timed entry in 2026: Delicate Arch, Devils Garden, Fiery Furnace permits, dark skies, and Moab''s glamping, river outfitters and restaurants, sourced.","slug":"arches-national-park-utah","primary_keyword":"Arches National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Arches National Park, Utah"}}'::jsonb, 76)
