insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('capitol-reef-utah', '12A', 'Capitol Reef National Park', 'United States', 'A red-rock park on the Waterpocket Fold with pioneer orchards you can pick, pies at the Gifford House, and some of the darkest skies in the West', 'future', 'verified', 'mountainValley', 'Utah Canyon Country', '{"hiking","adventure","culinary","glamping","parks"}', '{"dramatic","remote","historic"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Fruita orchards u-pick","source":"https://www.nps.gov/care/learn/historyculture/orchards.htm","accessed":"2026-10-02","si":["culinary","family","senior","culture"],"booking_route":"walk-in (self-pay station in the orchard)","commission_status":"none","tier_absent_reason":"not-sold","blurb":"historic orchards in the Fruita district (\"about 2,000 trees\" on the Fruita page, \"approximately 1,900\" on the orchards page); pick only where \"U-Pick Fruit\" signs are posted, pay at the self-pay station and scale; apples mid-August to mid-October, peaches late July to early September; hotline (435) 425-3791"},{"name":"Gifford Homestead store and museum","source":"https://www.nps.gov/care/learn/historyculture/giffordhomestead.htm","accessed":"2026-10-02","si":["culinary","culture","family","senior"],"booking_route":"walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the Capitol Reef Natural History Association''s store 1 mile south of the visitor center on the Scenic Drive, selling \"locally baked fruit pies and homemade ice cream\", jams and pioneer crafts; open March 14 (Pi Day) to late November, daily 9 am to 4:30 pm"},{"name":"Scenic Drive","source":"https://www.nps.gov/care/planyourvisit/scenicdrive.htm","accessed":"2026-10-02","si":["senior","family","romance"],"booking_route":"none needed - $20 vehicle entrance fee","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"a 7.9 mile (12.7 km) paved road, suitable for passenger vehicles\", about an hour and a half round trip with the Grand Wash and Capitol Gorge spurs; NPS: \"Avoid canyons and washes when storms threaten\""},{"name":"Capitol Gorge and the Pioneer Register","source":"https://www.nps.gov/care/planyourvisit/trailguide.htm","accessed":"2026-10-02","si":["hiking","culture","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 1.0-mile easy walk through a \"Deep canyon, historic inscriptions, short climb to waterpockets (''tanks'')\"; the Capitol Gorge road is listed Closed on the NPS road table updated 9/30/2026"},{"name":"Hickman Bridge","source":"https://www.nps.gov/care/planyourvisit/trailguide.htm","accessed":"2026-10-02","si":["hiking","family"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"0.9 mile one way, 400 ft of climb, rated moderate, to a \"133-foot natural bridge, canyon views\""},{"name":"Cassidy Arch and Grand Wash","source":"https://www.nps.gov/care/planyourvisit/trailguide.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"Cassidy Arch is 1.7 miles and 670 ft, rated strenuous (\"Deep canyon, natural arch, slickrock\"); Grand Wash is 2.2 miles and easy through \"Deep canyon, narrows\"; Grand Wash road listed 2WD on 9/30/2026"},{"name":"Cohab Canyon and Navajo Knobs","source":"https://www.nps.gov/care/planyourvisit/trailguide.htm","accessed":"2026-10-02","si":["hiking","adventure"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"Cohab Canyon, 1.7 miles and 440 ft, gives \"views of Fruita\"; Navajo Knobs, 4.7 miles and 1,620 ft, strenuous, ends on a \"360-degree mountaintop panorama\""},{"name":"Cathedral Valley loop","source":"https://www.nps.gov/care/planyourvisit/cathedralvalley.htm","accessed":"2026-10-02","si":["adventure","expedition"],"booking_route":"none needed (self-drive, high clearance); guided via Torrey outfitters","commission_status":"none","tier_absent_reason":"not-sold","blurb":"a 57.6-mile loop that \"takes about 6-8 hours\", with a Fremont River ford and the Temples of the Sun and Moon, Glass Mountain and the Gypsum Sinkhole; NPS: bentonite \"becomes very slick and gummy when wet\"; Hartnet Road \"Likely impassable\" on 9/30/2026"},{"name":"Burr Trail switchbacks","source":"https://www.nps.gov/care/planyourvisit/roads.htm","accessed":"2026-10-02","si":["adventure","expedition"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"8.5 miles of the Burr Trail inside the park, with \"a breathtaking set of switchbacks rising some 800 feet (244 m) in only one-half mile\"; paved from Boulder on Highway 12 to the park''s west boundary"},{"name":"International Dark Sky Park","source":"https://www.nps.gov/care/learn/nature/night-sky.htm","accessed":"2026-10-02","si":["romance","family","wellness"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"Designated an International Dark Sky Park in 2015\", with \"some of the best night sky viewing opportunities of the western national parks\""},{"name":"Heritage StarFest","source":"https://www.nps.gov/care/planyourvisit/heritage-starfest.htm","accessed":"2026-10-02","si":["culture","family","group"],"booking_route":"free; Entrada Institute events calendar for Saturday seats","commission_status":"none","tier_absent_reason":"not-sold","blurb":"the park''s annual night-sky festival with the Entrada Institute; 2026 edition ran September 9-12 in the park and Torrey, with star parties, solar telescopes and a free 3hattrio concert; Saturday events at the Entrada Institute require registration"},{"name":"Ranger and astronomy programmes","source":"https://www.nps.gov/care/planyourvisit/ranger-programs.htm","accessed":"2026-10-02","si":["family","culture","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"mid-May to mid-October: daily archeology and Ranger''s Choice talks, evening programmes at the Fruita Campground amphitheater, astronomy programmes several nights a week; Junior Ranger book in 14 languages"},{"name":"Fremont petroglyphs and the Fruita Schoolhouse","source":"https://www.nps.gov/care/planyourvisit/fruita.htm","accessed":"2026-10-02","si":["culture","family","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"Fremont Culture petroglyphs from \"about 1000 years ago\" reached by a Highway 24 boardwalk, and Fruita''s one-room schoolhouse, both in the historic district"},{"name":"Canyoneering and climbing by permit","source":"https://www.nps.gov/care/planyourvisit/outdooractivities.htm","accessed":"2026-10-02","si":["adventure","sports"],"booking_route":"NPS permit (free)","commission_status":"none","tier_absent_reason":"not-sold","blurb":"\"The multiple rock layers found at Capitol Reef offer a diverse canyon environment. Permits are now required\"; climbing and bouldering permits too, all listed free on the fees page"},{"name":"Fruita Campground","source":"https://www.nps.gov/care/planyourvisit/fruitacampground.htm","accessed":"2026-10-02","si":["family","hiking","senior"],"booking_route":"Recreation.gov","commission_status":"none","tier_absent_reason":"not-sold","blurb":"71 sites, no hookups, $25 a night, 100% reservation; \"Reservations are accepted 6 months ahead of time\" and \"the sites are full several months in advance\"; cancellations bookable \"even same day\"; four wheelchair-accessible sites"},{"name":"Cathedral Valley and Cedar Mesa primitive campgrounds","source":"https://www.nps.gov/care/planyourvisit/primitive-campgrounds.htm","accessed":"2026-10-02","si":["expedition","adventure"],"booking_route":"walk-in (first-come, first-served)","commission_status":"none","tier_absent_reason":"not-sold","blurb":"free, first-come, first-served: six sites at Cathedral Valley (7,000 ft, high-clearance 4WD usually necessary) and five at Cedar Mesa (5,500 ft, on Notom-Bullfrog Road); pit toilets, no water"},{"name":"Fishlake National Forest campgrounds: Singletree, Pleasant Creek, Oak Creek, Sunglow","source":"https://www.nps.gov/care/planyourvisit/camping-alternatives.htm","accessed":"2026-10-02","si":["family","hiking"],"booking_route":"not observed (USFS pages not fetched; Capitol Reef Country lists Singletree on Recreation.gov)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the NPS''s named camping alternatives on Boulder Mountain and near Bicknell"},{"name":"Capitol Reef Resort, Torrey","source":"https://www.capitolreefresort.com/","accessed":"2026-10-02","si":["glamping","family","romance","group"],"booking_route":"own site via Windsurfer CRS (res.windsurfercrs.com); phone 435-425-3761","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"stand-alone cabins, teepees and Conestoga wagons plus rooms and suites, heated outdoor pool and hot tub, with guided llama hikes, horseback trail rides and jeep safaris; 2600 E Highway 24"},{"name":"Capitol Reef RV Resort & Glamping, Teasdale","source":"https://visitcapitolreef.com/","accessed":"2026-10-02","si":["glamping","romance","family"],"booking_route":"RMS Cloud (bookings.rmscloud.com), linked from own site","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Star-gazing A-Frame Cabins\" with two large skylight windows from $150+ a night, and full-hookup RV sites from $55+ with back-ins up to 115 ft; mountain-spring water, dog park"},{"name":"Skyview Hotel, Torrey","source":"https://skyviewtorrey.com/","accessed":"2026-10-02","si":["glamping","romance","family"],"booking_route":"Cloudbeds (hotels.cloudbeds.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"rooms plus glamping King Skylight Dome, King Dome and Family Queen/Bunk Dome options in \"Utah''s first International Dark Sky certified community\"; breakfast boxes from Hunt and Gather; 876 West SR 24"},{"name":"Thousand Lakes RV Park, Torrey","source":"https://thousandlakesrvpark.com/","accessed":"2026-10-02","si":["glamping","family","adventure"],"booking_route":"ResNexus (own site); also Hipcamp, some sites instant book","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"79 sites (61 RV, 9 tent, 9 lodging from camping cabins to a super deluxe cabin for 6) with on-site 4x4 jeep rentals; listed by the Wayne County travel council as having glamping options; on Hipcamp, a 65 ft pull-through shows \"Booked 9 times\""},{"name":"Blue Valley Domes, Torrey","source":"https://capitolreefcountry.com/lodging/","accessed":"2026-10-02","si":["glamping"],"booking_route":"Lodgify (domes.lodgify.com, per the directory link; not loaded)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"listed by the Wayne County travel council under Cabins & Domes in Torrey; its own Lodgify site returned 403, so no detail was confirmed"},{"name":"Wonderland RV Park, Torrey","source":"https://wonderlandrvpark.com/","accessed":"2026-10-02","si":["family","glamping"],"booking_route":"ResNexus","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"full-hookup sites $56-$62, tent sites $40, an Econo Cabin $59, a Log Cabin $84 and a \"Buff Camp\" $59, at 44 S. SR 12"},{"name":"Sand Creek RV Park & Campground, Torrey","source":"https://sandcreekrv.com/","accessed":"2026-10-02","si":["family","group"],"booking_route":"ResNexus; phone 435.425.3577","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"pull-through full-hookup RV sites, tent sites, cabins and a family/deluxe cabin with a community pavilion for groups, pet-friendly; 540 W. Main Street"},{"name":"Ant Hill RV Park, Bicknell","source":"https://anthillrvpark.com/","accessed":"2026-10-02","si":["family"],"booking_route":"parkwith.us","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"two deluxe pull-through RV sites (145 ft and 101 ft) on concrete pads with gazebo patios, private dog runs and room for up to two horses per site; no store, shower house or public restrooms"},{"name":"Hanksville RV and Marine","source":"https://hanksvillervmarine.com/","accessed":"2026-10-02","si":["family","adventure"],"booking_route":"phone only ((435) 210-6673)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"RV park with boat parking and marine services, including decontamination, at the eastern gateway, between Capitol Reef, Goblin Valley, the Henry Mountains and Lake Powell"},{"name":"Capitol Reef Outfitters, Torrey","source":"https://www.capitolreefoutfitters.com/","accessed":"2026-10-02","si":["adventure","hiking","family"],"booking_route":"not observed (Book Now button; phone 435-425-3999)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"Local guides - Since 2001\": Cathedral Valley and Waterpocket Fold tours, Bentonite Hills, a buffalo safari to the Henry Mountains, Sulphur Creek Narrows hikes, fly fishing and UTV tours and rentals; 1012 East Highway 24"},{"name":"Capitol Reef Adventure Company","source":"https://www.capitolreefadventurecompany.com/","accessed":"2026-10-02","si":["adventure","hiking","sports"],"booking_route":"own site contact page; no engine observed","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"private canyoneering ($325 first person, $125 each extra), guided hikes ($300 first person, $50 each extra) and custom multi-sport trips"},{"name":"Waterpocket Adventure Company, Torrey","source":"https://waterpocketadventures.com/","accessed":"2026-10-02","si":["adventure","senior","romance"],"booking_route":"not observed (own site; phone 801 400-7558)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"luxury 4x4 tours: Temples of the Sun and Moon ($350-$540), Cathedral Valley ($540-$720), Burr Trail ($540-$720), Goblin Valley, a 2-hour Capitol Reef Sunset Tour from $260 and Dark Sky Photography from $270"},{"name":"Wilderness Ridge Adventures, Torrey","source":"https://wildernessridgeadventures.com/","accessed":"2026-10-02","si":["adventure","family"],"booking_route":"FareHarbor","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"guided horseback rides in Fishlake National Forest and Capitol Reef, from 1-hour introductions to full-day 6-8 hour rides; \"no experience needed, all riders welcome\""},{"name":"Wilderness Ridge Trail Llamas","source":"https://wildernessridgetrailllamas.com/","accessed":"2026-10-02","si":["hiking","family","expedition"],"booking_route":"FareHarbor","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"day and overnight llama hikes; \"an authorized Permittee of Fishlake National Forest Service\", operating on forest land next to the park rather than inside it"},{"name":"Get In The Wild, Hanksville","source":"https://getinthewild.com/","accessed":"2026-10-02","si":["adventure","expedition","sports"],"booking_route":"FareHarbor","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"guided canyoneering including a Capitol Reef National Park Canyoneering Adventure, a half-day Goblin''s Lair trip, slot canyons and multi-day expeditions; 175 HWY 24"},{"name":"Backcountry Safaris (Capitol Reef base)","source":"https://backcountrysafarisjh.com/","accessed":"2026-10-02","si":["adventure","wildlife"],"booking_route":"FareHarbor","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Jackson Hole jeep-tour company that lists Capitol Reef among its bases, alongside Yellowstone and Grand Teton"},{"name":"Fremont River Guides & Fly Shop, Torrey","source":"https://www.flyfishingsouthernutah.com/","accessed":"2026-10-02","si":["sports","wildlife","adventure"],"booking_route":"not observed (phone 435-425-3999)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"fly fishing since 2001 on the Fremont River and the Boulder Mountains'' \"over 50 fishable lakes and streams\", 2-8 hour trips, UTV remote trips and private water; shares phone numbers with Capitol Reef Outfitters"},{"name":"Hunt & Gather, Torrey","source":"http://huntandgatherrestaurant.com/","accessed":"2026-10-02","si":["culinary","romance"],"booking_route":"phone/email only ((435) 425-3070)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"New American cooking of \"wild game, fish, stone fruits, organic vegetables\", recognised with Slow Food USA''s Snail of Approval; 599 West Main Street, Wednesday to Sunday from 5 pm; reservations highly recommended"},{"name":"Etta Place Cidery & Taproom, Torrey","source":"https://www.ettaplacecider.com/","accessed":"2026-10-02","si":["culinary","wine","group"],"booking_route":"own site","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"an orchard-based cidery and meadery blending Kingston Black, Dabinett and Brown Snout with community-grown apples; billed as \"Torrey''s Only Local Bar\", 700 W. Main St"},{"name":"Cliffstone Restaurant at Red River Ranch, Teasdale","source":"http://www.redriverranch.com/cliffstone","accessed":"2026-10-02","si":["culinary","group","romance"],"booking_route":"phone only (435-425-3322)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the lodge''s farm-to-table restaurant with \"farm-fresh eggs sourced from right here on the ranch\" and buffalo sausage; breakfast daily 7:30-9:30 am, dinner by prearrangement for groups"},{"name":"Hell''s Backbone Grill & Farm, Boulder","source":"https://hellsbackbonegrill.com/","accessed":"2026-10-02","si":["culinary","romance","culture"],"booking_route":"own site (\"HBG Info & Reservations\"); engine not named","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a restaurant with its own working farm on Highway 12 in Boulder, open for 2026 Thursday to Monday 4-9 pm, with the Little Bone food truck daily; unified with Boulder Mountain Lodge since January 2025"},{"name":"Rim Rock Restaurant, Patio and Inn, Torrey","source":"http://www.therimrock.net/","accessed":"2026-10-02","si":["culinary","romance","family"],"booking_route":"rooms via direct-book.com; restaurant phone 435-425-3388","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"upscale Rim Rock Restaurant and the casual Patio, which \"frequently features Live Music\", with motel rooms and cabins at 2523 E Hwy 24; closes the last weekend of October, reopens the third weekend of March"},{"name":"Broken Spur Steakhouse and Inn, Torrey","source":"http://www.brokenspurinn.com/the-steakhouse","accessed":"2026-10-02","si":["culinary","family","group"],"booking_route":"not observed (inn books direct on own site)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a Western steakhouse of hand-cut steaks and house-made desserts, dinner 4:30-10 pm daily early March to mid-November; 955 East SR24"},{"name":"Duke''s Slickrock Grill, Hanksville","source":"https://www.dukesslickrock.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"Toast (online ordering)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a sit-down western BBQ grill of steaks and smoked meats on Main Street, 7 am-10 pm daily, with a campground and cabins under the same company"},{"name":"Stan''s Burger Shak, Hanksville","source":"http://www.stansburgershak.com/","accessed":"2026-10-02","si":["culinary","family"],"booking_route":"Toast (online ordering); walk-in","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"burgers, fries and shakes since 1984 at 150 UT-95"},{"name":"Cougar Ridge, Torrey","source":"https://www.cougarridge.com/","accessed":"2026-10-02","si":["romance","group","family"],"booking_route":"SynXis (be.synxis.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"\"a luxury ranch resort\" near Torrey with The Grand Lodge for families and groups, and meetings, events and weddings"},{"name":"Lodge at Red River Ranch, Teasdale","source":"https://www.redriverranch.com/","accessed":"2026-10-02","si":["romance","senior","culinary"],"booking_route":"iQ Web Book (us01.iqwebbook.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a great-western-style lodge on 2,000 acres with 15 individually decorated rooms, each with a balcony or patio over the cliffs and gardens"},{"name":"Cathedral Valley Inn, Caineville","source":"https://cathedralvalleyinn.com/","accessed":"2026-10-02","si":["family","adventure"],"booking_route":"own site (rooms page); phone (435) 456-9900","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"a boutique inn from $119 a night with pool, hot tub and continental breakfast on the park''s east side; 25 UT-24"},{"name":"Muddy Creek Mining Company cabins, Hanksville","source":"https://muddycreekminingcompany.com/","accessed":"2026-10-02","si":["adventure","family"],"booking_route":"Cloudbeds (hotels.cloudbeds.com)","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"new cabins with self check-in, pet-friendly, free laundry, near Goblin Valley, Factory Butte and the Bentonite Hills; 280 E 100 N"},{"name":"Entrada Institute, Torrey","source":"https://www.entradainstitute.org/","accessed":"2026-10-02","si":["culture","senior"],"booking_route":"own events calendar / Network for Good registration","commission_status":"unknown","tier_absent_reason":"not-sold","blurb":"the nonprofit that co-hosts Heritage StarFest and runs evening talks; October 2026: bees and fruit production in Capitol Reef (October 2), Mountain Meadows Massacre history (October 3), Barry Scholl (October 10)"},{"name":"Scenic Byway 12 to Boulder and Bryce Canyon","source":"https://www.nps.gov/care/planyourvisit/directions.htm","accessed":"2026-10-02","si":["adventure","romance","senior"],"booking_route":"none needed","commission_status":"none","tier_absent_reason":"not-sold","blurb":"the 123-mile highway connects Torrey with US-89 near Panguitch; \"The drive to or from Bryce Canyon to Capitol Reef takes about three (3) hours on SR-12\"; Visit Utah calls it \"an All-American Road\"; links this park to the library''s Bryce Canyon dossier"}],"faq":[{"q":"How much is the entrance fee at Capitol Reef?","a":"The NPS lists $20 for a private vehicle, $15 for a motorcycle and $10 per person on foot or bicycle (under 16 free), valid seven days, or $35 for a Capitol Reef annual pass.","source":"https://www.nps.gov/care/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"Can I get a site at Fruita Campground without a reservation?","a":"The NPS states the campground has a 100% reservation system, that reservations open 6 months ahead, and that sites are full several months in advance. Cancelled reservations can be booked, even the same day, on Recreation.gov.","source":"https://www.nps.gov/care/planyourvisit/fruitacampground.htm","accessed":"2026-10-02"},{"q":"Can I pick fruit in the Fruita orchards?","a":"Yes, in season, in orchards posted with U-Pick Fruit signs; fruit taken must be paid for at the self-pay station. The NPS gives approximate harvests of apricots late June to mid-July, peaches late July to early September, pears early August to early September and apples mid-August to mid-October.","source":"https://www.nps.gov/care/learn/historyculture/orchards.htm","accessed":"2026-10-02"},{"q":"Is the Capitol Gorge road open?","a":"Not on the date of this build: the NPS road table updated 9/30/2026 lists Capitol Gorge as Closed. The Scenic Drive and Grand Wash are listed 2WD.","source":"https://www.nps.gov/care/planyourvisit/conditions.htm","accessed":"2026-10-02"},{"q":"Do I need a 4x4 for Cathedral Valley?","a":"The NPS says high-clearance vehicles can usually manage the roads, but the loop requires fording the Fremont River and conditions vary with weather. On 10/1/2026 it listed Cathedral Valley as HC4WD to Gypsum Sinkhole and Hartnet Road as likely impassable.","source":"https://www.nps.gov/care/planyourvisit/cathedralvalley.htm","accessed":"2026-10-02"},{"q":"When can I buy pie at the Gifford House?","a":"The NPS says the Gifford House store and museum is open March 14 (Pi Day) through late November, daily 9 am to 4:30 pm, and sells locally baked fruit pies and homemade ice cream.","source":"https://www.nps.gov/care/planyourvisit/hours.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Capitol Reef National Park: Fruita Orchards, Pies & Cathedral Valley | TravelWell","meta_description":"Capitol Reef''s u-pick orchards and Gifford House pies, Hickman Bridge and Cathedral Valley, dated road closures, and where to stay from wagons to Fruita Campground.","slug":"capitol-reef-national-park-utah","primary_keyword":"Capitol Reef National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Capitol Reef National Park, Utah"}}'::jsonb, 77),
  ('canyonlands-utah', '12A', 'Canyonlands National Park', 'United States', 'Mesa Arch sunrise and the White Rim', 'future', 'verified', 'mountainValley', 'Utah Canyon Country', '{"hiking","adventure","river","motoring","glamping","parks"}', '{"dramatic","rugged","remote","wild","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Mesa Arch","source":"https://www.nps.gov/cany/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - park trail (park entrance fee applies)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"Island in the Sky, EASY, 0.6 miles round trip, about 30 minutes: \"A short hike leads to a cliff-edge arch. Mesa Arch is a classic sunrise spot and is popular among photographers.\""},{"name":"Grand View Point","source":"https://www.nps.gov/cany/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"none needed - park trail (park entrance fee applies)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"Island in the Sky, EASY, 1.8 miles round trip, about 1.5 hours: \"A stunning out-and-back trail, this walk showcases spectacular panoramic views as it follows the canyon edge.\" Ranger programs are offered at Grand View Point."},{"name":"Island in the Sky district","source":"https://www.nps.gov/cany/planyourvisit/islandinthesky.htm","accessed":"2026-10-03","si":["motoring","hiking","family"],"booking_route":"entrance fee at the gate ($30 per vehicle, card only)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"The Island in the Sky mesa rests on sheer sandstone cliffs over 1,000 feet (304 m) above the surrounding terrain.\" About 40 minutes'' drive from Moab by US 191 and UT 313; the visitor center \"is open year-round, seven days a week, with some closed days in winter.\""},{"name":"White Rim Road","source":"https://www.nps.gov/cany/planyourvisit/whiterimroad.htm","accessed":"2026-10-03","si":["adventure","motoring","sports"],"booking_route":"permit on Recreation.gov (overnight: $36 reservation fee plus $5 per person per night)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":4,"blurb":"\"The 100-mile White Rim Road loops around and below the Island in the Sky mesa top\" and needs \"high-clearance, four-wheel-drive vehicles\"; \"All vehicles, motorbikes, and bicyclists must have a day-use permit for single day trips on the White Rim.\" Overnight trips use \"20 individual campsites arranged in 10 camping areas\". The Shafer Trail and Mineral Bottom switchbacks \"require extreme caution.\""},{"name":"The Needles district","source":"https://www.nps.gov/cany/planyourvisit/needles.htm","accessed":"2026-10-03","si":["hiking","adventure","motoring"],"booking_route":"entrance fee at the gate ($30 per vehicle, card only)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"named for the colorful spires of Cedar Mesa Sandstone\"; trails and roads \"lead to such features as Tower Ruin, Confluence Overlook, Elephant Hill, the Joint Trail, and Chesler Park.\" Reached by UT 211, 14 miles north of Monticello on US 191 then about 35 miles west; the visitor center \"is open daily, spring through fall.\""},{"name":"Chesler Park Viewpoint","source":"https://www.nps.gov/cany/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"The Needles, STRENUOUS, 5.8 miles round trip, 3-4 hours: \"This popular trail leads to a pass overlooking a scenic expanse of desert grasses and shrubs surrounded by sandstone spires.\""},{"name":"Druid Arch","source":"https://www.nps.gov/cany/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"The Needles, STRENUOUS, 10.8 miles round trip, 5-7 hours: \"This trail offers one of the most spectacular views in The Needles\", following Elephant Canyon \"through deep sand and loose rock.\""},{"name":"Cave Spring Trail","source":"https://www.nps.gov/cany/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["family","hiking","culture"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"The Needles, EASY/MODERATE, 0.6-mile loop, about 45 minutes: \"This short loop leads to a historic cowboy camp and prehistoric rock paintings and peckings. You will climb two ladders to complete the route.\""},{"name":"Upheaval Dome","source":"https://www.nps.gov/cany/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"Island in the Sky, MODERATE, 0.6 miles to the first overlook, about 30 minutes: \"A short but steep trail leads to a clear view into Upheaval Dome. Exhibits at the end of the trail discuss this unique geologic feature.\""},{"name":"Aztec Butte","source":"https://www.nps.gov/cany/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","culture"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"Island in the Sky, MODERATE, 1.4 miles round trip, about 1.5 hours, 225 feet of elevation change; the trail forks to \"spectacular views\" and to \"ancestral Puebloan structures.\""},{"name":"Whale Rock","source":"https://www.nps.gov/cany/planyourvisit/hiking.htm","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"Island in the Sky, MODERATE, 0.8 miles round trip, about 1 hour: \"This trail leads up the side of a sandstone dome, ending with broad views.\""},{"name":"The Maze and Hans Flat Ranger Station","source":"https://www.nps.gov/cany/planyourvisit/maze.htm","accessed":"2026-10-03","si":["expedition","adventure","motoring"],"booking_route":"overnight backcountry permit on Recreation.gov","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":12,"blurb":"\"The Maze is the least accessible district of Canyonlands\"; \"Rarely do visitors spend less than three days in the Maze\". Hans Flat Ranger Station, 2.5 hours from Green River, \"is open to the public 8 am to 4 pm daily\"; from there the canyons are \"another 3 to 6 hours by high-clearance, four-wheel-drive vehicle.\" \"There are no services, food, gas, or potable water sources in The Maze.\""},{"name":"Horseshoe Canyon guided hikes","source":"https://www.nps.gov/cany/planyourvisit/maze.htm","accessed":"2026-10-03","si":["culture","hiking","adventure"],"booking_route":"ranger-led; no booking route on the page read","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"Part of The Maze district: \"The Maze offers guided hikes in Horseshoe Canyon most weekends during spring and fall.\""},{"name":"Cataract Canyon","source":"https://www.nps.gov/cany/planyourvisit/boating.htm","accessed":"2026-10-03","si":["river","adventure","expedition"],"booking_route":"guided trip with a licensed outfitter, or a private river permit on Recreation.gov","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":14,"blurb":"\"Cataract Canyon contains 14 miles of rapids that range in difficulty up to Class V\" - a \"fourteen-mile stretch of Class III to V whitewater\" where the combined flow of the Green and Colorado \"spills down ... with remarkable speed and power.\" \"Some companies offer guided whitewater river trips that vary in length from one to many days.\""},{"name":"Flatwater on the Green and Colorado","source":"https://www.nps.gov/cany/planyourvisit/boating.htm","accessed":"2026-10-03","si":["river","adventure","family"],"booking_route":"river permit on Recreation.gov; canoe shuttles from Moab outfitters","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":15,"blurb":"\"Flatwater trips may float down either the Colorado or Green rivers as far as Spanish Bottom\", with \"miles and miles of flatwater perfect for canoes, sea kayaks and other shallow-water boats.\" Permits are required for all day-use and overnight river trips."},{"name":"Island in the Sky Campground (Willow Flat)","source":"https://www.recreation.gov/camping/poi/247541","accessed":"2026-10-03","si":["hiking","motoring","adventure"],"booking_route":"first-come, first-served; no reservations","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"\"Island in the Sky Campground (Willow Flat) has 12 sites, first-come, first-served.\" \"Nightly camping fee is $15 per site.\" \"Sites fill quickly spring through fall.\" \"There is no water at the campground\"; vehicles up to 28 feet. Open year-round."},{"name":"The Needles Campground","source":"https://www.nps.gov/cany/faqs.htm","accessed":"2026-10-03","si":["hiking","family","motoring","group"],"booking_route":"Recreation.gov for reservable sites; first-come for the rest","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"\"The Needles Campground has 26 sites with fire rings, picnic tables, bathrooms, and running water.\" \"You can reserve some individual sites and all group sites at The Needles.\" $20 a night; group sites $70 to $225. No RV hookups; RVs up to about 28 feet."},{"name":"Overnight backcountry permits","source":"https://www.nps.gov/cany/planyourvisit/backcountrypermits.htm","accessed":"2026-10-03","si":["adventure","hiking","expedition"],"booking_route":"Recreation.gov","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":18,"blurb":"Backpacking, four-wheel-drive and mountain-bike permits on Recreation.gov, opening four months before each season at 8 am MT; \"a non-refundable $36 reservation fee for each permit\" plus \"$5 per person, per night\". \"Overnight permits are very competitive for White Rim trips in spring and fall and Needles backpacking trips in spring.\""},{"name":"Kit for desert heat and water","source":"https://www.nps.gov/cany/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - nothing is sold by the park","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":19,"blurb":"The park''s own guidance: carry \"at least 2-3 liters per person for front country hikes, and 4 liters or more for backcountry\"; \"Plan your activities during the cooler parts of the day (early morning or late evening)\". The hiking page adds: \"Avoid hiking during peak heat on summer days\" and \"Carry a flashlight, map, and basic first aid equipment.\""},{"name":"Kit for navigation, layers and footing","source":"https://www.nps.gov/cany/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","adventure","expedition"],"booking_route":"affiliate retail referral (REI.com via AvantLink; Amazon Associates) - park maps are sold in the visitor center bookstores","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":20,"blurb":"\"Download park maps for offline use\" and \"bring a physical park map and compass as a backup\"; \"Bring or dress in layers to adapt to changing conditions, especially if camping in fall, winter, or spring\"; \"Footwear with good tread that can keep traction on uneven terrain.\" In The Maze, visitors need \"the proper equipment or gear for self-rescue.\""},{"name":"Dead Horse Point State Park","source":"https://stateparks.utah.gov/parks/dead-horse/","accessed":"2026-10-03","si":["hiking","glamping","family"],"booking_route":"Utah State Parks online reservations (link on the park page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":21,"blurb":"Utah state park on the road to Island in the Sky: \"An immense desert landscape of canyons, high desert woodland, and miles of trails\", known for sunrises, sunsets and dark skies. Camping and two sets of yurts - \"Pets are not allowed in the Wingate Yurts\" but \"Moenkopi Yurts are pet friendly\"; day passes sold online."},{"name":"Under Canvas Moab","source":"https://www.undercanvas.com/camps/moab/","accessed":"2026-10-03","si":["glamping","romance","family"],"booking_route":"own website booking (undercanvas.com)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":22,"blurb":"\"just seven miles north of Moab, near Utah''s famed Canyonlands and Arches national parks\" - about 25 minutes from the Island in the Sky entrance; Deluxe, Stargazer, Suite and Safari tents and kids'' tents; pet-friendly for a small nightly fee; an International DarkSky-certified resort. 2026 season March 5 - November 1; 2027 March 4 - October 31."},{"name":"Needles Outpost","source":"https://www.needlesoutpost.com/","accessed":"2026-10-03","si":["hiking","glamping","adventure"],"booking_route":"own website booking","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","shop"],"draw_rank":23,"blurb":"\"Rustic camping a stone''s throw from Needles District\", 1.5 miles from the Needles visitor center - \"the closest camping to the park\": dry tent and RV sites, \"The Mo''Rockin Bell Tent\" with a queen bed, and a group site for up to 15. \"Camping is open 1 March to 20 November. Spring and fall weekends book up early.\" Store open March 15 - November 15."},{"name":"Moab RV and Glamping Resort","source":"https://www.hipcamp.com/en-US/land/utah-moab-rv-and-glamping-resort-06yh86ro","accessed":"2026-10-03","si":["motoring","glamping","family"],"booking_route":"Hipcamp instant booking","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"Moab: 43 RV sites with full hookups, 28-foot to 65-foot pull-through and back-in, \"30/50 Amp\"; 25 cabins, glamping tents and tipis with \"heat, AC, tvs, and more\"; \"Pet-friendly for a fee\". About 60 minutes from Island in the Sky per the listing."},{"name":"BLM campgrounds around Moab","source":"https://www.discovermoab.com/stay/campgrounds/blm-campgrounds/","accessed":"2026-10-03","si":["motoring","hiking","adventure"],"booking_route":"first-come cash at the campground; Ken''s Lake on Recreation.gov","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"The BLM \"maintains 26 campgrounds in the Moab area\"; most are \"first-come/first-served basis and no reservations are accepted\", except Ken''s Lake (10 miles south of Moab) and some group sites on Recreation.gov. \"All individual sites are $20/night. Pay at the campground with exact cash\"; \"drinking water is NOT available\"; stays limited to 14 days in 30."},{"name":"Hyatt Place Moab","source":"https://www.hyattplacemoab.com/","accessed":"2026-10-03","si":["family","senior","motoring"],"booking_route":"hyatt.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_basis":"benchmark","wells":["stay"],"draw_rank":26,"blurb":"The hotel''s own domain hyattplacemoab.com redirects (HTTP 301) to Hyatt''s property page \"hyatt.com/en-US/hotel/utah/hyatt-place-moab/slczm\", which refused the fetch (HTTP 403) - so the Hyatt Place brand affiliation is confirmed and nothing else about the property is stated here."},{"name":"Holiday Inn Express Hotel & Suites, Moab","source":"https://en.wikivoyage.org/wiki/Moab","accessed":"2026-10-03","si":["family","senior","motoring"],"booking_route":"ihg.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":27,"blurb":"Listed by Wikivoyage''s Moab guide at \"1515 Hwy 191 North\", +1 435 259-1150, with ichotelsgroup.com as its website. The IHG brand page was not fetched (IHG pages return 403), so nothing else about the property is stated here."},{"name":"Sorrel River Ranch Resort & Spa","source":"https://www.sorrelriver.com/","accessed":"2026-10-03","si":["romance","wellness","adventure"],"booking_route":"own website / stay@sorrelriver.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay","beauty"],"draw_rank":28,"blurb":"Mile 17, UT-128 on the Colorado River: \"A luxury Moab resort\" of custom-built cabins across 240 acres; Condé Nast Johansens Award Winner 2024 and listed with Forbes Travel Guide; horseback riding, mountain biking, hiking and spa. 435.259.4642."},{"name":"Sheri Griffith Expeditions","source":"https://www.griffithexp.com/","accessed":"2026-10-03","si":["river","expedition","adventure"],"booking_route":"online booking (go.theflybook.com) or phone (435) 259-8229","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":29,"blurb":"Moab river outfitter: Cataract Canyon trips \"ranging from 4 to 11 days\", including the 11-day \"John Wesley Powell Expedition\" on the Green and Colorado through Canyonlands, by oarboat, motorized J-rig or paddle boat; one-day trips too. (435) 259-8229."},{"name":"Navtec Expeditions","source":"https://www.navtec.com/","accessed":"2026-10-03","si":["river","adventure","motoring"],"booking_route":"own website booking","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":30,"blurb":"Moab, operating \"since 1896\" and \"an authorized concessioner of Canyonlands and Arches National Park\": rafting, 4x4 backcountry tours, canyoneering and park tours. 1-800-833-1278; 435-259-7983."},{"name":"Canyonlands by Night & Day","source":"https://www.canyonlandsbynight.com/","accessed":"2026-10-03","si":["river","family","romance"],"booking_route":"FareHarbor (\"BOOK NOW!\") or phone","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":31,"blurb":"\"family-owned tour company on the banks of the Colorado River near Moab\", running trips \"since 1963\": Sound and Light Show jet boat tours, a sunset jet boat with dinner, canoe shuttles for the Green and Colorado, 4x4 and helicopter tours. (800) 394-9978."},{"name":"Rim Tours","source":"https://www.rimtours.com/","accessed":"2026-10-03","si":["sports","adventure","hiking"],"booking_route":"phone (435) 259-5223 or request form","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":32,"blurb":"\"Moab''s Original Mountain Bike Tour Guides\", since 1985: the White Rim as a 4-day camping trip and a full-day Canyonlands tour, small groups, plus \"Bike & Gear Rentals\". (435) 259-5223."},{"name":"Moab Cyclery","source":"https://www.moabcyclery.com/","accessed":"2026-10-03","si":["sports","adventure"],"booking_route":"own website booking / walk-in","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities","shop"],"draw_rank":33,"blurb":"391 S. Main St., Moab, \"Open Daily 7:00 AM - 6:00 PM\": \"Moab bike rentals, shuttles, repairs, gear, and local trail advice\" - mountain bikes and e-bikes \"set up for desert riding\", trail shuttles, and \"water bottles, and all your trail essentials\"."},{"name":"Moab","source":"https://www.discovermoab.com/","accessed":"2026-10-03","si":["adventure","culinary","family"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":34,"blurb":"The gateway to Island in the Sky, about 40 minutes from its visitor center (NPS): \"A small town with a big spirit on the banks of the Colorado River, surrounded by two national parks and the red-rock horizons of the American West.\" Moab Office of Tourism, 25 E Center St."},{"name":"Monticello","source":"https://www.utahscanyoncountry.com/Monticello/","accessed":"2026-10-03","si":["motoring","hiking"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":35,"blurb":"The southern gateway, 14 miles south of the UT 211 turn to The Needles (NPS): \"Elevation: 7,069 feet (2,155 meters)\", \"Sheltered by the Abajo Mountains\", with \"Full services\" and day tours to Canyonlands, the Needles and Canyon Rims Recreation Area."},{"name":"Moab Brewery","source":"https://www.themoabbrewery.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / phone (435) 259-6333","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"686 S. Main St.: \"Our inspiration for our products comes from the beautiful and unique landscape in and around Moab, UT\" - beer, spirits and scratch-cooked food; \"Open Daily at 11:00am\". (435) 259-6333."},{"name":"Desert Bistro","source":"https://www.desertbistro.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"Tock (exploretock.com/desert-bistro), 1-6 guests","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":37,"blurb":"36 S 100 W: \"Internationally inspired fine cuisine with a southwestern flair\"; \"Open Nightly 5pm to Close\". 435-259-0756."},{"name":"Sabaku Sushi","source":"https://www.sabakusushi.com/visit","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"online reservations or walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":38,"blurb":"90 E. Center Street, \"open tue - sat 5pm - 9pm\"; \"We only reserve half the tables in the restaurant, the other half is left available for walk in service.\" 435-259-4455."},{"name":"98 Center","source":"https://www.98center.com/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in / phone 435-355-0098","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":39,"blurb":"98 East Center Street: \"Asian and Local fusion restaurant in Moab, UTAH\" - pho, bánh mì and salads made from scratch; \"Wednesday - Sunday 11:30 AM - 9:00 PM\". 435-355-0098."},{"name":"Pasta Jay''s","source":"https://www.pastajays.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in / phone (435) 259-2900","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":40,"blurb":"4 S Main Street: \"Where Red Rocks Meet Italian Flavor\"; \"Open Daily 11am – 11pm\". (435) 259-2900."},{"name":"River Grill at Sorrel River Ranch","source":"https://www.sorrelriver.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"phone 435.259.4642","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":41,"blurb":"Mile 17, UT-128: \"Unforgettable dining along the Colorado River, where Moab''s red rock cliffs\" frame indoor and outdoor starlit meals. 435.259.4642."}],"faq":[{"q":"How much does it cost to get into Canyonlands National Park?","a":"\"$30.00\" per private vehicle (\"Admits one private, non-commercial vehicle (15 passenger capacity or less) and all its occupants\"), \"$25.00\" per motorcycle and \"$15.00\" per person on foot or bicycle; \"Youth 15 and under are admitted free.\" Entrance stations take \"Credit/Debit Only\".","source":"https://www.nps.gov/cany/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Do you need timed entry for Canyonlands National Park?","a":"No: \"Timed entry reservations are not required to enter the park.\"","source":"https://www.nps.gov/cany/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Do you need a permit for Canyonlands National Park?","a":"Not to visit, but \"You need a backcountry permit for: vehicle, motorbike, and bicycle day-use trips on White Rim, Elephant Hill, Lavender Canyon, and Peekaboo/Horse Canyon roads; all overnight trips; all day-use and overnight river trips.\"","source":"https://www.nps.gov/cany/faqs.htm","accessed":"2026-10-03"},{"q":"How far is Canyonlands National Park from Moab?","a":"To Island in the Sky, \"drive 10 miles (16 km) north of Moab\" on US 191, then UT 313 \"southwest 22 miles (35 km). Driving time to the visitor center from Moab is about 40 minutes.\" The Needles is reached \"40 miles (60 km) south of Moab\" on US 191, then about 35 miles west on UT 211.","source":"https://www.nps.gov/cany/planyourvisit/islandinthesky.htm","accessed":"2026-10-03"},{"q":"Can you drive through Canyonlands National Park?","a":"Not from one district to another: \"No bridges or roads connect the districts within the park.\" UT 313 leads to Island in the Sky, UT 211 to The Needles, and \"Only unpaved roads reach The Maze (graded dirt or high-clearance, four-wheel-drive).\"","source":"https://www.nps.gov/cany/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"What is the best time to visit Canyonlands National Park?","a":"\"The temperate—and most popular—seasons are spring (April through May) and fall (mid-September through October)\", with highs averaging 60º to 80ºF. In summer \"temperatures often exceed 100ºF (37ºC)\" and late-summer monsoon storms \"often cause flash floods.\"","source":"https://www.nps.gov/cany/planyourvisit/weather.htm","accessed":"2026-10-03"},{"q":"Is Canyonlands National Park open year round?","a":"Yes: \"Canyonlands National Park is normally open year-round, 24 hours a day.\" Each district''s visitor center \"has its own visitor center with operating hours that change with the seasons. Some facilities close in winter.\"","source":"https://www.nps.gov/cany/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"Can you bring dogs to Canyonlands National Park?","a":"Only in limited places: leashed pets may go \"Along established front-country roads or in parking areas\" and \"In established front-country campgrounds and picnic areas\" - not \"on any hiking trails, or anywhere off-trail, even while in a carrier\", \"at any overlooks\", in buildings, or in the backcountry, including river trips.","source":"https://www.nps.gov/cany/planyourvisit/pets.htm","accessed":"2026-10-03"},{"q":"Can you fly drones in Canyonlands National Park?","a":"No. \"Launching, landing, or operating unmanned aircraft (such as drones, quadcopters, or model airplanes) is prohibited.\"","source":"https://www.nps.gov/cany/faqs.htm","accessed":"2026-10-03"},{"q":"What is the closest airport to Canyonlands National Park?","a":"Canyonlands Field (CNY), \"16 miles from Moab\"; Grand Junction Regional (GJT) is \"113 miles from Moab\" and Salt Lake City International (SLC) \"237 miles from Moab\". \"There is no public transportation to Canyonlands.\"","source":"https://www.nps.gov/cany/planyourvisit/directions.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Canyonlands National Park: Mesa Arch, White Rim & Camping | TravelWell","meta_description":"Island in the Sky, The Needles and The Maze: Mesa Arch, the 100-mile White Rim Road, Cataract Canyon, two park campgrounds and stays around Moab.","slug":"canyonlands-national-park-utah","primary_keyword":"Canyonlands National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Canyonlands National Park Mesa Arch sunrise"}}'::jsonb, 78),
  ('sand-hollow-utah', '12A', 'Sand Hollow State Park', 'United States', 'Blue reservoir and red Sand Mountain dunes', 'future', 'verified', 'mountainValley', 'Utah Canyon Country', '{"adventure","family","motoring","diveglobal","hiking","glamping","parks"}', '{"dramatic","rugged","adventurous","family-friendly"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Sand Hollow Reservoir","source":"https://stateparks.utah.gov/parks/sand-hollow/history/","accessed":"2026-10-03","si":["family","adventure","sailing"],"booking_route":"day-use fee at the park ($25 Utah resident vehicle, $35 non-resident vehicle, $5 walk-in)","commission_status":"unknown","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"warm, blue waters and red sandstone landscape\"; 1,322 surface acres, \"nearly twice as large as the nearby Quail Creek Reservoir\"; beach access, boating, swimming, kayaking, waterskiing and fishing, with a boat ramp and floating docks. \"There is no spearfishing on Sand Hollow Reservoir.\""},{"name":"Sand Mountain OHV Area","source":"https://stateparks.utah.gov/parks/sand-hollow/history/","accessed":"2026-10-03","si":["adventure","motoring","family"],"booking_route":"none needed beyond the park day-use fee","commission_status":"unknown","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"Sand Mountain OHV Acreage: 15,000\" of a 20,000-acre park; visitors \"explore and ride the dunes of Sand Mountain on an off-highway vehicle\", and the park points riders to the Utah OHV Program."},{"name":"Westside Campground","source":"https://stateparks.utah.gov/parks/sand-hollow/camping-lodging/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"ReserveAmerica (Utah State Parks reservations) or 1 (800) 322-3770","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":3,"blurb":"\"50 sites (2 ADA-accessible sites)\" with \"Full hookups (Water, 30/50 Amp Electric, and Sewer connections at every site)\" and \"Modern restrooms with flush toilets and hot showers\"; \"$50.00 / night\"."},{"name":"Sand Hollow Cottages","source":"https://stateparks.utah.gov/parks/sand-hollow/camping-lodging/","accessed":"2026-10-03","si":["family","motoring","romance"],"booking_route":"ReserveAmerica (Utah State Parks reservations) or 1 (800) 322-3770","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":4,"blurb":"Two beachside cottages, \"Sleeps up to 6\", with kitchenette, heating/AC and full bathroom; \"Full RV hook-up site included\"; \"Two night minimum\"; pets allowed in Cottage 1 only. Fee page: \"Sand Hollow Cottages: Per night (Amenities: AC, heat, kitchenette) $200\"."},{"name":"Lakeview Campground","source":"https://stateparks.utah.gov/parks/sand-hollow/camping-lodging/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"ReserveAmerica (Utah State Parks reservations) or 1 (800) 322-3770","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":5,"blurb":"\"30 sites (3 ADA-accessible sites)\": 8 full-hookup and 22 partial-hookup sites, \"Modern restrooms with flush toilets and hot showers\"; \"$45.00 / night\" partial, \"$50.00 / night\" full hookup."},{"name":"Sand Pit Campground","source":"https://stateparks.utah.gov/parks/sand-hollow/camping-lodging/","accessed":"2026-10-03","si":["family","group","adventure"],"booking_route":"ReserveAmerica (Utah State Parks reservations) or 1 (800) 322-3770","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":6,"blurb":"\"22 sites total\" - dry, partial-hookup and group sites, \"Modern restrooms and hot showers nearby\"; \"$28.00 - $35.00 / night\" dry, \"$35.00 - $45.00 / night\" partial, \"$75.00 - $125.00 / night\" groups."},{"name":"Primitive Beach Camping","source":"https://stateparks.utah.gov/parks/sand-hollow/camping-lodging/","accessed":"2026-10-03","si":["adventure","motoring","family"],"booking_route":"ReserveAmerica (Utah State Parks reservations) or 1 (800) 322-3770","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":7,"blurb":"\"Dispersed shoreline zones (40+ vehicle capacity depending on water levels)\", no hookups or facilities, \"$30.00 / night per vehicle\"; fires here are restricted to propane fires and grills, and \"Wood and charcoal are never allowed in this campground.\""},{"name":"Beachside Campground","source":"https://stateparks.utah.gov/parks/sand-hollow/camping-lodging/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"ReserveAmerica (Utah State Parks reservations) or 1 (800) 322-3770","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":8,"blurb":"\"4 (Back in only)\" sites with \"30/50 Amp Electric hookups\" and \"No restroom facilities\"; \"$55.00 / night per vehicle\"."},{"name":"Sand Hollow Rentals","source":"https://www.sandhollowrentals.com/","accessed":"2026-10-03","si":["adventure","family","sailing"],"booking_route":"own website online booking or 435-383-1200","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":9,"blurb":"The park''s named concession: \"ATV''s, UTV''s, kayaks, paddle boards and more\". Its own site rents \"Sea Doo''s, Pontoon Boats, Ski Boats\" and \"Wakeboards, Kayaks, SUPs, Trampolines, Canoes\", and runs Sand Mountain OHV tours from \"TWO HOUR\" ($389) to \"four HOUR\" ($489); \"You must be 18 years or older to rent.\" 3351 Sand Hollow Rd., Hurricane; 435-383-1200."},{"name":"Dixie Divers and the Sand Hollow Dive Shack","source":"https://divedixie.com/","accessed":"2026-10-03","si":["diveglobal","adventure"],"booking_route":"own website or (435) 627-2173","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":10,"blurb":"\"For your convenience we operate the Dive Shack at Sandhollow State Park during the summer!\" - \"We have everything you need for a dive at the lake.\" The St. George shop (558 E. Riverside Dr. #108, (435) 627-2173) teaches \"Discover Scuba and Open Water to Master Diver\"; the park lists it as a \"full-service Dive Center offering classes, gear, rentals and Dive travel\", May through October."},{"name":"Life jackets for the reservoir","source":"https://stateparks.utah.gov/parks/sand-hollow/boating-decontamination/","accessed":"2026-10-03","si":["family","adventure","sailing"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":11,"blurb":"The park''s own kit rule: \"All vessels must be equipped with a properly fitted life jacket for every passenger on board\"; \"Children under the age of 13 are required to wear a lifejacket at all times while the vessel is underway.\" Non-motorized craft and non-Utah residents must also complete the Mussel Awareness Course before launching."},{"name":"Dune whip flag and OHV helmet","source":"https://www.offroad-ed.com/utah/studyGuide/Meeting-OHV-Equipment-Requirements/401046_160743/","accessed":"2026-10-03","si":["adventure","motoring","family"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates); or the park gift shop","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":12,"blurb":"Utah''s OHV course on dune riding: \"a red or orange whip flag must be attached to the vehicle. The flag must be at least 6\" x 12\" in size and must be at least eight feet off the ground\"; \"All OHV operators and passengers under 18 years of age must wear a helmet that is properly fitted and fastened.\" The park''s visitor-center gift shop stocks \"OHV safety equipment\"."},{"name":"Sand Hollow Visitor Center and Gift Shop","source":"https://stateparks.utah.gov/parks/sand-hollow/rentals-food/","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"walk-in","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop","gear"],"draw_rank":13,"blurb":"Open 7 a.m. - 9 p.m.; the gift shop offers \"quality souvenirs including apparel, magnets and stickers, OHV safety equipment, water toys\" plus limited snacks and drinks; fishing proclamations are available here. 435-680-0715."},{"name":"Zion National Park","source":"https://www.nps.gov/zion/index.htm","accessed":"2026-10-03","si":["hiking","adventure","family","wildlife"],"booking_route":"national park entry; campground via Recreation.gov","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"Gaze up at massive sandstone cliffs of cream, pink, and red that soar into a brilliant blue sky.\" Springdale, UT 84767; 435-772-3256. Its Watchman Campground: \"Standard sites can be reserved up to 6 months in advance.\""},{"name":"Snow Canyon State Park","source":"https://stateparks.utah.gov/parks/snow-canyon/","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"day-use pass at the park","commission_status":"unknown","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"\"a 7,400-acre scenic park quietly tucked amid lava flows and soaring sandstone cliffs\", with \"more than 38 miles of hiking trails, a three-mile paved walking/biking trail and over 15 miles of equestrian trails\"; open \"6 a.m. to 10 p.m. Daily\"."},{"name":"Snow Canyon State Park Campground","source":"https://stateparks.utah.gov/parks/snow-canyon/","accessed":"2026-10-03","si":["hiking","family","motoring"],"booking_route":"ReserveAmerica (Utah State Parks reservations)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"\"Camping is available year-round at the 38-unit campground; reservations are recommended during peak seasons\"; reserved \"48 hours to 4 months in advance online\". \"Backcountry camping is not permitted in Snow Canyon.\""},{"name":"Quail Creek State Park","source":"https://stateparks.utah.gov/parks/quail-creek/","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"day-use at the park; campsites by phone 1-800-322-3770","commission_status":"unknown","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":17,"blurb":"\"Quail Creek reservoir was completed in 1985 to provide irrigation and culinary water to the St. George area\"; \"some of the warmest waters in the state and a mild winter climate\", 600 surface acres, up to 120 feet deep; rainbow trout, bullhead catfish and crappie below, largemouth bass and bluegill above. Campsites: \"To reserve all campsites call 1-800-322-3770.\""},{"name":"Sand Hollow Resort Championship Course","source":"https://www.sandhollowresort.com/","accessed":"2026-10-03","si":["golf","sports"],"booking_route":"own website tee times or (435) 656-4653","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":18,"blurb":"5662 W Clubhouse Dr., Hurricane: a \"Championship Course\" \"Consistently ranked #1 in Utah\", a Golfweek \"Top 100 Resort Course\", with \"three of Golf Digest''s top 100 golf holes in the country\"; \"surrounded by the captivating beauty of Sand Hollow Reservoir\". (435) 656-4653."},{"name":"Vacation Villas at Sand Hollow Resort","source":"https://www.sandhollowresort.com/","accessed":"2026-10-03","si":["golf","family","group"],"booking_route":"own website or (435) 656-4653","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"\"vacation rentals to suit every need\" - \"homes, condos, and suites in the Vacation Villas at Sand Hollow Resort\" beside the golf course, with Horizon Kitchen + Spirits on site."},{"name":"Hurricane Valley","source":"https://greaterzion.com/hurricane-valley/","accessed":"2026-10-03","si":["adventure","family","motoring"],"booking_route":"none needed - a town","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":20,"blurb":"The gateway towns of Hurricane, La Verkin, Toquerville, Leeds and Apple Valley, with \"mountain bike trails, OHV destinations, camping, and water sports at two state parks, set among red rock mesas\" (Greater Zion tourism board)."},{"name":"St. George / Hurricane KOA","source":"https://greaterzion.com/accommodations/st-george-hurricane-koa/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"koa.com or (800) 562-8607","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":21,"blurb":"5800 Old Hwy 91, Hurricane: \"114 RV, 15 Tent, 11 Cabins\" in the Hurricane Valley (Greater Zion listing; koa.com refused the fetch, HTTP 403). (800) 562-8607."},{"name":"Under Canvas Zion","source":"https://www.undercanvas.com/camps/zion/","accessed":"2026-10-03","si":["glamping","romance","hiking","family"],"booking_route":"own website; travel advisors via undercanvas.com/travel-advisor/","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":22,"blurb":"Safari-tent camp in Virgin, Utah: Deluxe, Stargazer, Suite and \"Angels Landing Suite (sleeps up to 6)\" tents with private ensuite bathrooms, wood-burning stoves, on-site dining, nightly campfires and s''mores; dogs welcome for a nightly fee. Season 2026 \"March 12th - November 8th\"."},{"name":"Cliffrose Springdale, Curio Collection by Hilton","source":"https://www.cliffroselodge.com/","accessed":"2026-10-03","si":["romance","hiking","wellness","senior"],"booking_route":"Hilton''s reservation system via the own website, or Reservations@cliffroselodge.com","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":23,"blurb":"281 Zion Park Blvd, Springdale - \"only steps from the entrance of Zion National Park\" on the Virgin River: 12 room categories from Riverside rooms to a Grand View Villa, the Anthera restaurant, the Five Petals spa, \"24-hour concierge and room service\". (435) 772-3234."},{"name":"The Red Cliffs Lodge Zion, a Tribute Portfolio Hotel","source":"https://greaterzion.com/accommodations/the-red-cliffs-lodge-zion/","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":24,"blurb":"792 Zion Park Boulevard, Springdale: 132 rooms, listed by Greater Zion as \"a tribute portfolio hotel\" under Marriott, including king suites with sofa beds. (435) 627-5280. Marriott''s own page was not fetched."},{"name":"TownePlace Suites St. George","source":"https://greaterzion.com/accommodations/towneplace-suites/","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"published","wells":["stay"],"draw_rank":25,"blurb":"251 S 1470 E, St. George: an 85-room Marriott hotel in the St. George Area, \"book at marriott.com\" or (435) 986-9955 (Greater Zion listing; Marriott''s own page was not fetched)."},{"name":"Best Western Plus Zion West","source":"https://greaterzion.com/accommodations/best-western-plus-zion-west/","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"bestwestern.com or (435) 635-0277","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"44 W 500 N, La Verkin: 69 rooms, \"20 miles away before the world famous Zion National Park\", with complimentary breakfast, a seasonal outdoor pool, hot tub, EV charging, and pets for an additional fee. (435) 635-0277."},{"name":"Horizon Kitchen + Spirits","source":"https://www.sandhollowresort.com/","accessed":"2026-10-03","si":["culinary","golf"],"booking_route":"not read","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":27,"blurb":"At Sand Hollow Resort, Hurricane: \"casual dining with a panoramic view\", plus in-room dining for resort guests."},{"name":"Zion Canyon Brew Pub","source":"https://www.zionbrewery.com/","accessed":"2026-10-03","si":["culinary","entertainment"],"booking_route":"walk-in (no booking method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":28,"blurb":"95 Zion Park Blvd, Springdale: Zion Canyon Brewery''s brewpub near the park entrance, small-batch ales with \"made-from-scratch pub fare\" and live music; its Station II Bar taproom is at 142 N Main St, St. George. 435-522-1360."},{"name":"Bit and Spur Restaurant and Saloon","source":"https://www.bitandspur.com/","accessed":"2026-10-03","si":["culinary","romance","family"],"booking_route":"Toast online reservations from the own site","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":29,"blurb":"1212 Zion Park Boulevard, Springdale: open \"7 days a week. 5:00 - 9:30PM\" with a late-night menu, a wine list, a kids'' menu and a taco truck; online reservations via Toast. (435) 772-3498."},{"name":"Oscar''s Cafe","source":"https://www.oscarscafe.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (no booking method read)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":30,"blurb":"948 Zion Park Blvd, Springdale, \"at the mouth of Zion National Park\": breakfasts (pancakes, omelets, breakfast burritos) and lunch and dinner, best known for its hamburgers."},{"name":"The Painted Pony","source":"https://www.painted-pony.com/","accessed":"2026-10-03","si":["culinary","romance","wine"],"booking_route":"own website reservations (painted-pony.com/reservations)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"2 W St. George Blvd, Ancestor Square, St. George: \"Contemporary Seasonal Cuisine\" - duck ravioli, bison tenderloin, seared scallops, wagyu - with an extensive wine list and craft cocktails. (435) 634-1700."},{"name":"George''s Corner Restaurant & Pub","source":"https://www.georgescornerrestaurant.com/","accessed":"2026-10-03","si":["culinary","family","entertainment"],"booking_route":"walk-in, first-come first-served","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"Ancestor Square, St. George: breakfast, lunch and dinner with live music; \"OPEN 8 am - 10pm Sun - Thurs | 8 am - midnight Fri - Sat\"; first-come, first-served seating. (435) 216-7311."}],"faq":[{"q":"How much does it cost to get into Sand Hollow State Park?","a":"Utah State Parks lists \"Day-Use - UT Residents: Per vehicle (Proof of Utah residency required) $25\", \"Non-Resident Day Use: Per vehicle (no senior discount) $35\", \"Senior Day-Use - UT Residents: Seniors 65+ ... $10\" and \"Walk In Fee: Per person $5\".","source":"https://stateparks.utah.gov/parks/sand-hollow/park-fees/","accessed":"2026-10-03"},{"q":"Can you camp at Sand Hollow State Park?","a":"Yes. The park has Westside (\"50 sites\", full hookups, $50), Lakeview (\"30 sites\", $45-$50), Sand Pit (\"22 sites total\"), Beachside (4 back-in electric sites, $55) and Primitive Beach Camping (\"$30.00 / night per vehicle\"), plus two cottages that sleep up to 6, booked through ReserveAmerica.","source":"https://stateparks.utah.gov/parks/sand-hollow/camping-lodging/","accessed":"2026-10-03"},{"q":"Can you swim at Sand Hollow State Park?","a":"Yes - the park lists \"Beach access, boating, camping, diving ... swimming, waterskiing\" among its activities. Before swimming, the park points visitors to its harmful-algae monitoring page for current \"Algae Conditions\" at the reservoir.","source":"https://stateparks.utah.gov/parks/sand-hollow/current-conditions/","accessed":"2026-10-03"},{"q":"Can you bring dogs to Sand Hollow State Park?","a":"Yes: \"Pets must be leashed at all times\" and may not be left in vehicles. Pets are allowed in Cottage 1 but not Cottage 2.","source":"https://stateparks.utah.gov/parks/sand-hollow/","accessed":"2026-10-03"},{"q":"Can you rent kayaks at Sand Hollow State Park?","a":"Yes, through the park''s concessionaire Sand Hollow Rentals: \"ATV''s, UTV''s, kayaks, paddle boards and more for those of all ages, shapes and sizes!\" (sandhollowrentals.com). Its own site adds \"You must be 18 years or older to rent.\"","source":"https://stateparks.utah.gov/parks/sand-hollow/rentals-food/","accessed":"2026-10-03"},{"q":"What time does Sand Hollow State Park open?","a":"\"Daylight Saving Time: 6 a.m. - 10 p.m.\"; \"Standard Time: 7 a.m. - 9 p.m.\" The visitor center is open 7 a.m. - 9 p.m.","source":"https://stateparks.utah.gov/parks/sand-hollow/","accessed":"2026-10-03"},{"q":"How big is Sand Hollow State Park?","a":"\"Park Acreage: 20,000\", of which \"Sand Mountain OHV Acreage: 15,000\"; the reservoir covers 1,322 surface acres.","source":"https://stateparks.utah.gov/parks/sand-hollow/history/","accessed":"2026-10-03"},{"q":"When did Sand Hollow State Park open?","a":"\"Opened to the public as a state park in 2003.\"","source":"https://stateparks.utah.gov/parks/sand-hollow/history/","accessed":"2026-10-03"},{"q":"Does Sand Hollow State Park have showers?","a":"Yes. Westside and Lakeview campgrounds have \"Modern restrooms with flush toilets and hot showers\", and Sand Pit has \"Modern restrooms and hot showers nearby\". Beachside has \"No restroom facilities\" and primitive beach camping has none.","source":"https://stateparks.utah.gov/parks/sand-hollow/camping-lodging/","accessed":"2026-10-03"},{"q":"How does Sand Hollow State Park compare with Quail Creek State Park?","a":"Sand Hollow''s reservoir covers 1,322 surface acres, \"nearly twice as large as the nearby Quail Creek Reservoir\", and the park adds 15,000 acres of OHV dunes. Quail Creek''s reservoir \"was completed in 1985\", covers 600 surface acres, reaches 120 feet deep and has \"some of the warmest waters in the state\".","source":"https://stateparks.utah.gov/parks/quail-creek/","accessed":"2026-10-03"}],"seo":{"meta_title":"Sand Hollow State Park: Reservoir, Dunes & Camping | TravelWell","meta_description":"Utah''s most popular state park: a 1,322-acre reservoir, 15,000 acres of Sand Mountain dunes, five campgrounds and cottages, and Zion within the ring.","slug":"sand-hollow-state-park-utah","primary_keyword":"Sand Hollow State Park","jsonld_type":"TouristDestination"},"hero":{"query":"Sand Hollow Reservoir red sandstone Utah"}}'::jsonb, 79)
