insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('rocky-mountain-colorado', '12A', 'Rocky Mountain National Park', 'United States', 'The highest continuous paved road in the US, an elk rut in the meadows, and a timed-entry permit for the busy hours', 'future', 'verified', 'mountainValley', 'The Colorado Rockies', '{"hiking","wildlife","adventure","family","glamping","parks"}', '{"alpine","wild","dramatic","adventurous"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Trail Ridge Road","source":"https://www.nps.gov/romo/planyourvisit/road_status.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"\"the highest continuous paved road in the United States\" - 48 miles one-way across the park, climbing to 12,183 feet; open to through travel on 2026-10-02, timed entry required 9 am to 2 pm; status line 970-586-1222"},{"name":"Old Fall River Road","source":"https://www.nps.gov/romo/planyourvisit/road_status.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"a 9.4-mile unpaved, one-way uphill road from Endovalley Picnic Area to 11,796 feet, open to vehicles early July to early October; closing for seasonal maintenance from October 6, 2026; vehicles over 25 feet and trailers prohibited"},{"name":"Timed Entry and Timed Entry+ Bear Lake Road (2026)","source":"https://www.nps.gov/romo/planyourvisit/timed-entry-permit-system.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"two reservation types on Recreation.gov with 2-hour entry windows; general 9 am-2 pm May 22-Oct 12, Bear Lake corridor 5 am-6 pm May 22-Oct 18; next-day releases at 7 pm MDT; a non-refundable $2 processing fee"},{"name":"Bear Lake Road and the Bear Lake Shuttle","source":"https://www.nps.gov/romo/planyourvisit/shuttle-buses-and-public-transit.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"a 9.2-mile paved road climbing from 8,200 to 9,475 feet, open year-round; free Bear Lake shuttle May 22-October 18, 6:30 am to 7:30 pm, every 10-15 minutes, stopping at Park & Ride, Bierstadt Lake, Glacier Gorge and Bear Lake"},{"name":"Hiker Shuttle from Estes Park","source":"https://www.nps.gov/romo/planyourvisit/shuttle-buses-and-public-transit.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"from the Estes Park Visitor Center to the Park & Ride, daily May 22-September 7 and weekends only September 12-October 18; $2 per reservation (up to 4 tickets) on Recreation.gov, plus a park entrance pass"},{"name":"Bear Lake to Nymph, Dream and Emerald Lakes","source":"https://www.nps.gov/romo/planyourvisit/trail_conditions.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"the chain of lakes above Bear Lake; NPS report of August 21, 2026: dry to Nymph Lake, with \"areas that are wet and muddy near Dream Lake\""},{"name":"Bear Lake Nature Trail","source":"https://www.nps.gov/romo/planyourvisit/trail_conditions.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"the loop at the end of Bear Lake Road; NPS report of August 21, 2026: \"mostly dry. There could be areas with puddles or that are muddy\""},{"name":"Glacier Gorge: Alberta Falls, Mills Lake, The Loch, Black Lake","source":"https://www.nps.gov/romo/planyourvisit/hiking.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"the Glacier Gorge trail system; the Glacier Gorge Trailhead and parking close September 28-October 1 and October 5-8, 2026 for erosion repair (open October 2-4); use Bear Lake Trailhead, 0.4 miles from Glacier Gorge Junction"},{"name":"Longs Peak and Chasm Lake","source":"https://www.nps.gov/romo/planyourvisit/longs_peak_conditions_report.htm","accessed":"2026-10-02","si":["expedition"],"tier_absent_reason":"not-sold","blurb":"the park''s mountaineering objective via the Keyhole Route; NPS, September 23, 2026: \"Fall has arrived on Longs Peak and the environment is transitioning to winter conditions\" and the route is \"a true mountaineering route and a serious undertaking this time of year\""},{"name":"Sprague Lake Trail","source":"https://www.nps.gov/romo/planyourvisit/physical-mobility.htm","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"0.8 mile of packed gravel, wood bridge and dirt with benches, a fishing pier and \"Stunning views of the Continental Divide\"; electric mobility devices permitted"},{"name":"Coyote Valley Trail, Kawuneeche Valley","source":"https://www.nps.gov/romo/planyourvisit/trail_conditions.htm","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"a west-side nature trail permitting electric mobility devices; NPS report: \"Enjoy views of the Colorado River and the Kawuneeche Valley\""},{"name":"Lily Lake Trail","source":"https://www.nps.gov/romo/planyourvisit/physical-mobility.htm","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"one of three trails the NPS names as permitting electric OPDMDs used as assistive devices"},{"name":"Cub Lake and Gem Lake trails","source":"https://www.nps.gov/romo/planyourvisit/trail_conditions.htm","accessed":"2026-10-02","si":["hiking"],"tier_absent_reason":"not-sold","blurb":"two named lower-elevation hikes; NPS reports of August 19-20, 2026 describe Cub Lake as \"clear and dry\" and Gem Lake as \"mostly dry\" with wet, muddy places"},{"name":"Alpine Ridge Trail and the Alpine Visitor Center","source":"https://www.nps.gov/romo/planyourvisit/trail_conditions.htm","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"a tundra trail at the high point of the Trail Ridge drive; the NPS asks visitors to \"Stay on the designated trail and do not cross any ropes to help protect fragile alpine plants\""},{"name":"Elk rut in the meadows (September-October)","source":"https://www.nps.gov/romo/planyourvisit/area_closures.htm","accessed":"2026-10-02","si":["wildlife"],"tier_absent_reason":"not-sold","blurb":"peak elk viewing during the mating season; meadow closures September 1-October 31 in Horseshoe Park, Moraine Park, Upper Beaver Meadows, Harbison and Holzwarth meadows, 5 pm to 10 am; NPS minimum distance 75 feet for elk"},{"name":"Sheep Lakes and Horseshoe Park bighorn sheep","source":"https://www.nps.gov/romo/planyourvisit/wildlife_view.htm","accessed":"2026-10-02","si":["wildlife"],"tier_absent_reason":"not-sold","blurb":"bighorn \"commonly seen near Sheep Lakes and Horseshoe Park from May through mid-August\"; 66 mammal and 280 bird species parkwide; 120 feet minimum from moose and bears"},{"name":"Wilderness overnight backpacking","source":"https://www.nps.gov/romo/planyourvisit/wilderness-overnight-backpacking.htm","accessed":"2026-10-02","si":["expedition"],"tier_absent_reason":"not-sold","blurb":"summer permits reserved on Recreation.gov (opened March 1, 2026), winter permits first-come, first-served; $10 per permit; \"All wilderness permits & dashtags MUST be picked up in person\" in Estes Park or Grand Lake"},{"name":"Glacier Creek Stables (in park)","source":"https://www.nps.gov/romo/planyourvisit/horses.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"\"One stable is located within the park: Glacier Creek Stables\", typically open May through October"},{"name":"Snow Mountain Ranch Yurt Village, Granby (YMCA of the Rockies)","source":"https://www.ymcarockies.org/stay/campgrounds-and-yurts","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"hilltop yurts for up to 6 plus 2 on an outside tent pad, with microwave, mini-fridge, linens, Wi-Fi and electricity, open May through late September; plus a full-hookup RV and tent campground; 1101 Co Rd 53, Granby"},{"name":"Winding River Resort, Grand Lake","source":"https://www.windingriverresort.com/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"covered wagons, camper cabins, rustic cabins, lodge rooms, RV and tent sites and guest horse camping at 1447 County Road 491, beside the park''s west entrance near the Kawuneeche Visitor Center; family-operated since 1972"},{"name":"Jellystone Park of Estes","source":"https://www.visitestespark.com/listings/jellystone-park-of-estes/1539/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"cabins and cottages, 30 hookup RV sites and 40 tent sites at 5495 Hwy 36, Estes Park, May through October, with pool and playground; Visit Estes Park calls it \"the closest thing Estes Park has to\" glamping"},{"name":"Sun Outdoors Rocky Mountains, Grand Lake area (listing only)","source":"https://gograndlake.com/listing/sun-outdoors-rocky-mountains/53/","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"listed by the Grand Lake chamber as a campground with RV sites, cabins and glamping options; the operator''s own site returned 403 and the chamber listing''s address and phone appear to be the visitor center''s"},{"name":"People of the Honey, Ward (Hipcamp listing)","source":"https://www.hipcamp.com/en-US/land/colorado-people-of-the-honey-lz9h07dx","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"an off-grid 5-acre sanctuary at 9,000 feet with a 24-foot ceremonial tipi sleeping 6, an off-grid cabin and tent sites; listed as about 35 miles from Estes Park and RMNP"},{"name":"Creekside Paradise, near Boulder (Hipcamp listing)","source":"https://www.hipcamp.com/en-US/land/colorado-creekside-paradise-1-qeoh0nlx","accessed":"2026-10-02","si":["glamping"],"tier_absent_reason":"not-sold","blurb":"a 42-acre creekside property with a Mongolian yurt, a bell tent and primitive tent sites; listed as about 45 minutes to the park''s main entrance; no potable water, power or cell service"},{"name":"Moraine Park Campground (NPS)","source":"https://www.nps.gov/romo/planyourvisit/camping.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Recreation.gov, up to 6 months ahead (some sites short-term release); summer season May 21-October 19, 2026; the only in-park campground open in winter, first come, first served; 14 accessible sites"},{"name":"Glacier Basin Campground (NPS)","source":"https://www.nps.gov/romo/planyourvisit/camping.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Recreation.gov, up to 6 months ahead; on the Moraine Park shuttle line; the NPS page lists it as \"closed for the 2026/2027 Winter Season\""},{"name":"Aspenglen Campground (NPS)","source":"https://www.nps.gov/romo/planyourvisit/camping.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Recreation.gov, up to 6 months ahead; 2026 summer season May 21 to September 28"},{"name":"Timber Creek Campground (NPS, west side)","source":"https://www.nps.gov/romo/planyourvisit/camping.htm","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"Recreation.gov, up to 6 months ahead; 2026 summer season May 21 to October 5"},{"name":"Longs Peak Campground (NPS)","source":"https://www.nps.gov/romo/planyourvisit/camping.htm","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"first-come, first-served and tents only; \"typically opens in early July and closes in early September\""},{"name":"Estes Park / Rocky Mountain National Park KOA Holiday (listing only)","source":"https://koa.com/states-provinces/colorado/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"named on KOA''s Colorado list; koa.com''s campground page returned 403, so accommodations, season and address were not confirmed"},{"name":"Grand Lake / Rocky Mountain National Park KOA Journey","source":"https://www.visitgrandcounty.com/listings/elk-creek-campground-rv-park/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"RV sites and cabins at 143 County Road 48, Grand Lake (the former Elk Creek Campground & RV Park), with camp store, rec room, laundry and dump station"},{"name":"Kirks Flyshop, Estes Park","source":"https://www.kirksflyshop.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"since 2002 at 230 E. Elkhorn Ave: guided fly fishing, RMNP hiking, backpacking, llama trekking and Longs Peak climbs, gear rentals and Lake Estes charters"},{"name":"Estes Park Mountain Shop","source":"https://www.estesparkmountainshop.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"since 1986: 18,000 sq ft of gear, summer, camping, winter and adaptive equipment rentals, guided climbing, snowshoeing and hiking, and an indoor climbing gym; open 8 am-8 pm daily"},{"name":"National Park Gateway Stables, Fall River Entrance","source":"http://www.skhorses.com/national-park-gateway-stables","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"at the edge of the park by the Fall River Visitor Center; \"All rides venture into Rocky Mountain National Park\", from pony rides to full-day rides; weight limits apply"},{"name":"Sombrero Stables, Estes Park","source":"https://www.sombrero.com/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"\"Riding for the Brand Since 1958\" at 1895 Big Thompson Ave: 30-minute to 2-hour rides, a Cowboy Experience and private rides"},{"name":"Rapid Transit Rafting, Estes Park","source":"https://www.rapidtransitrafting.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"half-day Cache la Poudre and full-day Colorado River trips (Class II-III, ages 7+), May 20 to early September, with round-trip transport from 161 Virginia Dr"},{"name":"Green Jeep Tours, Estes Park","source":"https://www.greenjeeptour.com/","accessed":"2026-10-02","si":["wildlife"],"tier_absent_reason":"not-sold","blurb":"open-jeep scenic and wildlife tours of Rocky Mountain National Park and the Estes Park region from 157 Moraine Ave"},{"name":"Wildside 4x4 Tours, Estes Park","source":"https://www.wildside4x4tours.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"year-round National Park tours and May 15-December 1 off-road tours in Roosevelt National Forest under a Forest Service special use permit"},{"name":"Estes Park Trolleys","source":"https://www.estesparktrolleys.com/","accessed":"2026-10-02","si":["senior"],"tier_absent_reason":"not-sold","blurb":"about 3-hour trolley tours through RMNP with walking and photo stops, plus Stanley Hotel tours, in 1920s-style enclosed trolleys"},{"name":"Rocky Mountain Conservancy Field Institute","source":"https://rmconservancy.org/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"the park''s nonprofit partner, running expert-led classes, fall elk ecology tours, custom tours and bus tours in the park"},{"name":"Never Summer Mountain Products, Grand Lake","source":"https://www.neversummermtn.com/","accessed":"2026-10-02","si":["adventure"],"tier_absent_reason":"not-sold","blurb":"independent and family-owned since 1982 at 919 Grand Ave: summer kayak, SUP and bear-canister rentals; winter backcountry ski and snowshoe rentals"},{"name":"Rocky Mountain Stables, Snow Mountain Ranch","source":"https://www.rockymountainstables.com/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"one- and two-hour guided rides with Continental Divide and park views, plus winter rides and sleigh rides, at Snow Mountain Ranch near Granby; ages 8+, 250 lb limit"},{"name":"Estes Park Aerial Tramway","source":"http://estestram.com/","accessed":"2026-10-02","si":["family"],"tier_absent_reason":"not-sold","blurb":"a 2,630-foot ride to the 8,708-foot summit of Prospect Mountain with views of the park, Longs Peak and the Continental Divide; open daily 9 am-7 pm through November 1, 2026"},{"name":"The Stanley Hotel, Estes Park","source":"https://www.stanleyhotel.com/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"the 1909 landmark at 333 E Wonderview Ave whose Stephen King connection made it famous; historic hotel tours"},{"name":"Grand Lake and Grand Lake Lodge","source":"https://gograndlake.com/things-to-do/lakes/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"Colorado''s largest natural lake, more than 500 acres, \"formed by glaciers\"; the historic Grand Lake Lodge sits beside the park at 15500 US-34"},{"name":"Rocky Mountain Repertory Theatre, Grand Lake","source":"https://rockymountainrep.com/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"professional musical theatre at 800 Grand Avenue; 2026 season includes a 70s Beehive musical from September 4 and Boulder Ballet on October 10"},{"name":"Estes Park fall festivals: Elk Fest and Autumn Gold","source":"https://www.visitestespark.com/events-calendar/fall-events/","accessed":"2026-10-02","si":["culture"],"tier_absent_reason":"not-sold","blurb":"Elk Fest brings \"vendors, live music, food trucks, and bugling contests in downtown Estes Park\"; Autumn Gold celebrates \"beer, brats, and music\"; 2026 dates not shown on the page fetched"},{"name":"Bird & Jim, Estes Park","source":"https://www.birdfamilyrestaurants.com/bird-jim","accessed":"2026-10-02","si":["culinary","wine","romance","group"],"booking_route":"phone (970) 586-9832; parties up to 20","tier_absent_reason":"not-sold","blurb":"Seasonal American restaurant at 915 Moraine Ave since 2016, menus built on local ingredients, with a sommelier-curated wine list holding the Wine Spectator Award of Excellence every year since 2020."},{"name":"Snowy Peaks Winery, Estes Park","source":"https://www.snowypeakswinery.com/","accessed":"2026-10-02","si":["wine","culinary","romance"],"booking_route":"online reservations via own site (recommended)","tier_absent_reason":"not-sold","blurb":"Winery at 292 Moraine Ave fermenting Colorado-grown grapes (Merlot, Syrah, Viognier, Riesling) with tasting flights and Colorado artisan cheeses, chocolates and charcuterie; daily 11:30 am-7:30 pm."},{"name":"The Whiskey Vault and MacGregor Chophouse at the Stanley Hotel, Estes Park","source":"https://www.stanleyhotel.com/dining","accessed":"2026-10-02","si":["culinary","romance","culture","wine"],"booking_route":"not observed (phone +1 970 577-4000 listed)","tier_absent_reason":"not-sold","blurb":"The Stanley''s five dining venues include the Whiskey Vault, billed as Colorado''s largest selection of whiskeys and single malt scotches, and the MacGregor Chophouse steakhouse, plus Post Beer & Chicken and the 217 Wine Bar."},{"name":"Elkins Tasting Room and Mercantile, Estes Park","source":"https://www.visitestespark.com/blog/post/estes-parks-craft-beverage-boom/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Distillery tasting room at 137 E. Elkhorn Ave whose original Elkins Colorado Whiskey took silver at the 2016 Denver International Spirits Competition; per the Visit Estes Park bureau article."},{"name":"Hogback Distillery Store & Tasting Room, Estes Park","source":"https://www.visitestespark.com/blog/post/estes-parks-craft-beverage-boom/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"not observed (phone (720) 357-9320 listed)","tier_absent_reason":"not-sold","blurb":"Boulder-based microdistillery pouring Scotch-style whisky in several expressions at 857 Moraine Ave; per the Visit Estes Park bureau article."},{"name":"Avant Garde Aleworks, Estes Park","source":"https://www.avantgardealeworks.com/","accessed":"2026-10-02","si":["culinary","group","family"],"booking_route":"walk-in only; rental packages for large groups","tier_absent_reason":"not-sold","blurb":"Family-founded brewery at 920 Dunraven St pouring European-inspired beers and house seltzers, with rotating food trucks, live music and vinyl nights; dog- and family-friendly."},{"name":"Rock Cut Brewing Company, Estes Park","source":"https://rockcutbrewing.com/","accessed":"2026-10-02","si":["culinary","group","hiking"],"booking_route":"walk-in; phone 970-586-7300","tier_absent_reason":"not-sold","blurb":"Downtown brewery at 390 W Riverside Drive at the base of Prospect Mountain, with patio, food, crowlers to go and Tuesday trivia; daily 11 am-10 pm."},{"name":"Lumpy Ridge Brewing Co., Estes Park","source":"https://www.visitestespark.com/blog/post/estes-parks-craft-beverage-boom/","accessed":"2026-10-02","si":["culinary","group"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Handcrafted beers from traditional to adventurous, brewed in a former gas station at 531 S. Saint Vrain Ave; per the Visit Estes Park bureau article."},{"name":"The Barrel, Estes Park","source":"https://www.visitestespark.com/blog/post/estes-parks-craft-beverage-boom/","accessed":"2026-10-02","si":["culinary","group","wine"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Open-air craft beer, wine and spirits garden at 116 E. Elkhorn Ave with more than 60 rotating taps; per the Visit Estes Park bureau article."},{"name":"Spirit Hound Distillers, Lyons","source":"https://spirithounds.com/","accessed":"2026-10-02","si":["culinary","group","culture"],"booking_route":"not observed for tours (private party reservations offered); phone (303) 823-5696","tier_absent_reason":"not-sold","blurb":"Distillery at 4196 Ute Hwy making American Single Malt Whisky from locally harvested and malted barley; London International Spirits Competition ''Whisky of the Year'' 2022 and 2024; tours, cocktail classes and food trucks."},{"name":"Marigold Lyons","source":"https://www.marigoldlyons.com/","accessed":"2026-10-02","si":["culinary","wine","romance"],"booking_route":"OpenTable","tier_absent_reason":"not-sold","blurb":"Family-owned bistro at 405 Main St cooking Northern Italian and Southern French cuisine, a James Beard Best Chef Mountain semifinalist and on Wine Enthusiast''s best wine restaurants list; Wednesday to Sunday dinners."},{"name":"Oskar Blues original location, Lyons","source":"https://www.lyonscolorado.com/761/restaurants-in-lyons","accessed":"2026-10-02","si":["culinary","group","culture"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"The original Oskar Blues location at 303 Main St for a meal and hand-crafted beers; per the Lyons town visitor listing."},{"name":"The Historic Rapids Restaurant, Grand Lake","source":"https://gograndlake.com/restaurants-dining/","accessed":"2026-10-02","si":["culinary","romance"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Gourmet dining with ''elegant dishes'' at the Rapids Lodge in Grand Lake; per the Grand Lake visitor bureau dining page."},{"name":"Mountain Market, Grand Lake","source":"https://gograndlake.com/restaurants-dining/","accessed":"2026-10-02","si":["culinary","family","hiking"],"booking_route":"not observed","tier_absent_reason":"not-sold","blurb":"Market for assembling picnic provisions or buying prepared food; per the Grand Lake visitor bureau dining page."}],"faq":[{"q":"Do I need a reservation to enter Rocky Mountain National Park in 2026?","a":"From May 22, a timed entry reservation is required between 9 a.m. and 2 p.m. through October 12, 2026, and for the Bear Lake Road Corridor between 5 a.m. and 6 p.m. through October 18, 2026. Entry outside those hours, on foot or bicycle, or with a campground or wilderness reservation is exempt.","source":"https://www.nps.gov/romo/planyourvisit/timed-entry-permit-system.htm","accessed":"2026-10-02"},{"q":"How do I get a timed entry reservation?","a":"On Recreation.gov. Blocks were released on May 1 at 8 a.m. MDT and then on the first of each month; additional reservations are released at 7 p.m. MDT the night before the arrival date. The only cost is a non-refundable $2 processing fee.","source":"https://www.nps.gov/romo/planyourvisit/timed-entry-permit-system.htm","accessed":"2026-10-02"},{"q":"Is Trail Ridge Road open?","a":"On October 2, 2026 the NPS stated that Trail Ridge Road is open to through travel. It is a seasonal road; the recorded status line is 970-586-1222.","source":"https://www.nps.gov/romo/planyourvisit/road_status.htm","accessed":"2026-10-02"},{"q":"How much does it cost to enter Rocky Mountain National Park?","a":"$30 per private vehicle for one day or $35 for seven days; $15 or $20 per person on foot or bicycle (16+); $70 for the park''s annual pass. Non-US residents 16 and older pay an additional $100 unless admitted with an annual or America the Beautiful pass.","source":"https://www.nps.gov/romo/planyourvisit/fees.htm","accessed":"2026-10-02"},{"q":"When is the elk rut, and are any areas closed?","a":"The NPS names September-October as peak elk viewing during the mating season. From September 1 to October 31, off-trail foot travel is prohibited 5 p.m. to 10 a.m. in Horseshoe Park, Moraine Park, Upper Beaver Meadows, Harbison Meadow and Holzwarth Meadow.","source":"https://www.nps.gov/romo/planyourvisit/area_closures.htm","accessed":"2026-10-02"},{"q":"How do I reserve a campsite in the park?","a":"Moraine Park, Glacier Basin, Aspenglen and Timber Creek are reserved on Recreation.gov up to six months ahead, with some short-term releases. Longs Peak Campground is first-come, first-served and tents only. In winter, Moraine Park is the only campground open, first come, first served.","source":"https://www.nps.gov/romo/planyourvisit/camping.htm","accessed":"2026-10-02"},{"q":"Is there a shuttle to Bear Lake?","a":"Yes. The free Bear Lake shuttle runs May 22 to October 18, 6:30 a.m. to 7:30 p.m., every 10-15 minutes from the Park & Ride. A Hiker Shuttle from the Estes Park Visitor Center needs a $2 Recreation.gov reservation and runs weekends only from September 12 to October 18.","source":"https://www.nps.gov/romo/planyourvisit/shuttle-buses-and-public-transit.htm","accessed":"2026-10-02"}],"seo":{"meta_title":"Rocky Mountain National Park: Timed Entry, Trail Ridge Road & Estes Park | TravelWell","meta_description":"How 2026 timed entry works, when Trail Ridge Road and the elk rut happen, which campgrounds to reserve, and where to stay from Estes Park to Grand Lake.","slug":"rocky-mountain-national-park-colorado","primary_keyword":"Rocky Mountain National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Rocky Mountain National Park, Colorado"}}'::jsonb, 80),
